# =====================================================================
# МЕЛОЧИ
# =====================================================================
_BLOCKS = " ▁▂▃▄▅▆▇█"


def spark(v):
    v = np.asarray(v, dtype=float)
    lo, hi = v.min(), v.max()
    if hi - lo < 1e-12:
        return "─" * len(v)
    idx = np.clip(np.round((v - lo) / (hi - lo) * 8).astype(int), 0, 8)
    return "".join(_BLOCKS[i] for i in idx)


def _f(x, fmt, width=None, dash='—'):
    try:
        ok = x is not None and np.isfinite(x)
    except TypeError:
        ok = False
    s = f"{x:{fmt}}" if ok else dash
    return f"{s:>{width}}" if width else s


def _jsonable(x):
    if isinstance(x, dict):
        return {str(k): _jsonable(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)):
        return [_jsonable(v) for v in x]
    if isinstance(x, np.ndarray):
        return _jsonable(x.tolist())
    if isinstance(x, (np.bool_, bool)):
        return bool(x)
    if isinstance(x, np.integer):
        return int(x)
    if isinstance(x, (np.floating, float)):
        return None if not np.isfinite(x) else float(x)
    return x


class _Tee:
    """Печать в вывод и в лог-файл на Drive. Файл НЕ держится открытым: текст копится
       в памяти и дописывается open/write/close раз в SYNC_S секунд (и при закрытии).
       Ошибка записи лога никогда не роняет прогон."""
    SYNC_S = 5.0

    def __init__(self, path, stream):
        self.path = path
        self.stream = stream
        self.buf = []
        self.t_last = time.time()
        self.warned = False

    def _sync(self):
        if not self.buf:
            return
        text = ''.join(self.buf)
        try:
            with open(self.path, 'a', encoding='utf-8') as fh:
                fh.write(text)
            self.buf = []
        except OSError as e:
            if not self.warned:
                self.stream.write(f"\n⚠️ лог-файл недоступен ({e}) — коплю в памяти, повторю позже\n")
                self.warned = True
        self.t_last = time.time()

    def write(self, s):
        self.stream.write(s)
        self.buf.append(s)
        if time.time() - self.t_last >= self.SYNC_S:
            self._sync()

    def flush(self):
        self.stream.flush()
        if time.time() - self.t_last >= self.SYNC_S:
            self._sync()

    def close(self):
        self._sync()

    def __getattr__(self, name):            # encoding, isatty и прочее — от настоящего потока
        return getattr(self.stream, name)

@contextlib.contextmanager
def tee_to(path):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    keep = sys.stdout
    tee = _Tee(path, keep)
    sys.stdout = tee
    try:
        yield
    finally:
        sys.stdout = keep
        tee.close()


def valid_starts(r, L):
    bad = ~np.isfinite(r)
    cs = np.concatenate([[0], np.cumsum(bad)])
    n = len(r) - L + 1
    if n <= 0:
        return np.empty(0, dtype=np.int64)
    return np.where(cs[L:L + n] - cs[:n] == 0)[0].astype(np.int64)


def tf_minutes(tf):
    """'5M' -> 5, '1H' -> 60, '4H' -> 240, '1D' -> 1440."""
    tf = tf.upper()
    n, unit = int(tf[:-1]), tf[-1]
    return n * {'M': 1, 'H': 60, 'D': 1440}[unit]


# =====================================================================
# ДАННЫЕ: ряды из ноутбука SMC_Data
# =====================================================================
PRICE_NAMES = {'close': 'close', 'hl2': 'HL/2', 'hlc3': 'HLC/3', 'multi': 'close+HL/2+HLC/3',
               'multi_g': 'close+HL/2+HLC/3+диапазон', 'multi_gc': 'close+HL/2+HLC/3+диапазон+положение close'}
MULTI_PRICES = ('hl2', 'hlc3')    # v4.6: каналы средних цен у price 'multi' (канал 0 — close)
MULTI_KINDS = ('multi', 'multi_g', 'multi_gc')  # v5.6: несколько каналов одной сетью; у 'multi_g' — плюс диапазон бара
N_PATH = 1 + len(MULTI_PRICES)      # v5.6: каналы-пути (close, HL/2, HLC/3); дальше — каналы-уровни (диапазон бара)
# v5.7: каналы-уровни по цене бара: 'multi_g' — диапазон g; 'multi_gc' — диапазон g и положение close в баре o.
# LEVEL_SIGNED — знаковый ли уровень (по месту после N_PATH): g от зеркала бара не меняется, o = (close − HL/2) / норм.
# переворачивается вместе с баром (и вместе с ориентацией формы)
N_LEVEL = {'multi_g': 1, 'multi_gc': 2}
LEVEL_SIGNED = (False, True)
LEVEL_KINDS = ('multi_g', 'multi_gc')       # цены с диапазоном бара (нужен smc_range)
LVL_EPS = 0.1                               # v5.7, lvl_log: log(g / делитель окна + 0.1) — бар без движения не уходит в −∞
SIDE_DAYS = (30, 7, 1)             # v4.5: нормы |r| для боковых входов — EMA за 30 / 7 / 1 сутки
# v6.0, правило ничьей ориентации (как в экспорте MRI): форма переворачивается, только если конец центрированного пути
# close < −ORIENT_EPS · делитель окна. Без запаса на сетке цены конец пути бывает ровно 0, и знак решал шум float32 (на GPU —
# разный при разной пачке), причём to_shapes и side_feats могли разойтись. 0 — старое правило (переворот при конце < 0)
ORIENT_EPS = 1e-4
ORIENT = True          # v6.7: форма окна ориентируется «концом вверх» (True — как всегда); False — абсолютное направление: окно и
                       # знаковые боковые входы как есть (сеть видит, вверх рынок шёл или вниз). На прогон ставит run_one — orientation()


@contextlib.contextmanager
def orientation(on=True):
    """v6.7: на время блока — ориентация формы окна (True) или абсолютное направление (False) в to_shapes и side_feats."""
    global ORIENT
    keep = ORIENT
    ORIENT = bool(on)
    try:
        yield
    finally:
        ORIENT = keep


class SeriesData:
    """Все ряды одного ТФ в одном массиве: TRAINING и VALIDATION каждого ассета подряд,
       между кусками прокладки из NaN — окно через прокладку не пройдёт. Позиция окна —
       индекс его первого бара в этом массиве.
       v4.5: price — цена бара, на которой смотрит модель: 'close' (ряд SMC_Data как есть) или средняя цена
       бара 'hl2' | 'hlc3' (приращения Δp_t = e_t − d_{t−1} из TrendyCoins_SMC_Prices; self.r — они, close-ряд
       остаётся в self.rc). Окна и знаки суррогатов проверки — те же, что у close.
       v4.6: price 'multi' — self.r = close (окна, полы, боковые входы — по close), плюс каналы HL/2 и HLC/3:
       окно — (n, 3, L), см. gw / flip_multi.
       v5.6: price 'multi_g' — то же плюс канал «диапазон бара» g (smc_range, TrendyCoins_SMC_Range): окно — (n, 4, L).
       v5.7: price 'multi_gc' — плюс канал «положение close в баре» o = (close − HL/2) / норм. = −d_hl2 (smc_prices, тот же
       делитель, что у r): окно — (n, 5, L). Вместе с шагом close и диапазоном — свеча целиком (high, low, close от прошлого
       close)."""
    PAD = 256

    def __init__(self, assets, tf, N, tune_start, price='close'):
        if price not in PRICE_NAMES:
            raise ValueError(f"🍆 АЙ, ОШИБКА! цена бара '{price}' — есть {', '.join(PRICE_NAMES)}")
        self.tf, self.N, self.price = tf.upper(), N, price
        self.tune_ns = pd.Timestamp(tune_start).value
        rr, tt, pp, ss, ee, dd, cc, gg, oo = [], [], [], [], [], [], [], [], []
        self.series, off = [], 0
        for i, a in enumerate(assets):
            path = data_path(f"smc_series_{a}_{self.tf}_N{N}.npz")
            if not os.path.isfile(path):
                raise FileNotFoundError(f"🍆 АЙ, ОШИБКА! нет {path} — сначала TrendyCoins_SMC_Data")
            d = np.load(path, allow_pickle=False)
            s = {'asset': a, 'meta': json.loads(str(d['meta'])), 'floors': {}, 'probe': {},
                 'bank': {}, 'off': {}, 'fin': {}, 'n': {}, 'bars': {}}
            px = self._load_prices(a, d) if price != 'close' else None
            pxs = MULTI_PRICES if price in MULTI_KINDS else (price,)
            gx = self._load_range(a, d) if price in LEVEL_KINDS else None     # v5.6: диапазон бара
            # v6.0: сырые OHLC (None — нет файла); v6.1: NT_KEEP = () — столбцы истории не нужны, файл не читается
            bx = None if NT_KEEP == () else self._load_bars(a, d)
            for key, code in (('tr', 0), ('va', 1)):
                r = d[f'r_{key}'].astype(np.float32)
                s['off'][key], s['n'][key] = off, len(r)
                s['fin'][key] = d[f'fin_{key}'].astype(np.int64)
                s['bars'][key] = None if bx is None else {k_: bx[f'{k_}_{key}'] for k_ in
                                                         ('o', 'h', 'l', 'c', 'pre_o', 'pre_h', 'pre_l', 'pre_c')}
                for arr, fill, lst in ((r, np.nan, rr), (d[f't_{key}'], -1, tt),
                                       (np.full(len(r), code, np.int8), -1, pp),
                                       (np.full(len(r), i, np.int16), -1, ss)):
                    lst.append(arr)
                    lst.append(np.full(self.PAD, fill, dtype=arr.dtype))
                # v5.5: close бара (для абсолютной волы — признак absv); в старых файлах его может не быть
                cl = d[f'close_{key}'].astype(np.float64) if f'close_{key}' in d.files else None
                cc.append(cl if cl is not None and len(cl) == len(r) else None)
                cc.append(np.full(self.PAD, np.nan))
                if gx is not None:
                    gg.append(gx[f'g_{key}'].astype(np.float32))
                    gg.append(np.full(self.PAD, np.nan, dtype=np.float32))
                if px is not None:
                    # e_t — сдвиг цены бара от прошлого close, d_{t−1} — сдвиг цены прошлого бара от его close
                    for j, p_ in enumerate(pxs):
                        e = px[f'e_{p_}_{key}'].astype(np.float32)
                        dv = px[f'd_{p_}_{key}'].astype(np.float32)
                        dprv = np.concatenate([px[f'd0_{p_}_{key}'].reshape(1), dv[:-1]]).astype(np.float32)
                        if len(e) != len(r):
                            raise ValueError(f"🍆 АЙ, ОШИБКА! {a}: длина сдвигов цены {len(e)} против {len(r)} у ряда")
                        if price == 'multi_gc' and p_ == 'hl2':      # v5.7: o_t = (close_t − HL/2_t) / норм. = −d_t
                            oo.append(-dv)
                            oo.append(np.full(self.PAD, np.nan, dtype=np.float32))
                        if len(ee) <= j:
                            ee.append([])
                            dd.append([])
                        for arr, lst in ((e, ee[j]), (dprv, dd[j])):
                            lst.append(arr)
                            lst.append(np.full(self.PAD, np.nan, dtype=np.float32))
                off += len(r) + self.PAD
            for k in d.files:
                if k.startswith('floor_L'):
                    s['floors'][int(k[7:])] = float(d[k])
                elif k.startswith('probe_pos_L'):
                    L = int(k[11:])
                    s['probe'][L] = (d[k].astype(np.int64), d[f'probe_X_L{L}'])
                elif k.startswith('bank_'):
                    s['bank'][k[5:]] = d[k].astype(np.float32)
            self.series.append(s)
        self.r = np.concatenate(rr)
        self.t = np.concatenate(tt)
        self.part = np.concatenate(pp)
        self.sid = np.concatenate(ss)
        self.close_px = np.concatenate(cc) if all(x is not None for x in cc) else None    # v5.5: None — нет close в npz
        self.same_fin = True
        if price in MULTI_KINDS:
            # v4.6: канал 0 — close (self.r), каналы средних цен — e − d_{t−1}; где у какого-то канала NaN — NaN и в close
            self.rc = self.r.copy()
            self.chan_e = [np.concatenate(x) for x in ee]
            self.chan_d = [np.concatenate(x) for x in dd]
            ok = np.isfinite(self.rc)
            for e_, d_ in zip(self.chan_e, self.chan_d):
                ok &= np.isfinite(e_ - d_)
            if price in LEVEL_KINDS:                          # v5.6: диапазон конечен там же, где r (TrendyCoins_SMC_Range)
                self.chan_g = np.concatenate(gg)
                ok &= np.isfinite(self.chan_g)
                self.chan_g_t = torch.from_numpy(self.chan_g).to(DEVICE)
            if price == 'multi_gc':                           # v5.7: положение close (d конечен везде, где норм. живой)
                self.chan_o = np.concatenate(oo)
                ok &= np.isfinite(self.chan_o)
                self.chan_o_t = torch.from_numpy(self.chan_o).to(DEVICE)
            self.same_fin = bool(np.array_equal(ok, np.isfinite(self.rc)))
            self.r = np.where(ok, self.rc, np.nan).astype(np.float32)
            for s in self.series:
                s['bank'] = {}                                # банк SMC_Data — только close-канал
                for key in ('tr', 'va'):
                    o = s['off'][key]
                    s['fin'][key] = np.where(np.isfinite(self.r[o:o + s['n'][key]]))[0].astype(np.int64)
            self.chan_t = [(torch.from_numpy(e_).to(DEVICE), torch.from_numpy(d_).to(DEVICE))
                           for e_, d_ in zip(self.chan_e, self.chan_d)]
        elif price != 'close':
            self.rc = self.r                                  # close-приращения (справочно)
            self.e = np.concatenate(ee[0])
            self.dprv = np.concatenate(dd[0])
            self.r = self.e - self.dprv                       # приращения цены бара (float32, как у суррогата)
            self.same_fin = bool(np.array_equal(np.isfinite(self.r), np.isfinite(self.rc)))
            for s in self.series:
                # пол делителя — по приращениям этой цены; банк и проба SMC_Data посчитаны по close
                s['floors'], s['bank'], s['probe'] = {}, {}, {}
                for key in ('tr', 'va'):
                    o = s['off'][key]
                    s['fin'][key] = np.where(np.isfinite(self.r[o:o + s['n'][key]]))[0].astype(np.int64)
            self.e_t = torch.from_numpy(self.e).to(DEVICE)
            self.dprv_t = torch.from_numpy(self.dprv).to(DEVICE)
        self.r_t = torch.from_numpy(self.r).to(DEVICE)
        # начало куска (части ряда) у каждой позиции: прошлое перед окном не берётся из соседнего куска
        seg0 = np.arange(len(self.r), dtype=np.int64)
        for s in self.series:
            for key in ('tr', 'va'):
                o = s['off'][key]
                seg0[o:o + s['n'][key]] = o
        self.seg0 = seg0
        self.seg0_t = torch.from_numpy(seg0).to(DEVICE)
        self._win, self._fin_vals = {}, {}
        self._side_arrays()
        self._nt_arrays()

    def _load_prices(self, asset, d):
        """v4.5: сдвиги цены бара из TrendyCoins_SMC_Prices; контрольная сумма ряда обязана совпасть со smc_series."""
        path = data_path(f"smc_prices_{asset}_{self.tf}_N{self.N}.npz")
        if not os.path.isfile(path):
            raise FileNotFoundError(f"🍆 АЙ, ОШИБКА! нет {path} — сначала TrendyCoins_SMC_Prices "
                                    f"(цена бара '{self.price}')")
        px = np.load(path, allow_pickle=False)
        meta = json.loads(str(px['meta']))
        for key in ('tr', 'va'):
            crc = zlib.crc32(d[f'r_{key}'].astype(np.float32).tobytes())
            if (meta.get('crc') or {}).get(key) != crc:
                raise ValueError(f"🍆 АЙ, ОШИБКА! {os.path.basename(path)} посчитан для другого ряда (CSV или "
                                 f"smc_series менялись) — перезапусти TrendyCoins_SMC_Prices")
            for p_ in (MULTI_PRICES if self.price in MULTI_KINDS else (self.price,)):
                if f'e_{p_}_{key}' not in px.files:
                    raise ValueError(f"🍆 АЙ, ОШИБКА! в {os.path.basename(path)} нет цены '{p_}'")
        return {k: px[k] for k in px.files if k != 'meta'}

    def _load_range(self, asset, d):
        """v5.6: диапазон бара g = (high − low) / норм. из TrendyCoins_SMC_Range; контрольная сумма ряда обязана совпасть
           со smc_series (файл диапазона — от того же ряда: и в DATA_DIR, и в накладке боевого обучения)."""
        path = data_path(f"smc_range_{asset}_{self.tf}_N{self.N}.npz")
        if not os.path.isfile(path):
            raise FileNotFoundError(f"🍆 АЙ, ОШИБКА! нет {path} — сначала TrendyCoins_SMC_Range (цена бара '{self.price}')")
        gx = np.load(path, allow_pickle=False)
        meta = json.loads(str(gx['meta']))
        for key in ('tr', 'va'):
            crc = zlib.crc32(d[f'r_{key}'].astype(np.float32).tobytes())
            if (meta.get('crc') or {}).get(key) != crc:
                raise ValueError(f"🍆 АЙ, ОШИБКА! {os.path.basename(path)} посчитан для другого ряда (smc_series менялся или "
                                 f"файлы из разных папок) — перезапусти TrendyCoins_SMC_Range")
            if len(gx[f'g_{key}']) != len(d[f'r_{key}']):
                raise ValueError(f"🍆 АЙ, ОШИБКА! {asset}: длина диапазона {len(gx[f'g_{key}'])} против {len(d[f'r_{key}'])} у ряда")
        return {k: gx[k] for k in gx.files if k != 'meta'}

    def _load_bars(self, asset, d):
        """v6.0: сырые OHLC баров smc_series и NT_HIST баров перед первым баром каждой части (TrendyCoins_SMC_Bars) — для
           признаков истории в барах. Контрольная сумма r обязана совпасть со smc_series, close — бит в бит с close_tr /
           close_va. Нет файла — None: признаки истории — нули, модели с ними не запустятся (check_absv)."""
        path = data_path(f"smc_bars_{asset}_{self.tf}_N{self.N}.npz")
        if not os.path.isfile(path):
            return None
        bx = np.load(path, allow_pickle=False)
        meta = json.loads(str(bx['meta']))
        out = {}
        for key in ('tr', 'va'):
            crc = zlib.crc32(d[f'r_{key}'].astype(np.float32).tobytes())
            if (meta.get('crc') or {}).get(key) != crc:
                raise ValueError(f"🍆 АЙ, ОШИБКА! {os.path.basename(path)} посчитан для другого ряда (smc_series менялся или "
                                 f"файлы из разных папок) — перезапусти TrendyCoins_SMC_Bars")
            n = len(d[f'r_{key}'])
            for k_ in ('o', 'h', 'l', 'c'):
                v, pre = bx[f'{k_}_{key}'].astype(np.float64), bx[f'pre_{k_}_{key}'].astype(np.float64)
                if len(v) != n or len(pre) < NT_HIST:
                    raise ValueError(f"🍆 АЙ, ОШИБКА! {asset}: в {os.path.basename(path)} баров {len(v)} (у ряда {n}), "
                                     f"перед частью {len(pre)} (нужно {NT_HIST})")
                out[f'{k_}_{key}'], out[f'pre_{k_}_{key}'] = v, pre[-NT_HIST:]
            if f'close_{key}' in d.files and not np.array_equal(out[f'c_{key}'], d[f'close_{key}'].astype(np.float64)):
                raise ValueError(f"🍆 АЙ, ОШИБКА! {asset}: close в {os.path.basename(path)} не совпадает с smc_series бит в бит "
                                 f"— файлы из разных выгрузок CSV, перезапусти TrendyCoins_SMC_Bars")
        return out

    def gw(self, starts, L):
        """v4.6: окна модели: (n, L) — приращения своей цены; у 'multi' — (n, 3, L): close, HL/2, HLC/3; v5.6: у 'multi_g' —
           (n, 4, L), канал 3 — диапазон бара g (уровень, не приращение); v5.7: у 'multi_gc' — (n, 5, L), канал 4 — положение
           close в баре o (знаковый уровень)."""
        W = gather(self.r_t, starts, L)
        if self.price not in MULTI_KINDS:
            return W
        chans = [W] + [gather(e_, starts, L) - gather(d_, starts, L) for e_, d_ in self.chan_t]
        if self.price in LEVEL_KINDS:
            chans.append(gather(self.chan_g_t, starts, L))
        if self.price == 'multi_gc':
            chans.append(gather(self.chan_o_t, starts, L))
        return torch.stack(chans, dim=1)

    def flip_multi(self, starts, L, S, W):
        """v4.6, суррогат 'multi': close-канал — знаки баров S[:, 1:] (ровно как sflip у close), каналы средних цен —
           зеркало тех же баров (S — из block_signs_prev, столбец 0 — бар перед окном). v5.6: каналы-уровни (диапазон бара)
           — как у реального окна: зеркало бара его ширину не меняет. v5.7: знаковый уровень (положение close в баре) —
           со знаком своего бара: у перевёрнутого бара close по ту же сторону от середины, что был, только зеркально."""
        chans = [W[:, 0] * S[:, 1:]]
        for e_, d_ in self.chan_t:
            chans.append(S[:, 1:] * gather(e_, starts, L) - S[:, :-1] * gather(d_, starts, L))
        chans += [S[:, 1:] * W[:, c] if LEVEL_SIGNED[c - N_PATH] else W[:, c] for c in range(N_PATH, W.shape[1])]
        return torch.stack(chans, dim=1)

    def mirror(self, starts, L, S):
        """v4.5, суррогат «зеркало бара» для средней цены бара: Δp'_t = s_t·e_t − s_{t−1}·d_{t−1} — бар t
           перевёрнут целиком (знак close-приращения; high и low — зеркально вокруг прошлого close), цена бара
           суррогата посчитана из перевёрнутых баров. S — знаки (n, L + 1) из block_signs_prev: столбец 0 —
           бар перед окном. При всех +1 получается реальное окно бит в бит."""
        return S[:, 1:] * gather(self.e_t, starts, L) - S[:, :-1] * gather(self.dprv_t, starts, L)

    def _side_arrays(self):
        """v4.4-4.5, для боковых входов: нормы |r| каждого ряда — EMA |r| со span = 30 / 7 / 1 суток баров
           (пропуски не сбивают состояние; TRAINING и VALIDATION ряда — один непрерывный счёт), час суток и
           день недели конца бара; накопленная сумма r (для хода перед окном)."""
        self.bars_day = int(round(1440 / tf_minutes(self.tf)))
        emas = []
        for days in SIDE_DAYS:
            span = int(round(days * 1440 / tf_minutes(self.tf)))
            ema = np.full(len(self.r), np.nan, dtype=np.float64)
            for i in range(len(self.series)):
                idx = np.where(self.sid == i)[0]
                ema[idx] = pd.Series(np.abs(self.r[idx].astype(np.float64))).ewm(
                    span=span, adjust=False, ignore_na=True).mean().to_numpy()
            ema = np.where(np.isfinite(ema) & (ema > 0), ema, np.nan)
            emas.append(pd.Series(ema).bfill().ffill().to_numpy().astype(np.float32))   # прокладки — соседним
        t = np.where(self.t > 0, self.t, 0)
        self.ema_abs_t = torch.from_numpy(np.stack(emas)).to(DEVICE)                     # (3, позиции)
        self.hod_t = torch.from_numpy(((t // 60_000_000_000) % 1440 / 60.0).astype(np.float32)).to(DEVICE)
        self.dow_t = torch.from_numpy((((t // 86_400_000_000_000) + 3) % 7).astype(np.float32)).to(DEVICE)
        cs0 = np.concatenate([[0.0], np.cumsum(np.nan_to_num(self.r.astype(np.float64)))])
        self.cs0_t = torch.from_numpy(cs0).to(DEVICE)          # сумма r по барам [i, j) = cs0[j] − cs0[i]
        self._hist_arrays()
        self._absv_arrays()

    def _hist_arrays(self):
        """v5.4, исторические нормы масштабов пирамиды: H_k — EMA |доходности close за k баров| со span HIST_DAYS суток.
           Доходность за k баров — только там, где все k баров конечны и лежат в одном куске ряда (TRAINING или
           VALIDATION); TRAINING и VALIDATION ряда — один непрерывный счёт EMA. До первого значения ряда — медиана
           |доходности за k баров| по его TRAINING (константа: без заглядывания вперёд), на прокладках — прошлое
           значение. Окно берёт H_k на баре start − 2 (side_feats): только прошлое, бар перед окном не берётся."""
        rc = getattr(self, 'rc', self.r).astype(np.float64)      # close (у средних цен и 'multi' — self.rc)
        fin = np.isfinite(rc)
        cs = np.concatenate([[0.0], np.cumsum(np.where(fin, rc, 0.0))])
        cn = np.concatenate([[0], np.cumsum(fin)])
        pos = np.arange(len(rc))
        span = int(round(HIST_DAYS * 1440 / tf_minutes(self.tf)))
        idx_s = [np.where(self.sid == i)[0] for i in range(len(self.series))]
        logs = []
        for k in HIST_K:
            a0 = np.maximum(pos + 1 - k, 0)
            ok = (pos + 1 - k >= self.seg0) & (cn[pos + 1] - cn[a0] == k)
            Rk = np.where(ok, cs[pos + 1] - cs[a0], np.nan)
            H = np.full(len(rc), np.nan)
            for i, idx in enumerate(idx_s):
                s = self.series[i]
                o, n = s['off']['tr'], s['n']['tr']
                c0 = np.nanmedian(np.abs(Rk[o:o + n])) if np.isfinite(Rk[o:o + n]).any() else math.sqrt(k)
                e = pd.Series(np.abs(Rk[idx])).ewm(span=span, adjust=False, ignore_na=True).mean().to_numpy(copy=True)
                good = np.isfinite(e)
                e[:int(np.argmax(good)) if good.any() else len(e)] = c0
                H[idx] = e
            H = pd.Series(H).ffill().to_numpy()                   # прокладки — прошлым значением
            logs.append(np.log(np.maximum(np.nan_to_num(H, nan=1.0), 1e-4)).astype(np.float32))
        self.hist_log_t = torch.from_numpy(np.stack(logs)).to(DEVICE)    # (масштабы, позиции): log H_k

    def _absv_arrays(self):
        """v5.5, абсолютная вола бара (признак absv, столбец 36 side_feats): делитель приращений r — rolling-медиана диапазона
           бара (high − low) за 200 баров ДО бара (SMC_Data, closed='left') — восстанавливается как Δclose_t / r_t (close из
           smc_series) и выражается в базисных пунктах цены: 1e4 · делитель / close. Где r = 0 или NaN (и на первом баре
           куска) — прошлое значение; до первого значения ряда — медиана по его TRAINING (константа: без заглядывания
           вперёд); на прокладках — прошлое значение. Окно берёт значение на баре start − 2 (только прошлое). Диапазон бара у
           «зеркала бара» тот же, а суррогат не трогает делитель вовсе: у реала и его суррогата признак совпадает и от
           знаков окна не зависит. Нет close в файлах данных — absv_ok = False, признак 0 (варианты с ним не запустятся)."""
        n = len(self.r)
        self.absv_ok = self.close_px is not None
        if not self.absv_ok:
            self.absv_log_t = torch.zeros(n, device=DEVICE)
            return
        rc = getattr(self, 'rc', self.r).astype(np.float64)      # close-приращения в единицах делителя
        c = self.close_px
        prev = np.concatenate([[np.nan], c[:-1]])
        same = np.zeros(n, dtype=bool)
        same[1:] = np.arange(n - 1) >= self.seg0[1:]             # бар t − 1 — в том же куске ряда
        with np.errstate(invalid='ignore', divide='ignore'):
            dc = np.where(same, c - prev, np.nan)
            ok = np.isfinite(rc) & (np.abs(rc) > 0) & np.isfinite(dc) & np.isfinite(c) & (c > 0)
            bp = np.where(ok, 1e4 * dc / np.where(ok, rc, 1.0) / np.where(ok, c, 1.0), np.nan)
        bp = np.where(bp > 0, bp, np.nan)                         # знак Δclose и r один: делитель > 0
        out = np.full(n, np.nan)
        for i in range(len(self.series)):
            idx = np.where(self.sid == i)[0]
            s = self.series[i]
            o, m = s['off']['tr'], s['n']['tr']
            c0 = float(np.nanmedian(bp[o:o + m])) if np.isfinite(bp[o:o + m]).any() else 1.0
            v = pd.Series(bp[idx]).ffill().to_numpy(copy=True)
            good = np.isfinite(v)
            v[:int(np.argmax(good)) if good.any() else len(v)] = c0
            out[idx] = v
        out = pd.Series(out).ffill().to_numpy()                  # прокладки — прошлым значением
        self.absv_log_t = torch.from_numpy(np.log(np.maximum(np.nan_to_num(out, nan=1.0), 1e-6)).astype(np.float32)).to(DEVICE)
        self.close_px = None                                     # цены больше не нужны (у пула — сотни МБ)

    def _nt_arrays(self):
        """v6.0, признаки истории в барах (столбцы side_feats NT_COL0 …, см. nt_segment): считаются один раз по сырым OHLC
           каждой части вместе с NT_HIST барами перед ней — у каждого окна полная история, и на первых барах части тоже. Знак
           ориентации формы ставит side_feats (у реала и суррогата он свой). NT_KEEP — какие столбцы держать на устройстве
           (None — все). Нет файла баров хотя бы у одного ассета — nt_ok = False, признаки — нули. Сверка по пути: медиана
           диапазона за 200 баров перед баром — тот же нормировщик, что у r (r · медиана = Δclose). Сырые цены после счёта не
           хранятся; для проверки глубины (MODE 'check') остаётся проба — первые 1200 баров первой части с разогревом."""
        n = len(self.r)
        rows = tuple(range(NT_N)) if NT_KEEP is None else tuple(sorted(c - NT_COL0 for c in NT_KEEP))
        base = np.zeros((len(rows), n), np.float32)
        self.nt_ok = all(s['bars'][k] is not None for s in self.series for k in ('tr', 'va'))
        self.nt_rows, self.nt_probe, self.nt_stats = rows, None, {}
        if self.nt_ok:
            rc = getattr(self, 'rc', self.r)
            err, n_gap, n_bar, br = 0.0, 0, 0, []
            for s in self.series:
                for key in ('tr', 'va'):
                    b = s['bars'][key]
                    ext = [np.concatenate([b[f'pre_{k_}'], b[k_]]) for k_ in ('o', 'h', 'l', 'c')]
                    o, m = s['off'][key], s['n'][key]
                    f, sc = nt_segment(*ext, with_scales=True)
                    base[:, o:o + m] = f[list(rows)]
                    r_ = rc[o:o + m].astype(np.float64)
                    dc = ext[3][NT_HIST:] - ext[3][NT_HIST - 1:-1]
                    ok = np.isfinite(r_) & (np.abs(r_) > 0.05) & (dc != 0)
                    if ok.any():
                        err = max(err, float(np.max(np.abs(r_[ok] * sc['rmed'][ok] - dc[ok]) / np.abs(dc[ok]))))
                    n_gap += int((ext[0][NT_HIST:] != ext[3][NT_HIST - 1:-1]).sum())
                    n_bar += m
                    rng_ = ext[1][NT_HIST:] - ext[2][NT_HIST:]
                    br.append(np.median(np.abs(ext[3][NT_HIST:] - ext[0][NT_HIST:])[rng_ > 0] / rng_[rng_ > 0]))
                    if self.nt_probe is None:
                        self.nt_probe = [x[:1200].copy() for x in ext]
                    s['bars'][key] = None
            self.nt_stats = {'norm_err': err, 'open_gap': n_gap / max(n_bar, 1), 'body_rng': float(np.median(br))}
        self.nt_t = torch.from_numpy(base).to(DEVICE)
        self.nt_orient_t = torch.from_numpy(NT_ORIENT[list(rows)]).to(DEVICE)

    def floor(self, i, L):
        """Пол делителя ряда i для окна L: из файла данных или по TRAINING (как в SuMo)."""
        s = self.series[i]
        if L not in s['floors']:
            a = s['off']['tr']
            r = self.r[a:a + int(s['meta']['parts']['TRAINING']['n'])]
            st = valid_starts(r, L)
            div = np.empty(len(st), np.float32)
            for j in range(0, len(st), 200000):
                W = r[st[j:j + 200000][:, None] + np.arange(L)[None, :]]
                div[j:j + 200000] = np.median(np.abs(W), axis=1)
            s['floors'][L] = float(np.percentile(div[div > 1e-6], 0.1))
            print(f"🧱 пол {s['asset']} L={L} ({PRICE_NAMES[self.price]}) посчитан здесь: {s['floors'][L]:.6f}")
        return s['floors'][L]

    def windows(self, L):
        """Все окна без NaN: начало, время конца, ряд, часть (FIT / TUNE / VAL).
           v4.5: same_as_close — окна те же, что у close (у средней цены бара — обязаны)."""
        if L not in self._win:
            st = valid_starts(self.r, L)
            t0, t1 = self.t[st], self.t[st + L - 1]
            part, sid = self.part[st], self.sid[st]
            fit = (part == 0) & (t1 < self.tune_ns)
            tune = (part == 0) & (t0 >= self.tune_ns)
            fl = np.array([self.floor(i, L) for i in range(len(self.series))], np.float32)
            same = True if self.price == 'close' else bool(np.array_equal(valid_starts(self.rc, L), st))
            if not same:
                print(f"⚠️ {PRICE_NAMES[self.price]} L={L}: окна не те же, что у close — сравнение с close по "
                      f"парам окон и ансамбль цен в сводке не считаются")
            self._win[L] = {'st': st, 't_end': t1, 'sid': sid.astype(np.int64),
                            'fit': np.where(fit)[0], 'tune': np.where(tune)[0],
                            'val': np.where(part == 1)[0], 'floor': fl, 'same_as_close': same,
                            'floor_t': torch.from_numpy(fl).to(DEVICE)}
        return self._win[L]

    def fin_values(self, i, which):
        """Конечные приращения ряда i в куске 'fit' | 'tune' | 'val' (для iid-нулевой)."""
        key = (i, which)
        if key not in self._fin_vals:
            s = self.series[i]
            p = 'va' if which == 'val' else 'tr'
            g = s['off'][p] + s['fin'][p]
            if which == 'fit':
                g = g[self.t[g] < self.tune_ns]
            elif which == 'tune':
                g = g[self.t[g] >= self.tune_ns]
            self._fin_vals[key] = torch.from_numpy(self.r[g]).to(DEVICE)
        return self._fin_vals[key]

    def bank_windows(self, i, name, which, L, k=0):
        """Окна суррогата из банка (ряд из конечных значений, без NaN): приращения, время конца окна по
           реальному бару, чьё место занял последний шаг, и глобальный индекс этого бара (v4.5: боковые входы)."""
        s = self.series[i]
        p = 'va' if which == 'val' else 'tr'
        key = f"{name}_{p}_{k}"
        if key not in s['bank']:
            return None, None, None
        v = s['bank'][key]
        g = s['off'][p] + s['fin'][p]                     # глобальный индекс j-го конечного бара
        st = np.arange(len(v) - L + 1)
        t_end, t_st = self.t[g[st + L - 1]], self.t[g[st]]
        if which == 'tune':
            st = st[t_st >= self.tune_ns]
        elif which == 'fit':
            st = st[t_end < self.tune_ns]
        W = v[st[:, None] + np.arange(L)[None, :]]
        return torch.from_numpy(W).to(DEVICE), self.t[g[st + L - 1]], g[st + L - 1]


# =====================================================================
# ФОРМА ОКНА И СУРРОГАТЫ (torch)
# =====================================================================
def gather(r_t, starts, L):
    return r_t[starts[:, None] + torch.arange(L, device=r_t.device)[None, :]]


def median_abs(W):
    """Медиана |шага| как np.median: при чётном L — среднее двух средних."""
    A = W.abs().sort(dim=1).values
    L = W.shape[1]
    return A[:, L // 2] if L % 2 else 0.5 * (A[:, L // 2 - 1] + A[:, L // 2])


def to_shapes(W, floor, chunk=262144):
    """Форма ret_med, как sumo_shapes: cumsum -> центрирование -> симметризация по знаку
       X[-1] -> деление на max(медиана |шага|, пол). floor — пол каждой строки.
       v4.6: окна 'multi' (n, 3, L) — каждый канал свой путь, но ориентация и делитель — по close-каналу (каналы
       остаются согласованными: видно, где средние цены расходятся с close).
       v5.6: каналы после N_PATH (диапазон бара у 'multi_g') — уровни: не суммируются, не центрируются и не переворачиваются
       ориентацией (у зеркального окна диапазоны те же), только делятся на тот же делитель окна.
       v5.7: знаковый уровень (положение close в баре у 'multi_gc') переворачивается вместе с ориентацией формы: перевернуть
       форму — то же, что перевернуть все бары окна, а у перевёрнутого бара положение close — с другим знаком.
       v6.0: правило ничьей — переворот только при конце пути < −ORIENT_EPS · делитель окна (тот же знак — в side_feats).
       v6.7: при ORIENT = False переворота нет (абсолютное направление; см. orientation)."""
    if W.dim() == 3:
        out = []
        for i in range(0, len(W), chunk):
            w, f = W[i:i + chunk], floor[i:i + chunk]
            lv = None
            if w.shape[1] > N_PATH:                      # v5.6: каналы-уровни отдельно
                w, lv = w[:, :N_PATH], w[:, N_PATH:]
            div = torch.maximum(median_abs(w[:, 0]), f)
            X = torch.cumsum(w, dim=2)
            X = X - X.mean(dim=2, keepdim=True)
            flip = (X[:, 0, -1] < -ORIENT_EPS * div)[:, None, None]
            if not ORIENT:                               # v6.7: абсолютное направление — окно как есть
                flip = torch.zeros_like(flip)
            X = torch.where(flip, -X, X)
            if lv is not None and any(LEVEL_SIGNED[:lv.shape[1]]):    # v5.7: знаковые уровни — с ориентацией формы
                lv = torch.stack([torch.where(flip[:, 0], -lv[:, j], lv[:, j]) if LEVEL_SIGNED[j] else lv[:, j]
                                  for j in range(lv.shape[1])], dim=1)
            div = div[:, None, None]
            out.append(X / div if lv is None else torch.cat([X / div, lv / div], dim=1))
        return torch.cat(out) if len(out) > 1 else out[0]
    out = []
    for i in range(0, len(W), chunk):
        w, f = W[i:i + chunk], floor[i:i + chunk]
        div = torch.maximum(median_abs(w), f)
        X = torch.cumsum(w, dim=1)
        X = X - X.mean(dim=1, keepdim=True)
        if ORIENT:                                       # v6.7: без ориентации — окно как есть
            X = torch.where((X[:, -1] < -ORIENT_EPS * div)[:, None], -X, X)
        out.append(X / div[:, None])
    return torch.cat(out) if len(out) > 1 else out[0]


CTX_BLOCK, CTX_NBLK = 16, 8       # v4.6: грубый путь перед окном — 8 кусков по 16 баров (последние 128 баров)
SIDE_NAMES = (('вола к норме 30 сут', 'вола к норме 7 сут', 'вола к норме 1 сут', 'час sin', 'час cos',
               'день sin', 'день cos', 'ход за L баров до окна', 'ход за сутки до окна',
               'ход за 3 суток до окна', 'ход за неделю до окна')
              + tuple(f'путь до окна {CTX_BLOCK * (CTX_NBLK - j)}-{CTX_BLOCK * (CTX_NBLK - j - 1)}' for j in range(CTX_NBLK)))
_T, _P = (3, 4, 5, 6), tuple(range(11, 11 + CTX_NBLK))
SIDE_COLS = {'vt': (0,) + _T, 'v': (0,), 't': _T,                     # волна 7 (смысл столбцов тот же)
             'v7t': (1,) + _T,                                         # v4.5: норма за 7 суток (в Pine — без месяца истории)
             'vvt': (0, 1, 2) + _T,                                    # v4.5: все три нормы + время
             'vtc': (0,) + _T + (7, 8),                                # v4.5: волна 7 + прошлое перед окном
             'v7tc': (1,) + _T + (7, 8),                               # v4.6: то же с нормой за 7 суток
             'v7tcL': (1,) + _T + (7,),                                # v4.6: только ход за L баров до окна
             'v7tcD': (1,) + _T + (8,),                                # v4.6: только ход за сутки до окна
             'v7tc4': (1,) + _T + (7, 8, 9, 10),                       # v4.6: + ход за 3 суток и за неделю
             'v7tcp': (1,) + _T + (8, 9, 10) + _P}                     # v4.6: грубый путь 128 баров + сутки / 3 суток / неделя
# v5.4: пирамида доходностей окна (вход CNN) и исторические нормы масштабов
HIST_K = (1, 2, 4, 8, 16, 32, 64)     # масштабы (бары) исторических норм H_k
HIST_DAYS = 7                          # H_k — EMA |доходности close за k баров| со span 7 суток
HIST_COL0 = 19                         # столбцы side_feats 19-25: log(делитель окна / H_k), k по HIST_K
PYR_MODES = ('sum', 'haar', 'ms')
PYR_MS_K = (1, 2, 4, 8, 16, 32)       # масштабы каналов 'ms'
PYR_G_CLAMP = 4.0                      # |log(делитель окна / H_k)| не больше 4 (множитель масштаба не больше e^4)
SIDE_NAMES = SIDE_NAMES + tuple(f'log(делитель окна / H_{k})' for k in HIST_K)
# v5.5: признаки токена — числа самого окна (и абсолютная вола до него), столбцы side_feats 26-36
TOK_COL0 = 26
TOK_VR_K = (2, 4, 8, 16, 32)           # масштабы лестницы VR (суммы k шагов окна)
SIDE_NAMES = SIDE_NAMES + ('log амплитуды пути окна', 'ER окна', 'log медианы |шага| окна', 'log среднего |шага| окна',
                           'доля нулевых шагов окна') + tuple(f'VR_{k} окна' for k in TOK_VR_K) + (
                          'log абсолютной волы до окна (б.п.)',)
TOK_COLS = tuple(range(TOK_COL0, TOK_COL0 + 6 + len(TOK_VR_K)))      # 26 … 36
TOK_SIGNFREE = (28, 29, 30, 36)        # от знаков окна не зависят: у реала и его суррогата — бит в бит
_V7TCP = SIDE_COLS['v7tcp']
SIDE_COLS.update({'v7tcp_amp': _V7TCP + (26,),                      # v5.5: F1 + амплитуда
                  'v7tcp_er': _V7TCP + (27,),                       # + эффективность хода
                  'v7tcp_den': _V7TCP + (28, 29),                   # + медиана и среднее |шага| (знаменатели)
                  'v7tcp_z0': _V7TCP + (30,),                       # + доля нулевых шагов (грубая сетка цены)
                  'v7tcp_vr': _V7TCP + tuple(range(31, 31 + len(TOK_VR_K))),   # + лестница VR
                  'v7tcp_absv': _V7TCP + (36,),                     # + абсолютная вола (б.п.)
                  'v7tcp_tok': _V7TCP + TOK_COLS})                  # + все признаки токена
CHAN_COLS = {'tok': TOK_COLS}          # v5.5: признаки токена постоянными каналами на вход свёрток (cnn_chan)
# v5.5: нижняя граница масштаба столбца при стандартизации по FIT. Доля нулевых шагов у BTC почти всегда 0 — её sd по FIT
# крошечный, и окно с одним нулевым шагом в TUNE дало бы вход в десятки sd; граница — один нулевой шаг из 64
SIDE_SD_FLOOR = {30: 1.0 / 64}

# v6.0: признаки истории В БАРАХ (без времени) — столбцы side_feats NT_COL0 … NT_COL0 + NT_N − 1, см. nt_segment.
# История окна с началом s — бары s − 200 … s − 1 (вместе с окном 64 бара — 264): глубже ничего не читается
NT_HIST = 200
NT_SCALES = ('rmed', 'rmean', 'bmed', 'bmean')     # нормировки за 200 баров перед окном:
NT_SCALE_NAMES = {'rmed': 'медиана диапазона',      # медиана high − low (тот же нормировщик, что у r)
                  'rmean': 'среднее диапазона',     # среднее high − low
                  'bmed': 'медиана |close − open|',
                  'bmean': 'среднее |close − open|'}
NT_GEO = (71, 64, 32, 16, 8, 4, 2, 2)    # куски пути до окна, от старого к свежему: бары s − 200 … s − 2 (199 баров)
NT_UNI = (24, 25, 25, 25, 25, 25, 25, 25)  # то же равными кусками
NT_SHORT = (16, 64)                      # короткие средние диапазона (V): последние 16 и 64 бара
NT_BODY_FLOOR = 0.05                     # пол медианы / среднего |close − open| — доля медианы диапазона (сплошные доджи)
NT_CLIP_Z, NT_CLIP_LOG = 20.0, 5.0       # обрезка ходов в единицах нормировки и логарифмов (обвалы, мёртвые бары)


def _nt_layout():
    """Столбцы признаков истории: (имя, со знаком ориентации формы, группа)."""
    cols = []
    for x in NT_SCALES:
        cols += [(f'путь до окна, кусок {j + 1}/8 ({n} бар.), {NT_SCALE_NAMES[x]}', True, f'P_{x}')
                 for j, n in enumerate(NT_GEO)]
    cols += [(f'путь до окна, равный кусок {j + 1}/8 ({n} бар.), {NT_SCALE_NAMES["rmed"]}', True, 'PU')
             for j, n in enumerate(NT_UNI)]
    cols.append(('положение close в диапазоне 200 баров', True, 'R1'))
    for x in NT_SCALES:
        cols.append((f'log ширины диапазона 200 баров, {NT_SCALE_NAMES[x]}', False, f'R2_{x}'))
        cols.append((f'отклонение close от средней за 200 баров, {NT_SCALE_NAMES[x]}', True, f'R3_{x}'))
    cols += [(nm, False, 'V') for nm in (f'log(ср. диапазон {NT_SHORT[0]} / 200 баров)',
                                          f'log(ср. диапазон {NT_SHORT[1]} / 200 баров)',
                                          'log(среднее / медиана диапазона, 200 баров)',
                                          'log(медиана |close − open| / медиана диапазона, 200 баров)')]
    return cols


_NT = _nt_layout()
NT_COL0 = TOK_COLS[-1] + 1                                   # 37
NT_N = len(_NT)                                              # 53
NT_ORIENT = np.array([o for _, o, _ in _NT], dtype=bool)
NT_GROUP = {}
for _j, (_, _, _g) in enumerate(_NT):
    NT_GROUP.setdefault(_g, []).append(NT_COL0 + _j)
NT_GROUP = {k: tuple(v) for k, v in NT_GROUP.items()}
SIDE_NAMES = SIDE_NAMES + tuple(nm for nm, _, _ in _NT)
NT_KEEP = None            # какие столбцы истории держать на устройстве (None — все; для пула — только нужные модели)
# v6.4: столбцы side_feats со знаком ориентации формы — у зеркального окна они с минусом (ход перед окном 7-18, путь и положение
# в истории P / PU / R1 / R3); остальные (вола, время, масштаб, ширина диапазона, режим волы V) от зеркала не меняются
SIDE_MIRROR = tuple(range(7, 19)) + tuple(NT_COL0 + int(j) for j in np.where(NT_ORIENT)[0])
# v6.4, гладкость линии (line_stats): «крупный бар» — |шаг close| >= LINE_BIG медиан |шага| окна; оттенки покраски (временная
# шкала для счёта смен) — границы M на каждой стороне; эхо крупного бара — бары с |r| в верхних (1 − LINE_ECHO_Q); бутстреп по
# неделям — LINE_BOOT повторов
LINE_BIG = 3.0
LINE_SHADES = (1.5, 2.5, 5.0, 10.0)
LINE_ECHO_Q = 0.995
LINE_ECHO_AGES = 300
LINE_BOOT = 300
SMOOTH_V0 = 1.0       # v6.4: пол разброса logit в знаменателе штрафа скачков (см. smooth_penalty)


def _nt_cols(x='rmed', groups='PRV'):
    """Столбцы групп признаков истории: P (путь, геометрические куски), U (путь, равные куски), R, V; x — нормировка."""
    out = ()
    for g in groups:
        out += {'P': NT_GROUP[f'P_{x}'], 'U': NT_GROUP['PU'], 'V': NT_GROUP['V'],
                'R': NT_GROUP['R1'] + NT_GROUP[f'R2_{x}'] + NT_GROUP[f'R3_{x}']}[g]
    return out


_DEN = (28, 29)          # знаменатель окна (медиана и среднее |шага|) — в F1 с v5.6, от времени не зависит
SIDE_COLS.update({'nt_den': _DEN,                              # v6.0: без времени, без замены
                  'nt_P': _DEN + _nt_cols(groups='P'),
                  'nt_PU': _DEN + _nt_cols(groups='U'),
                  'nt_R': _DEN + _nt_cols(groups='R'),
                  'nt_V': _DEN + _nt_cols(groups='V'),
                  'nt_PR': _DEN + _nt_cols(groups='PR'),
                  'nt_PV': _DEN + _nt_cols(groups='PV'),
                  'nt_PRV': _DEN + _nt_cols(groups='PRV')})
SIDE_COLS.update({f'nt_PRV_{x}': _DEN + _nt_cols(x, 'PRV') for x in NT_SCALES[1:]})
# столбцы, которых у моделей без времени быть не должно: время суток и дня недели, нормы волы в сутках, ход за L баров /
# сутки / 3 суток / неделю и грубый путь в долях нормы за сутки, H_k (7 суток), абсолютная вола (б.п., глубже 200 баров)
NT_OLD_COLS = tuple(range(0, 26)) + (36,)


def nt_segment(o, h, l, c, n_pre=NT_HIST, with_scales=False):
    """v6.0, признаки истории в барах для окон, начинающихся на барах n_pre … len − 1 куска. o, h, l, c — сырые цены куска
       (float64) вместе с n_pre >= 200 баров перед ним. История окна с началом s — бары s − 200 … s − 1:
         нормировки (NT_SCALES) — медиана / среднее диапазона high − low и медиана / среднее |close − open| за все 200 баров
             (медиана диапазона — тот же нормировщик, что у r на баре s); у |close − open| пол — 5% медианы диапазона;
         P — ход close куска пути (close последнего бара − open первого) / (√длины · нормировка), куски NT_GEO по барам
             s − 200 … s − 2; PU — то же кусками NT_UNI, нормировка — медиана диапазона;
         R1 — положение close бара s − 2 в диапазоне [min low, max high] баров s − 200 … s − 2, от −1 (низ) до +1 (верх);
         R2 — log((max high − min low) / (√199 · нормировка)); R3 — (close s − 2 − средняя close тех же баров) / (√199 · норм.);
         V — log(ср. диапазон последних 16 баров / ср. за 200), то же для 64, log(среднее / медиана диапазона за 200),
             log(медиана |close − open| / медиана диапазона за 200).
       Знакозависимое (P, PU, R1, R3) кончается на баре s − 2: бар прямо перед окном не берётся, как в прошлых волнах;
       нормировки и V — по s − 1. Глубже s − 200 ничего не читается. Знак ориентации формы окна ставит side_feats (у реала
       и его суррогата он свой), здесь его нет. Возвращает (NT_N, число окон) float32 (и нормировки при with_scales)."""
    nh, nh2 = NT_HIST, NT_HIST - 1
    m = len(c) - n_pre
    idx = np.arange(n_pre, len(c))
    rng_, body = h - l, np.abs(c - o)

    def roll(x, n, how, lag):
        """Статистика how по барам s − lag − n + 1 … s − lag для каждого начала окна s."""
        v = getattr(pd.Series(x).rolling(n, min_periods=n), how)().to_numpy()
        return v[idx - lag]

    with np.errstate(invalid='ignore', divide='ignore'):
        rmed, rmean = roll(rng_, nh, 'median', 1), roll(rng_, nh, 'mean', 1)
        sc = {'rmed': rmed, 'rmean': rmean,
              'bmed': np.maximum(roll(body, nh, 'median', 1), NT_BODY_FLOOR * rmed),
              'bmean': np.maximum(roll(body, nh, 'mean', 1), NT_BODY_FLOOR * rmed)}
        hmax, lmin, cma = roll(h, nh2, 'max', 2), roll(l, nh2, 'min', 2), roll(c, nh2, 'mean', 2)
        c2 = c[idx - 2]

        def blocks(lens):
            res, end = [], idx - 2                     # последний бар куска; идём от свежего куска к старому
            for n in lens[::-1]:
                start = end - n + 1
                res.append((c[end] - o[start]) / math.sqrt(n))
                end = start - 1
            return res[::-1]

        geo, out = blocks(NT_GEO), []
        for x in NT_SCALES:
            out += [np.clip(v / sc[x], -NT_CLIP_Z, NT_CLIP_Z) for v in geo]
        out += [np.clip(v / rmed, -NT_CLIP_Z, NT_CLIP_Z) for v in blocks(NT_UNI)]
        w = hmax - lmin
        out.append(np.where(w > 0, 2.0 * (c2 - lmin) / np.where(w > 0, w, 1.0) - 1.0, 0.0))
        for x in NT_SCALES:
            out.append(np.clip(np.log(np.maximum(w, 1e-12) / (math.sqrt(nh2) * sc[x])), -NT_CLIP_LOG, NT_CLIP_LOG))
            out.append(np.clip((c2 - cma) / (math.sqrt(nh2) * sc[x]), -NT_CLIP_Z, NT_CLIP_Z))
        r16, r64 = roll(rng_, NT_SHORT[0], 'mean', 1), roll(rng_, NT_SHORT[1], 'mean', 1)
        for v in (r16 / rmean, r64 / rmean, rmean / rmed, sc['bmed'] / rmed):
            out.append(np.clip(np.log(np.maximum(v, 1e-3)), -NT_CLIP_LOG, NT_CLIP_LOG))
    f = np.nan_to_num(np.stack(out), nan=0.0, posinf=0.0, neginf=0.0).astype(np.float32)
    if m <= 0:
        f = np.zeros((NT_N, 0), np.float32)
    return (f, sc) if with_scales else f


def side_sd(Z, cols):
    """sd столбцов cols по окнам FIT (Z — их значения) с нижней границей: 1e-6 у всех, SIDE_SD_FLOOR — у своих столбцов."""
    sd = Z.std(0).clamp_min(1e-6)
    fl = torch.tensor([SIDE_SD_FLOOR.get(c, 0.0) for c in cols], device=sd.device, dtype=sd.dtype)
    return torch.maximum(sd, fl)


def side_feats(data, starts, L, W, floor):
    """v4.4-4.5: боковые входы окна (n, 9). Каждый считается по СВОЕМУ окну W (у суррогата — по суррогатному),
       прошлое и время — общие для реала и суррогата той же позиции:
       0-2 — log(делитель формы / норма |r| за 30 / 7 / 1 сутки на конце окна): тихо или бурно относительно своей
             нормы (у close-суррогата sflip модули те же, что у реала, — эти входы у пары одинаковы);
       3-6 — sin / cos часа суток и дня недели конца окна;
       7-8 — ход цены за L баров и за сутки ДО окна (бар прямо перед окном не берётся: у суррогата средней
             цены бара он участвует в первом приращении), в долях нормы за сутки, умноженный на знак ориентации
             формы (форма симметризуется по знаку): «окно идёт туда же, куда шёл рынок до него» — плюс.
       9-10 — то же за 3 суток и за неделю (v4.6);
       11-18 — грубый путь последних 128 баров до окна: 8 кусков по 16 баров (от старого к свежему), каждый — ход куска
             в долях нормы за сутки, со знаком ориентации формы (v4.6).
       19-25 — log(делитель окна / H_k), k = 1, 2, 4, …, 64 (v5.4): H_k — историческая норма |доходности close за k
             баров| на баре start − 2 (только прошлое, бар перед окном не берётся); делитель окна от знаков не зависит,
             поэтому у реала и его суррогата эти столбцы совпадают. Нужны пирамиде с нормировкой 'hist'.
       26-36 — признаки токена (v5.5), числа самого окна: 26 — log амплитуды пути (RMS центрированного пути в единицах
             делителя окна — как log_amp прототипной модели и B_simple); 27 — ER = |сумма шагов| / сумма |шагов|; 28 — log
             делителя окна (медиана |шага|, с полом); 29 — log среднего |шага| (с тем же полом); 30 — доля нулевых шагов;
             31-35 — VR_k = log(RMS суммы k шагов подряд / (√k · RMS шага)), k = 2, 4, 8, 16, 32 (только полные суммы;
             у 26 и 31-35 снизу −5: плоское окно или идеальная «пила» на сетке цены дали бы log 0);
             36 — log абсолютной волы на баре start − 2 (делитель r в б.п. цены, см. SeriesData._absv_arrays).
             26, 27, 31-35 — по 63 шагам формы (первый шаг окна форма теряет), 28-30 — по всем 64 приращениям, как делитель.
             26, 27, 31-35 зависят от знаков — у суррогата они свои (по его окну); 28-30, 36 у реала и его суррогата
             совпадают (модули шагов у sflip те же).
       Сами по себе входы 0-25, 28-30 и 36 реал и суррогат не различают — только через взаимодействие с узором знаков окна.
       37-89 — признаки истории в барах (v6.0, nt_segment): у реала и его суррогата одни и те же (история реальная, глубина
             200 баров), кроме знака ориентации формы — его получают P, PU, R1, R3 (у суррогата знак — по его окну).
       У окон 'multi' (n, 3, L) всё считается по close-каналу.
       v6.7: при ORIENT = False знак ориентации — +1 у всех окон: знаковые входы как есть (абсолютное направление)."""
    if W.dim() == 3:
        W = W[:, 0]
    end = starts + (L - 1)
    div = torch.maximum(median_abs(W), floor)
    ld = torch.log(div)
    v = ld[:, None] - torch.log(data.ema_abs_t[:, end].t())
    h = data.hod_t[end] * (2.0 * math.pi / 24.0)
    d = data.dow_t[end] * (2.0 * math.pi / 7.0)
    cs = torch.cumsum(W, dim=1)
    sgn = torch.where(cs[:, -1] - cs.mean(dim=1) < -ORIENT_EPS * div, -1.0, 1.0)   # ориентация формы — как в to_shapes
    if not ORIENT:                                       # v6.7: абсолютное направление — знаковые входы как есть
        sgn = torch.ones_like(sgn)
    a1 = (starts - 1).clamp_min(0)
    norm = data.ema_abs_t[2, a1]
    ctx = []
    for n_ in (L, data.bars_day):
        a0 = torch.minimum(torch.maximum(a1 - n_, data.seg0_t[starts]), a1)
        n_eff = (a1 - a0).clamp_min(1).float()
        ctx.append((data.cs0_t[a1] - data.cs0_t[a0]).float() / (torch.sqrt(n_eff) * norm) * sgn)
    # v4.6: прошлое подробнее — те же формулы; A1 — конец прошлого (бар перед окном не берётся), не раньше начала куска
    seg = data.seg0_t[starts]
    A1 = torch.maximum(a1, seg)
    for n_ in (3 * data.bars_day, 7 * data.bars_day):
        a0 = torch.maximum(A1 - n_, seg)
        n_eff = (A1 - a0).clamp_min(1).float()
        ctx.append((data.cs0_t[A1] - data.cs0_t[a0]).float() / (torch.sqrt(n_eff) * norm) * sgn)
    for k in range(CTX_NBLK - 1, -1, -1):                 # от старого куска к свежему
        hi = torch.maximum(A1 - CTX_BLOCK * k, seg)
        lo = torch.maximum(A1 - CTX_BLOCK * (k + 1), seg)
        n_eff = (hi - lo).clamp_min(1).float()
        ctx.append((data.cs0_t[hi] - data.cs0_t[lo]).float() / (torch.sqrt(n_eff) * norm) * sgn)
    g = ld[:, None] - data.hist_log_t[:, (starts - 2).clamp_min(0)].t()      # v5.4: log(делитель окна / H_k)
    tok = tok_feats(W, ld, floor, data.absv_log_t[(starts - 2).clamp_min(0)])  # v5.5: признаки токена
    nt = data.nt_t[:, starts].t() * torch.where(data.nt_orient_t[None, :], sgn[:, None], torch.ones_like(sgn)[:, None])
    if len(data.nt_rows) < NT_N:                                             # v6.0: не все столбцы истории на устройстве
        full = torch.zeros(len(starts), NT_N, device=nt.device, dtype=nt.dtype)
        full[:, list(data.nt_rows)] = nt
        nt = full
    return torch.cat([v, torch.stack([torch.sin(h), torch.cos(h), torch.sin(d), torch.cos(d)] + ctx, dim=1), g, tok, nt],
                     dim=1)


def tok_feats(W, ld, floor, absv):
    """v5.5, признаки токена (столбцы side_feats 26-36), см. side_feats. W — приращения окна (n, L) close-канала, ld — log
       делителя окна, floor — пол делителя, absv — log абсолютной волы на баре start − 2."""
    cs = torch.cumsum(W, dim=1)
    xc = cs - cs.mean(dim=1, keepdim=True)
    # = log_amp формы (путь / делитель); снизу −5 — только у вырожденных окон (все шаги нулевые: путь плоский)
    amp = torch.log(xc.pow(2).mean(dim=1).sqrt() * torch.exp(-ld) + 1e-6).clamp_min(-5.0)
    z = W[:, 1:]                                                             # 63 шага формы
    az = z.abs()
    er = z.sum(dim=1).abs() / az.sum(dim=1).clamp_min(1e-12)
    aw = W.abs()
    mean_l = torch.log(torch.maximum(aw.mean(dim=1), floor))
    z0 = (aw == 0).float().mean(dim=1)
    cz = F.pad(torch.cumsum(z, dim=1), (1, 0))                               # cz[j] − cz[i] — сумма шагов [i, j)
    rms1 = z.pow(2).mean(dim=1).sqrt().clamp_min(1e-12)
    # снизу −5: идеальная «пила» на сетке цены (+1, −1, …) дала бы log 0
    vr = [torch.log((cz[:, k:] - cz[:, :-k]).pow(2).mean(dim=1).sqrt().clamp_min(1e-12) / (math.sqrt(k) * rms1)).clamp_min(-5.0)
          for k in TOK_VR_K]
    return torch.stack([amp, er, ld, mean_l, z0] + vr + [absv], dim=1)


def tv_ratio(W, floor):
    """Сумма |шагов| в единицах делителя формы: от знаков не зависит, поэтому обрезка
       по ней убирает одни и те же позиции у реала и у его sflip."""
    return W.abs().sum(dim=1) / torch.maximum(median_abs(W), floor)


def block_signs(n, L, b, gen, device):
    """Случайные ±1 блоками по b баров со случайной фазой (как _block_signs в SuMo)."""
    if b <= 1:
        return torch.where(torch.rand(n, L, generator=gen, device=device) < 0.5, -1.0, 1.0)
    phase = torch.randint(0, b, (n, 1), generator=gen, device=device)
    idx = (torch.arange(L, device=device)[None, :] + phase) // b
    nb = (L - 1 + b - 1) // b + 1
    s = torch.where(torch.rand(n, nb, generator=gen, device=device) < 0.5, -1.0, 1.0)
    return torch.gather(s, 1, idx)


def block_signs_prev(n, L, b, gen, device):
    """v4.5: знаки L баров окна — ровно как block_signs (тот же поток случайных чисел: у суррогата средней цены
       бара перевёрнуты те же бары, что у суррогата close той же позиции и того же набора) — плюс знак бара перед
       окном (он участвует в первом приращении): тот же блок, что у первого бара окна, если фаза блоков не 0,
       иначе свежий знак. Выход (n, L + 1), столбец 0 — бар перед окном."""
    if b <= 1:
        s = torch.where(torch.rand(n, L, generator=gen, device=device) < 0.5, -1.0, 1.0)
        s0 = torch.where(torch.rand(n, 1, generator=gen, device=device) < 0.5, -1.0, 1.0)
        return torch.cat([s0, s], dim=1)
    phase = torch.randint(0, b, (n, 1), generator=gen, device=device)
    idx = (torch.arange(L, device=device)[None, :] + phase) // b
    nb = (L - 1 + b - 1) // b + 1
    s = torch.where(torch.rand(n, nb, generator=gen, device=device) < 0.5, -1.0, 1.0)
    win = torch.gather(s, 1, idx)
    fresh = torch.where(torch.rand(n, 1, generator=gen, device=device) < 0.5, -1.0, 1.0)
    return torch.cat([torch.where(phase > 0, win[:, :1], fresh), win], dim=1)


def parse_null(spec):
    """'sflip4' -> ('sflip', 4); 'iid' -> ('iid', 0); 'bank:bperm32w2016' -> ('bank', имя);
       'shuf4' -> ('shuf', 4); 'ctlnull4' -> ('ctlnull', 4); v4.5: 'nsflip4' -> ('nsflip', 4) — наивный sflip
       приращений (у close то же, что sflip; у средней цены бара нечестен — только для демонстрации)."""
    if spec.startswith('bank:'):
        return 'bank', spec[5:]
    for kind in ('nsflip', 'sflip', 'shuf', 'ctlnull'):
        if spec.startswith(kind):
            return kind, int(spec[len(kind):] or 1)
    if spec == 'iid':
        return 'iid', 0
    raise ValueError(f"🍆 АЙ, ОШИБКА! нулевая '{spec}'")


def primary_spec(cfg):
    """Набор проверки, на котором модель учится и останавливается (с учётом контроля).
       v4.5: price_null 'naive' — наивный sflip приращений средней цены бара ('nsflip<b>')."""
    null = cfg['null'].split(':')[1].split('+')[0] if cfg['null'].startswith('mix:') else cfg['null']
    if cfg.get('price_null', 'mirror') == 'naive':
        kind, b = parse_null(null)
        if kind != 'sflip' or cfg['control'] is not None or cfg['null'].startswith('mix:'):
            raise ValueError("🍆 АЙ, ОШИБКА! наивная нулевая цены бара — только sflip<b>, без контроля и смеси")
        return f'nsflip{b}'
    if cfg['control'] is None:
        return null
    kind, b = parse_null(null)
    if kind != 'sflip':
        raise ValueError("🍆 АЙ, ОШИБКА! контроли определены только для нулевой sflip<b>")
    return ('ctlnull' if cfg['control'] == 'null' else 'shuf') + str(b)


def iid_draws(data, sids, which, L, gen, device):
    """Окна из независимых шагов своего ряда и куска (iid-нулевая на уровне окна)."""
    W = torch.empty(len(sids), L, device=device)
    for i in torch.unique(sids).tolist():
        rows = torch.where(sids == i)[0]
        vals = data.fin_values(int(i), which).to(device)
        idx = torch.randint(0, len(vals), (len(rows), L), generator=gen, device=device)
        W[rows] = vals[idx]
    return W


class PairMaker:
    """Обучающая пара на каждом шаге: реальное окно FIT и его отрицательный пример.
       v4.5: у средней цены бара sflip — «зеркало бара» (data.mirror), наивный sflip — 'nsflip'."""
    def __init__(self, data, L, cfg, tv_thr, gen):
        self.data, self.L, self.cfg, self.thr, self.gen = data, L, cfg, tv_thr, gen
        self.floor_t = data.windows(L)['floor_t']
        mix = cfg['null'][4:].split('+') if cfg['null'].startswith('mix:') else [cfg['null']]
        self.mix = [parse_null(m) for m in mix]
        if cfg.get('price_null', 'mirror') == 'naive':
            self.mix = [('nsflip', b) if k == 'sflip' else (k, b) for k, b in self.mix]
        for kind, _ in self.mix:
            if kind not in ('sflip', 'nsflip', 'iid'):
                raise ValueError(f"🍆 АЙ, ОШИБКА! для обучения есть sflip<b> и iid, не '{kind}'")
            if data.price in MULTI_KINDS and kind != 'sflip':
                raise ValueError("🍆 АЙ, ОШИБКА! у трёх цен бара ('multi') нулевая обучения — только sflip<b>")

    def _flip(self, Wr, starts, b):
        """sflip: у close — случайные знаки приращений блоками по b; у средней цены бара — зеркало баров блоками;
           у 'multi' — те же перевёрнутые бары во всех трёх каналах."""
        if self.data.price == 'close':
            return Wr * block_signs(len(Wr), self.L, b, self.gen, DEVICE)
        if self.data.price in MULTI_KINDS:
            return self.data.flip_multi(starts, self.L, block_signs_prev(len(Wr), self.L, b, self.gen, DEVICE), Wr)
        return self.data.mirror(starts, self.L, block_signs_prev(len(Wr), self.L, b, self.gen, DEVICE))

    def _iid(self, sids):
        W = iid_draws(self.data, sids, 'fit', self.L, self.gen, DEVICE)
        fl = self.floor_t[sids]
        for _ in range(5):                     # та же обрезка по размаху, что у реальных окон
            bad = torch.where(tv_ratio(W, fl) > self.thr)[0]
            if len(bad) == 0:
                break
            W[bad] = iid_draws(self.data, sids[bad], 'fit', self.L, self.gen, DEVICE)
        return W

    def _neg(self, Wr, starts, sids, kind, b):
        if kind == 'sflip':
            return self._flip(Wr, starts, b)
        if kind == 'nsflip':                   # v4.5: наивный sflip приращений (у средней цены бара нечестен)
            return Wr * block_signs(len(Wr), self.L, b, self.gen, DEVICE)
        return self._iid(sids)

    def make(self, starts, sids):
        Wr = self.data.gw(starts, self.L)      # v4.6: у 'multi' — (n, 3, L)
        fl = self.floor_t[sids]
        ctl = self.cfg['control']
        if ctl is not None:
            b = self.mix[0][1]
            if ctl == 'null':                  # суррогат против суррогата: сигнала нет
                Wp = self._flip(Wr, starts, b)
                Wn = self._flip(Wr, starts, b)
            elif self.data.price in MULTI_KINDS:
                raise ValueError("🍆 АЙ, ОШИБКА! у трёх цен бара ('multi') контроль — только 'null'")
            else:                              # перемешанный ряд против своего sflip
                Wp = self._iid(sids)
                Wn = Wp * block_signs(len(Wp), self.L, b, self.gen, DEVICE)
            return Wp, Wn, fl
        if len(self.mix) == 1:
            return Wr, self._neg(Wr, starts, sids, *self.mix[0]), fl
        parts = torch.tensor_split(torch.arange(len(Wr), device=DEVICE), len(self.mix))
        Wn = torch.empty_like(Wr)
        for (kind, b), rows in zip(self.mix, parts):
            Wn[rows] = self._neg(Wr[rows], starts[rows], sids[rows], kind, b)
        return Wr, Wn, fl


# =====================================================================
# НАБОРЫ ПРОВЕРКИ (одинаковые у всех прогонов)
# =====================================================================
class EvalStore:
    """Реальные окна TUNE / VAL / пробы FIT и суррогаты к ним с фиксированными seed.
       Кэшируется на весь рантайм: у прогонов с тем же L наборы бит в бит одни.
       v6.7: набор помнит ориентацию, с которой создан (ORIENT): формы и боковые входы считаются в ней; окна и знаки суррогатов
       от ориентации не зависят (те же генераторы) — сравнение моделей с ориентацией и без неё парное."""
    def __init__(self, data, L):
        self.data, self.L = data, L
        self.w = data.windows(L)
        self._pos, self._set = {}, {}
        self.orient = ORIENT

    def _check_orient(self):
        made = getattr(self, 'orient', True)
        if ORIENT != made:
            raise RuntimeError(f"🍆 АЙ, ОШИБКА! наборы проверки созданы с ORIENT = {made}, а сейчас ORIENT = {ORIENT} "
                               f"(v6.7: у каждой ориентации свои наборы — get_store)")

    def _gen(self, *key):
        g = torch.Generator()
        g.manual_seed(DATA['eval_seed'] + zlib.crc32("|".join(map(str, key)).encode()) % 1000003)
        return g

    def years(self):
        """Календарный год конца каждого окна (для профиля по годам)."""
        if not hasattr(self, '_year'):
            self._year = pd.to_datetime(self.w['t_end']).year.values
        return self._year

    def fit_years(self):
        return sorted(set(self.years()[self.w['fit']].tolist()))

    def positives(self, which):
        if which not in self._pos:
            self._check_orient()               # v6.7
            if which.startswith('fitY'):       # окна FIT одного календарного года
                fit = self.w['fit']
                idx = fit[self.years()[fit] == int(which[4:])]
                n_max = 30000
            elif which.startswith('fitout:') or which.startswith('fitin:'):
                # v4.2-4.3: окна FIT в отложенных блоках (в обучение не шли) / в блоках обучения;
                # ключ 'fitout:H:B' или 'fitout:H:B:Y2019' (только окна этого года)
                kind, H, B, *yr = which.split(':')
                fit = self.w['fit']
                out, excl = holdout_masks(self.w['t_end'][fit], int(H), int(B))
                idx = fit[out] if kind == 'fitout' else fit[~excl]
                n_max = 60000
                if yr:
                    idx = idx[self.years()[idx] == int(yr[0][1:])]
                    n_max = 30000
            else:
                idx = self.w['fit' if which == 'fitprobe' else which]
                n_max = 60000 if which == 'fitprobe' else DATA['max_eval']
            if n_max and len(idx) > n_max:
                rng = np.random.default_rng(DATA['eval_seed'] + len(which))
                idx = np.sort(rng.choice(idx, size=n_max, replace=False))
            st = self.w['st'][idx]
            sid = torch.from_numpy(self.w['sid'][idx]).to(DEVICE)
            st_t = torch.from_numpy(st).to(DEVICE)
            W = self.data.gw(st_t, self.L)      # v4.6: у 'multi' — (n, 3, L)
            fl = self.w['floor_t'][sid]
            self._pos[which] = {'W': W, 'fl': fl, 'sid': sid, 'X': to_shapes(W, fl), 'st': st, 'st_t': st_t,
                                'wk': self.w['t_end'][idx] // WEEK_NS,
                                'S': side_feats(self.data, st_t, self.L, W, fl)}
        return self._pos[which]

    def get(self, which, spec):
        """v4.5: у средней цены бара sflip — «зеркало бара» с теми же знаками баров, что у close той же позиции
           (один мир суррогатов для всех цен); 'nsflip' — наивный sflip приращений. Боковые входы суррогата —
           по его собственному окну на месте реального (у iid / перемешанного ряда / банка — тоже)."""
        key = (which, spec)
        if key in self._set:
            return self._set[key]
        self._check_orient()                   # v6.7
        P = self.positives(which)
        n, L = len(P['W']), self.L
        kind, par = parse_null(spec)
        part = 'fit' if which.startswith('fit') else which
        g = self._gen(which, spec, L)
        mirror = self.data.price != 'close'
        out = {'Xp': P['X'], 'wp': P['wk'], 'wn': P['wk'], 'paired': True, 'st': P['st'],
               'Sp': P['S'], 'Sn': P['S']}      # у close-суррогата sflip модули те же — боковые входы те же

        def side(W_):
            return side_feats(self.data, P['st_t'], L, W_, P['fl'])

        if self.data.price in MULTI_KINDS:
            # v4.6: три цены бара — только «перевёрнутые бары» (sflip) и контроль «суррогат против суррогата»
            if kind not in ('sflip', 'ctlnull'):
                return None
            Wn = self.data.flip_multi(P['st_t'], L, block_signs_prev(n, L, par, g, 'cpu').to(DEVICE), P['W'])
            if kind == 'sflip':
                out.update({'Xn': to_shapes(Wn, P['fl']), 'Sn': side(Wn)})
            else:
                Wp, Wn = Wn, self.data.flip_multi(P['st_t'], L, block_signs_prev(n, L, par, g, 'cpu').to(DEVICE), P['W'])
                out.update({'Xp': to_shapes(Wp, P['fl']), 'Xn': to_shapes(Wn, P['fl']), 'st': None,
                            'Sp': side(Wp), 'Sn': side(Wn)})
            self._set[key] = out
            return out

        if kind == 'sflip':
            if mirror:
                Wn = self.data.mirror(P['st_t'], L, block_signs_prev(n, L, par, g, 'cpu').to(DEVICE))
            else:
                Wn = P['W'] * block_signs(n, L, par, g, 'cpu').to(DEVICE)
            out.update({'Xn': to_shapes(Wn, P['fl']), 'Sn': side(Wn)})
        elif kind == 'nsflip':
            Wn = P['W'] * block_signs(n, L, par, g, 'cpu').to(DEVICE)
            out.update({'Xn': to_shapes(Wn, P['fl']), 'Sn': side(Wn)})
        elif kind == 'iid':                    # окно из независимых шагов своего ряда — на месте реального
            Wn = iid_draws(self.data, P['sid'].cpu(), part, L, g, 'cpu').to(DEVICE)
            out.update({'Xn': to_shapes(Wn, P['fl']), 'paired': False, 'Sn': side(Wn)})
        elif kind in ('shuf', 'ctlnull'):
            if kind == 'shuf':                 # перемешанный ряд против своего sflip
                Wp = iid_draws(self.data, P['sid'].cpu(), part, L, g, 'cpu').to(DEVICE)
                Wn = Wp * block_signs(n, L, par, g, 'cpu').to(DEVICE)
            elif mirror:                       # два независимых зеркала баров ОДНОГО реального окна
                Wp = self.data.mirror(P['st_t'], L, block_signs_prev(n, L, par, g, 'cpu').to(DEVICE))
                Wn = self.data.mirror(P['st_t'], L, block_signs_prev(n, L, par, g, 'cpu').to(DEVICE))
            else:                              # два независимых sflip ОДНОГО реального окна
                Wp = P['W'] * block_signs(n, L, par, g, 'cpu').to(DEVICE)
                Wn = P['W'] * block_signs(n, L, par, g, 'cpu').to(DEVICE)
            out.update({'Xp': to_shapes(Wp, P['fl']), 'Xn': to_shapes(Wn, P['fl']), 'st': None,
                        'Sp': side(Wp), 'Sn': side(Wn)})
        elif kind == 'bank':
            Ws, ts, fls, ends = [], [], [], []
            for i in range(len(self.data.series)):
                W, t_end, g_end = self.data.bank_windows(i, par, part, L)
                if W is None:
                    return None
                Ws.append(W)
                ts.append(t_end)
                ends.append(g_end)
                fls.append(torch.full((len(W),), float(self.w['floor'][i]), device=DEVICE))
            W, t_end, fl, ends = torch.cat(Ws), np.concatenate(ts), torch.cat(fls), np.concatenate(ends)
            rng = np.random.default_rng(DATA['eval_seed'] + zlib.crc32(spec.encode()) % 1000)
            pick = np.sort(rng.choice(len(W), size=min(n, len(W)), replace=False))
            pick_t = torch.from_numpy(pick).to(DEVICE)
            Wb, flb = W[pick_t], fl[pick_t]
            st_b = torch.from_numpy(ends[pick] - (L - 1)).to(DEVICE)   # окно банка — на месте своего конца
            out.update({'Xn': to_shapes(Wb, flb), 'wn': t_end[pick] // WEEK_NS, 'paired': False,
                        'Sn': side_feats(self.data, st_b, L, Wb, flb)})
        self._set[key] = out
        return out


# =====================================================================
# МОДЕЛИ
# =====================================================================
def mlp(n_in, hidden, dropout=0.0):
    layers, d = [], n_in
    for h in hidden:
        layers += [nn.Linear(d, h), nn.ReLU()]
        if dropout > 0:
            layers.append(nn.Dropout(dropout))
        d = h
    layers.append(nn.Linear(d, 1))
    return nn.Sequential(*layers)


class SMCModel(nn.Module):
    """Прототипы + мягкое разложение + голова. Всё — умножения матриц, exp и ReLU."""
    def __init__(self, C0, cfg):
        super().__init__()
        self.K, self.L = C0.shape
        self.dist, self.head_in = cfg['dist'], cfg['head_in']
        self.head_amp = cfg['head_amp'] or cfg['dist'] == 'cos'
        self.topk = int(cfg.get('p_topk') or 0)   # 0 — плотное P; k — только k ближайших форм (остальные 0)
        self.protos = nn.Parameter(C0.clone().float())
        self.log_T = nn.Parameter(torch.zeros(()), requires_grad=cfg['temp_learn'])
        for nm, size in (('dmin_mu', ()), ('dmin_sd', ()), ('d_mu', (self.K,)),
                         ('d_sd', (self.K,)), ('amp_mu', ()), ('amp_sd', ())):
            self.register_buffer(nm, torch.zeros(size) if nm.endswith('mu') else torch.ones(size))
        n_in = self.K + (1 if self.head_in == 'p_dmin' else 0) + (1 if self.head_amp else 0)
        self.head = mlp(n_in, cfg['head_hidden'])

    def dist_matrix(self, x):
        C = self.protos
        if self.dist == 'l2':      # квадрат евклида на точку: D не зависит от длины окна
            D = (x * x).mean(1, keepdim=True) - 2.0 * (x @ C.t()) / self.L + (C * C).mean(1)[None, :]
            return D.clamp_min(0.0)
        xc = F.normalize(x - x.mean(1, keepdim=True), dim=1)
        cc = F.normalize(C - C.mean(1, keepdim=True), dim=1)
        return 1.0 - xc @ cc.t()   # 1 − корреляция форм: амплитуда не видна

    @staticmethod
    def log_amp(x):
        return torch.log((x - x.mean(1, keepdim=True)).pow(2).mean(1).sqrt() + 1e-6)

    def soft_p(self, D):
        """P = softmax(−D / T); при p_topk = k — softmax только по k ближайшим формам, остальные
           координаты ровно 0: токен несёт «какие k форм и с какими весами», а не перекодировку окна."""
        T = self.log_T.exp()
        if 0 < self.topk < self.K:
            vals, idx = D.topk(self.topk, dim=1, largest=False)
            return torch.zeros_like(D).scatter(1, idx, torch.softmax(-vals / T, dim=1))
        return torch.softmax(-D / T, dim=1)

    def features(self, x, D):
        P = self.soft_p(D)
        dmin = D.min(dim=1).values
        if self.head_in == 'd':
            feats = [(torch.log1p(D) - self.d_mu) / self.d_sd]
        else:
            feats = [P]
            if self.head_in == 'p_dmin':
                feats.append(((torch.log1p(dmin) - self.dmin_mu) / self.dmin_sd)[:, None])
        if self.head_amp:
            feats.append(((self.log_amp(x) - self.amp_mu) / self.amp_sd)[:, None])
        return torch.cat(feats, dim=1), P, dmin

    def forward(self, x):
        D = self.dist_matrix(x)
        e, P, dmin = self.features(x, D)
        return self.head(e).squeeze(1), D, P, dmin

    @torch.no_grad()
    def set_stats(self, x):
        """Масштабы входов головы по реальным окнам FIT на старте (дальше не меняются)."""
        D = self.dist_matrix(x)
        ld, dm = torch.log1p(D), torch.log1p(D.min(1).values)
        self.dmin_mu.copy_(dm.mean())
        self.dmin_sd.copy_(dm.std().clamp_min(1e-6))
        self.d_mu.copy_(ld.mean(0))
        self.d_sd.copy_(ld.std(0).clamp_min(1e-6))
        a = self.log_amp(x)
        self.amp_mu.copy_(a.mean())
        self.amp_sd.copy_(a.std().clamp_min(1e-6))

    def pine_cost(self):
        n = self.K * self.L + self.K
        for m in self.head:
            if isinstance(m, nn.Linear):
                n += m.in_features * m.out_features
        return n


class MLPBase(nn.Module):
    """Потолок без прототипов: MLP прямо на форме окна (inp='shape') или на её шагах (inp='steps')."""
    def __init__(self, L, hidden, x_sd, dropout=0.0, inp='shape'):
        super().__init__()
        self.inp = inp
        self.register_buffer('x_sd', torch.tensor(float(x_sd)))
        self.net = mlp(L if inp == 'shape' else L - 1, hidden, dropout)

    def forward(self, x):
        z = x if self.inp == 'shape' else x[:, 1:] - x[:, :-1]
        return self.net(z / self.x_sd).squeeze(1), None, None, None

    def pine_cost(self):
        return sum(m.in_features * m.out_features for m in self.net if isinstance(m, nn.Linear))


def pyr_input(x, mode, norm='rw', s=None):
    """v5.4, пирамида доходностей окна — вход CNN вместо шагов формы подряд.
       x — форма окна (окна, каналы, 64) или (окна, 64): путь, ориентированный по знаку и делённый на делитель окна.
       u — шаги формы: те же 63 шага, что видит сеть на шагах, и u[0] = 0 (первый шаг окна теряется при центрировании
       формы — как и у сети на шагах). Масштаб k = 2^j баров.
       mode 'sum'  — суммы u по непересекающимся блокам k = 2, 4, …, 64 (32 + 16 + 8 + 4 + 2 + 1 чисел) и последний шаг
                     окна: 64 числа на канал, места — клетки пирамиды, а не время. С потерей: из двух шагов внутри пары
                     баров остаётся только их сумма (остальные уровни — суммы этих 32 чисел);
            'haar' — вейвлет Хаара: разности соседних половин блоков (32 + 16 + 8 + 4 + 2 + 1), делённые на √2, и сумма
                     окна / 8: 64 числа, преобразование ортогональное — без потерь;
            'ms'   — доходность за k = 1, 2, 4, 8, 16, 32 бара, кончающаяся на каждом баре окна: каналы цены × масштабы,
                     места — время (64); в начале окна, где шагов меньше k, — сумма с начала окна. Без потерь (k = 1 —
                     сами шаги), сдвинутый во времени узор — тот же узор.
       norm 'rw'   — общий делитель окна (как у формы) и деление на √(число шагов в сумме): у случайного блуждания все
                     масштабы одного размера ('haar' ортонормальный — это то же самое);
            'hist' — масштаб k — на свою историческую норму H_k: множитель exp(s[:, HIST_COL0 + j]) = делитель окна / H_k
                     (столбцы side_feats, только прошлое): значение — доходность за k баров в долях типичной доходности
                     за k баров последней недели.
       Всё — функция окна и прошлого, поэтому у суррогата пирамида считается из его собственных (перевёрнутых) баров."""
    if x.dim() == 2:
        x = x[:, None, :]
    n, C, L = x.shape
    if L != 64 or mode not in PYR_MODES or norm not in ('rw', 'hist'):
        raise ValueError(f"🍆 АЙ, ОШИБКА! пирамида: окно {L} (нужно 64), режим '{mode}', нормировка '{norm}'")
    u = F.pad(x[..., 1:] - x[..., :-1], (1, 0))
    if norm == 'hist':
        if mode == 'haar':
            raise ValueError("🍆 АЙ, ОШИБКА! у 'haar' нормировка только 'rw' (коэффициенты Хаара — не доходности)")
        if s is None or s.shape[1] < HIST_COL0 + len(HIST_K):
            raise ValueError("🍆 АЙ, ОШИБКА! пирамиде с нормировкой 'hist' нужны столбцы H_k боковых входов")
        fk = torch.exp(s[:, HIST_COL0:HIST_COL0 + len(HIST_K)].clamp(-PYR_G_CLAMP, PYR_G_CLAMP)).to(x.dtype)

    def mult(j):                                   # множитель полной суммы на масштабе k = 2^j
        return fk[:, j].view(n, 1, 1) if norm == 'hist' else 1.0 / math.sqrt(2 ** j)

    if mode == 'sum':
        parts = [u.reshape(n, C, L >> j, 1 << j).sum(-1) * mult(j) for j in range(1, 7)]
        return torch.cat(parts + [u[..., -1:] * mult(0)], dim=2)
    if mode == 'haar':
        a, det = u, []
        while a.shape[2] > 1:
            ev, od = a[..., 0::2], a[..., 1::2]
            det.append((ev - od) * math.sqrt(0.5))
            a = (ev + od) * math.sqrt(0.5)
        return torch.cat(det + [a], dim=2)
    t = torch.arange(L, device=x.device, dtype=x.dtype)
    chans = []
    for k in PYR_MS_K:
        R = u if k == 1 else F.avg_pool1d(F.pad(u, (k - 1, 0)), k, stride=1) * k
        m = torch.minimum(t, torch.full_like(t, float(k))).clamp_min(1.0)    # шагов в сумме (u[0] = 0 — не шаг)
        if norm == 'hist':
            chans.append(R * torch.sqrt(k / m) * mult(int(round(math.log2(k)))))
        else:
            chans.append(R / torch.sqrt(m))
    return torch.stack(chans, dim=2).reshape(n, C * len(PYR_MS_K), L)


def mirror_inputs(x, s=None, n_level=0, lvl_signed=()):
    """v6.4: вход модели у зеркального ряда (каждый бар перевёрнут вокруг уровня: close-ход и ходы средних цен — с минусом,
       high <-> low): у формы окна каналы-пути с минусом, знаковые уровни (положение close в баре) — тоже, ширина бара — как была;
       у боковых входов с минусом столбцы со знаком ориентации формы (SIDE_MIRROR), остальные — как были. x — форма окна (окна, L)
       или (окна, каналы, L) после to_shapes, s — все столбцы side_feats (или None). Зеркало зеркала — исходный вход бит в бит."""
    if x.dim() == 3:
        n_path = x.shape[1] - int(n_level or 0)
        sg = torch.ones(x.shape[1], device=x.device, dtype=x.dtype)
        sg[:n_path] = -1.0
        for j, signed in enumerate(lvl_signed):
            if signed:
                sg[n_path + j] = -1.0
        xm = x * sg[None, :, None]
    else:
        xm = -x
    if s is None:
        return xm, None
    sm = s.clone()
    idx = [c for c in SIDE_MIRROR if c < s.shape[1]]
    sm[:, idx] = -sm[:, idx]
    return xm, sm


class CNNBase(nn.Module):
    """Свёрточная сеть по шагам окна: одни и те же фильтры в любом месте окна (веса общие по
       времени — меньше запоминания конкретных окон, чем у MLP), dilation 1, 2, 4, 8 — поле
       зрения ~ всё окно. По времени — среднее, максимум и значение на последнем шаге -> голова.
       Опции: batchnorm, остаточные связи, dropout в свёртках, пулинг 'mml' | 'mm' | 'last',
       вход 'steps' (шаги окна) | 'shape' (форма) | 'sm' (два канала: знак шага и log его модуля —
       суррогат sflip хранит модули и меняет только знаки, так что различие живёт в знаках «при
       данных модулях»; сети не нужно самой раскладывать шаг на знак и размер).
       v4.3: sdrop — канальный dropout (выключает канал целиком во всём окне); valid — свёртки без
       добивки нулями (выход есть только там, где поле зрения целиком внутри окна); bias=False —
       без сдвигов в свёртках; ma — вход сглажен скользящим средним по ma шагам.
       Pine: у сети valid + без bias + без batchnorm (streamable) признаки каждой позиции зависят
       только от шагов в её поле зрения и масштабируются вместе с делителем окна, поэтому в Pine
       они считаются один раз на бар (два потока — для r и −r из-за симметризации формы по знаку),
       а делитель окна применяется после пулинга: в таблице — цена такого счёта на бар. У
       остальных — цена полного пересчёта окна на каждом баре.
       v5.4: pyr — вход-пирамида доходностей ('sum' | 'haar' | 'ms', см. pyr_input) вместо шагов подряд, pyr_norm —
       её нормировка ('rw' | 'hist'; 'hist' берёт нормы H_k из боковых входов s).
       v5.5: chan_cols — столбцы side_feats постоянными каналами на вход свёрток: число окна (стандартизованное по FIT)
       повторено во всех местах — первый слой видит его рядом с каждым шагом (сдвиг порога каждого фильтра по окну).
       v5.6: n_level — последние каналы входа — уровни (диапазон бара у 'multi_g'): свёрткам идут их значения на барах
       1…L−1 (рядом с шагами этих баров), а не разности; стандартизованы по FIT (буферы lvl_mu / lvl_sd).
       v5.7: lvl_log — диапазон бара (первый уровень) идёт как log(g / делитель окна + LVL_EPS); знаковый уровень (положение
       close в баре, 'multi_gc') и все уровни потоковой сети — без сдвига: lvl_mu = 0, lvl_sd = RMS по FIT (зеркальный бар —
       зеркальный вход; у потоковой сети признаки остаются пропорциональны 1 / делитель окна — счёт в Pine бар за баром).
       v6.3: sep — свёртки слоёв 2 … последний раздельные (depthwise-separable): по каналу своё ядро k с той же dilation
       (groups = ch), затем смешение каналов 1 × 1, потом ReLU. Весов и умножений на место k·ch + ch² вместо k·ch²; первый
       слой (вход — каналы цены) — обычный. Без bias и batchnorm сеть остаётся потоковой (счёт в Pine бар за баром).
       v6.4: sym — зеркально-симметричная сеть: logit = (g(x, s) + g(зеркало x, зеркало s)) / 2, g — та же сеть (mirror_inputs).
       Форма окна по-прежнему ориентирована «концом вверх», но выход от ориентации не зависит: окно и его зеркало дают одно число
       бит в бит, и на смене ориентации между соседними окнами оценка не прыгает. Знаковые боковые входы (SIDE_MIRROR) модель видит
       с обоими знаками — их сдвиг при стандартизации 0, масштаб — RMS. В Pine: голова на обоих потоках (r и −r уже считаются).
       v6.7: anti — у симметричной сети вторая, антисимметричная голова на тех же признаках свёрток: logit = s + a,
       s = (h(f(x)) + h(f(зеркало x))) / 2 — как у sym, a = (h_a(f(x)) − h_a(f(зеркало x))) / 2 ('mlp' — h_a такая же, как голова;
       'lin' — линейная, без сдвига). a(зеркало x) = −a(x): с входом без ориентации (ORIENT = False) a — оценка асимметрии рынка
       «вверх против вниз». Последний слой h_a стартует нулём: в начале обучения сеть — та же SM_sym."""
    def __init__(self, L, ch, k, dils, hidden, dropout, in_sd, bn=False, res=False, cdrop=0.0,
                 pool='mml', inp='steps', sdrop=0.0, valid=False, bias=True, ma=0, side_cols=None, n_chan=1,
                 pyr=None, pyr_norm='rw', chan_cols=None, n_level=0, lvl_log=False, sep=False, sym=False, anti=None):
        super().__init__()
        self.sym = bool(sym)                   # v6.4: зеркально-симметричная сеть
        if self.sym and (inp != 'steps' or pyr or chan_cols):
            raise ValueError("🍆 АЙ, ОШИБКА! зеркально-симметричная сеть (cnn_sym) — только вход 'steps' без пирамиды и постоянных каналов")
        self.anti = anti or None               # v6.7: антисимметричная голова (сеть видит направление)
        if self.anti not in (None, 'mlp', 'lin'):
            raise ValueError(f"🍆 АЙ, ОШИБКА! cnn_anti '{anti}' — есть 'mlp' и 'lin'")
        if self.anti and not self.sym:
            raise ValueError("🍆 АЙ, ОШИБКА! антисимметричная голова (cnn_anti) — только у зеркально-симметричной сети (cnn_sym)")
        self.pyr, self.pyr_norm = (pyr or None), pyr_norm
        if self.pyr is not None and (inp != 'steps' or valid or ma):
            raise ValueError("🍆 АЙ, ОШИБКА! пирамида — только вход 'steps', без valid-свёрток и сглаживания")
        self.n_level = int(n_level or 0)
        if self.n_level and (inp != 'steps' or self.pyr is not None or n_chan <= self.n_level):
            raise ValueError("🍆 АЙ, ОШИБКА! каналы-уровни (диапазон бара) — только вход 'steps' многоканального окна, без пирамиды")
        self.lvl_log = bool(lvl_log)
        if self.lvl_log and (not self.n_level or LEVEL_SIGNED[0]):
            raise ValueError("🍆 АЙ, ОШИБКА! lvl_log — только у цены с диапазоном бара ('multi_g' / 'multi_gc')")
        self.lvl_signed = tuple(LEVEL_SIGNED[:self.n_level])
        if self.n_level:                       # v5.6: буферы — только у моделей с уровнями (веса старых грузятся как были)
            self.register_buffer('lvl_mu', torch.zeros(self.n_level))
            self.register_buffer('lvl_sd', torch.ones(self.n_level))
        # v4.4: боковые входы — выбранные столбцы side_feats, стандартизованные по FIT, идут в голову
        # рядом с признаками свёрток (взаимодействие с узором знаков — в скрытом слое головы)
        self.side_cols = tuple(side_cols) if side_cols else None
        n_side = len(self.side_cols) if self.side_cols else 0
        self.register_buffer('side_mu', torch.zeros(max(n_side, 1)))
        self.register_buffer('side_sd', torch.ones(max(n_side, 1)))
        # v5.5: постоянные каналы; буферы — только у моделей с ними (веса старых моделей грузятся как были)
        self.chan_cols = tuple(chan_cols) if chan_cols else None
        if self.chan_cols:
            self.register_buffer('chan_mu', torch.zeros(len(self.chan_cols)))
            self.register_buffer('chan_sd', torch.ones(len(self.chan_cols)))
        self.L, self.ch, self.k, self.dils = L, ch, k, tuple(dils)
        self.res, self.pool, self.inp, self.ma = res, pool, inp, int(ma or 0)
        self.c_in0 = 2 if inp == 'sm' else int(n_chan)      # v4.6: n_chan = 3 у трёх цен бара ('multi')
        if self.pyr == 'ms':
            self.c_in0 *= len(PYR_MS_K)                      # v5.4: каналы цены × масштабы
        if self.chan_cols:
            self.c_in0 += len(self.chan_cols)                # v5.5: + постоянные каналы
        self.streamable = bool(valid and not bias and not bn and inp == 'steps' and self.pyr is None
                               and not self.chan_cols and not self.lvl_log)
        self.needs_s = (bool(self.side_cols) or (self.pyr is not None and pyr_norm == 'hist')
                        or bool(self.chan_cols))
        self.n_pos = L if self.pyr is not None else L - 1   # мест на входе свёрток: 64 у пирамиды, 63 шага подряд
        self.register_buffer('s_sd', torch.tensor(float(in_sd)))
        self.sep = bool(sep)                   # v6.3: раздельные свёртки слоёв 2 … последний
        if self.sep and k < 2:
            raise ValueError("🍆 АЙ, ОШИБКА! раздельные свёртки (cnn_sep) — только с ядром k >= 2")
        blocks, c_in = [], self.c_in0
        for i_l, d in enumerate(self.dils):
            pad = 0 if valid else d * (k - 1) // 2
            if self.sep and i_l > 0:           # v6.3: по каналу своё ядро (groups = каналы), затем смешение каналов 1 × 1
                layers = [nn.Conv1d(c_in, c_in, k, dilation=d, padding=pad, groups=c_in, bias=bias),
                          nn.Conv1d(c_in, ch, 1, bias=bias)]
            else:
                layers = [nn.Conv1d(c_in, ch, k, dilation=d, padding=pad, bias=bias)]
            if bn:
                layers.append(nn.BatchNorm1d(ch))
            layers.append(nn.ReLU())
            if cdrop > 0:
                layers.append(nn.Dropout(cdrop))
            if sdrop > 0:
                layers.append(nn.Dropout1d(sdrop))
            blocks.append(nn.Sequential(*layers))
            c_in = ch
        self.blocks = nn.ModuleList(blocks)
        self.head = mlp({'mml': 3, 'mm': 2, 'last': 1}[pool] * ch + n_side, hidden, dropout)
        if self.anti:                          # v6.7: антисимметричная голова, последний слой — с нуля (a ≡ 0 на старте)
            n_in = {'mml': 3, 'mm': 2, 'last': 1}[pool] * ch + n_side
            self.head_a = mlp(n_in, hidden, dropout) if self.anti == 'mlp' else nn.Linear(n_in, 1, bias=False)
            last = [m for m in self.head_a.modules() if isinstance(m, nn.Linear)][-1]
            with torch.no_grad():
                last.weight.zero_()
                if last.bias is not None:
                    last.bias.zero_()
        n_out = self.n_pos - (self.ma - 1 if self.ma > 1 else 0) - (sum(self.dils) * (k - 1) if valid else 0)
        if n_out < 1:
            raise ValueError(f"🍆 АЙ, ОШИБКА! valid-свёртки: поле зрения {1 + sum(self.dils) * (k - 1)} "
                             f"шагов не помещается в окно из {L - 1} шагов")

    def conv_maps(self, x, s=None):
        """Карты последнего слоя свёрток (окна, каналы, места) — до пулинга."""
        if self.pyr is not None:               # v5.4: пирамида доходностей окна
            h = pyr_input(x, self.pyr, self.pyr_norm, s) / self.s_sd
        elif self.inp == 'sm':                 # шаги формы — в единицах медианы |шага| окна
            z = x[:, 1:] - x[:, :-1]
            h = torch.stack([torch.sign(z), torch.log(z.abs() + 0.1)], dim=1)
        elif self.n_level:                     # v5.6: пути — шагами, уровни (диапазон бара) — значениями баров 1…L−1
            P_ = x.shape[1] - self.n_level
            z = x[:, :P_, 1:] - x[:, :P_, :-1]
            lv = self.lvl_values(x[:, P_:, 1:])
            lv = (lv - self.lvl_mu[None, :, None]) / self.lvl_sd[None, :, None]
            h = torch.cat([z / self.s_sd, lv], dim=1)
        else:
            z = (x[..., 1:] - x[..., :-1]) if self.inp == 'steps' else x
            h = z / self.s_sd
            if h.dim() == 2:                   # один канал; у 'multi' вход уже (окна, 3, места)
                h = h[:, None, :]
        if self.chan_cols:                     # v5.5: числа окна — постоянными каналами во всех местах
            if s is None:
                raise ValueError("🍆 АЙ, ОШИБКА! постоянным каналам (cnn_chan) нужны боковые входы s")
            c = (s[:, list(self.chan_cols)] - self.chan_mu) / self.chan_sd
            h = torch.cat([h, c.to(h.dtype)[:, :, None].expand(-1, -1, h.shape[2])], dim=1)
        if self.ma > 1:                        # сглаженный путь: шаги, усреднённые по ma подряд
            h = F.avg_pool1d(h, self.ma, stride=1)
        for i, blk in enumerate(self.blocks):
            out = blk(h)
            h = out + h[:, :, h.shape[2] - out.shape[2]:] if (self.res and i > 0) else out
        return h

    def pooled(self, h):
        feats = []
        if self.pool in ('mml', 'mm'):
            feats += [h.mean(2), h.amax(2)]
        if self.pool in ('mml', 'last'):
            feats.append(h[:, :, -1])
        return torch.cat(feats, dim=1)

    def _feats(self, x, s=None):
        """Вход головы: пулинг карт свёрток и (v4.4) стандартизованные боковые входы."""
        f = self.pooled(self.conv_maps(x, s))
        if self.side_cols:
            f = torch.cat([f, (s[:, list(self.side_cols)] - self.side_mu) / self.side_sd], dim=1)
        return f

    def _logit(self, x, s=None):
        return self.head(self._feats(x, s)).squeeze(1)

    def forward(self, x, s=None):
        if getattr(self, 'sym', False):        # v6.4: среднее по окну и его зеркалу — выход не зависит от ориентации
            xm, sm = mirror_inputs(x, s, self.n_level, self.lvl_signed)
            if getattr(self, 'anti', None):    # v6.7: + антисимметричная часть a — сеть видит направление
                f, fm = self._feats(x, s), self._feats(xm, sm)
                s_ = 0.5 * (self.head(f) + self.head(fm))
                a_ = 0.5 * (self.head_a(f) - self.head_a(fm))
                return (s_ + a_).squeeze(1), None, None, None
            return 0.5 * (self._logit(x, s) + self._logit(xm, sm)), None, None, None
        return self._logit(x, s), None, None, None

    @torch.no_grad()
    def set_side_stats(self, S):
        """Масштабы боковых входов головы и (v5.5) постоянных каналов — по окнам FIT на старте. v6.4: у зеркально-симметричной
           сети знаковые столбцы (SIDE_MIRROR) приходят с обоими знаками — сдвиг 0, масштаб — RMS."""
        if self.side_cols:
            Z = S[:, list(self.side_cols)]
            mu, sd = Z.mean(0), side_sd(Z, self.side_cols)
            if getattr(self, 'sym', False):
                for j, c in enumerate(self.side_cols):
                    if c in SIDE_MIRROR:
                        mu[j] = 0.0
                        sd[j] = torch.maximum(Z[:, j].pow(2).mean().sqrt(), sd[j])
            self.side_mu.copy_(mu)
            self.side_sd.copy_(sd)
        if self.chan_cols:
            Z = S[:, list(self.chan_cols)]
            self.chan_mu.copy_(Z.mean(0))
            self.chan_sd.copy_(side_sd(Z, self.chan_cols))

    def lvl_values(self, v):
        """v5.7: значения каналов-уровней до стандартизации: у lvl_log диапазон бара — log(g / делитель окна + LVL_EPS)."""
        if not self.lvl_log:
            return v
        return torch.cat([torch.log(v[:, :1] + LVL_EPS), v[:, 1:]], dim=1)

    @torch.no_grad()
    def set_lvl_stats(self, X):
        """v5.6: среднее и sd каналов-уровней (баров 1…L−1) по окнам FIT на старте. v5.7: у знаковых уровней и у потоковой
           сети — без сдвига (среднее 0, масштаб — RMS)."""
        if self.n_level:
            V = self.lvl_values(X[:50000, -self.n_level:, 1:]).transpose(0, 1).reshape(self.n_level, -1)
            mu, sd = V.mean(1), V.std(1).clamp_min(1e-6)
            for j, sg in enumerate(self.lvl_signed):
                if sg or self.streamable:
                    mu[j], sd[j] = 0.0, V[j].pow(2).mean().sqrt().clamp_min(1e-6)
            self.lvl_mu.copy_(mu)
            self.lvl_sd.copy_(sd)

    @torch.no_grad()
    def set_pyr_sd(self, X, S=None):
        """v5.4: масштаб входа-пирамиды — std её значений на окнах FIT (как s_sd шагов у обычного входа).
           Без боковых входов у 'hist' (восстановление модели из весов) — пропуск: s_sd придёт из весов."""
        if self.pyr is None or (self.pyr_norm == 'hist' and S is None):
            return
        P = pyr_input(X[:50000], self.pyr, self.pyr_norm, None if S is None else S[:50000])
        self.s_sd.fill_(float(P.std()))

    def pine_cost(self):
        n_l = len(self.dils) - 1               # слои после первого: обычные k·ch² или (v6.3) раздельные k·ch + ch²
        per_pos = self.k * self.ch * self.c_in0 + n_l * ((self.k * self.ch + self.ch * self.ch) if getattr(self, 'sep', False)
                                                          else self.k * self.ch * self.ch)
        head = sum(m.in_features * m.out_features for m in self.head if isinstance(m, nn.Linear))
        if getattr(self, 'anti', None):        # v6.7: антисимметричная голова — на тех же потоках
            head += sum(m.in_features * m.out_features for m in self.head_a.modules() if isinstance(m, nn.Linear))
        sym = getattr(self, 'sym', False)      # v6.4: зеркально-симметричная — голова на обоих потоках, у полной сети вдвое всё
        if self.streamable:                    # одна новая позиция на бар, два потока (r и −r)
            return 2 * per_pos + head * (2 if sym else 1)
        return (self.n_pos * per_pos + head) * (2 if sym else 1)


class AttnBase(nn.Module):
    """Маленький трансформер по шагам окна (для потолка, не для Pine): шаг -> вектор d, плюс
       обучаемая позиция; n слоёв самовнимания; среднее и последний шаг -> голова."""
    EVAL_BS = 8192             # матрицы внимания окна x головы x L x L: оценка кусками поменьше

    def __init__(self, L, d, heads, layers, hidden, dropout, in_sd):
        super().__init__()
        self.L, self.d, self.layers_n = L, d, layers
        self.register_buffer('s_sd', torch.tensor(float(in_sd)))
        self.inp = nn.Linear(1, d)
        self.pos = nn.Parameter(torch.zeros(1, L - 1, d))
        enc = nn.TransformerEncoderLayer(d, heads, dim_feedforward=2 * d, dropout=dropout,
                                         batch_first=True, norm_first=True)
        self.enc = nn.TransformerEncoder(enc, layers, enable_nested_tensor=False)
        self.head = mlp(2 * d, hidden, dropout)

    def forward(self, x):
        z = ((x[:, 1:] - x[:, :-1]) / self.s_sd)[:, :, None]
        h = self.enc(self.inp(z) + self.pos)
        return self.head(torch.cat([h.mean(1), h[:, -1]], dim=1)).squeeze(1), None, None, None

    def pine_cost(self):
        n = self.L - 1
        per_layer = n * (4 * self.d * self.d + 2 * self.d * 2 * self.d) + 2 * n * n * self.d
        return self.layers_n * per_layer + n * self.d


class ShapeletBase(nn.Module):
    """v4.3, формы-шейплеты: K коротких форм длины m (путь, центрированный), которые ищутся в любом
       месте окна — форма, сдвинутая внутри окна, остаётся той же формой (как в SuMo).
       Для каждого места t окна: D_k(t) = средний квадрат разности центрированного куска пути
       x[t : t+m] и формы k; P_t = softmax_k(−D(t) / T) — какая форма описывает кусок t.
       Эмбеддинг окна: доля окна, описанная каждой формой (среднее P_t по местам: «мешок форм»), и
       насколько близко каждая форма нашлась в окне (мягкий минимум D_k по местам) -> MLP -> logit.
       Pine: полный пересчёт окна — места × K × m умножений (на порядок дешевле CNN)."""
    EVAL_BS = 16384            # тензор окна x формы x места: оценка кусками поменьше

    def __init__(self, C0, L, hidden, dropout, fdrop=0.0, side_cols=None):
        super().__init__()
        self.K, self.m = C0.shape
        self.fdrop = nn.Dropout(fdrop) if fdrop > 0 else nn.Identity()   # v4.4: dropout признаков форм
        self.L = L
        self.n_pos = L - self.m + 1
        self.protos = nn.Parameter(C0.clone().float())
        self.log_T = nn.Parameter(torch.zeros(()))
        self.register_buffer('b_mu', torch.zeros(self.K))
        self.register_buffer('b_sd', torch.ones(self.K))
        self.register_buffer('ones_m', torch.ones(1, 1, self.m))
        # v4.5: боковые входы, как у CNN — стандартизованные по FIT, в голову рядом с признаками форм
        self.side_cols = tuple(side_cols) if side_cols else None
        n_side = len(self.side_cols) if self.side_cols else 0
        self.register_buffer('side_mu', torch.zeros(max(n_side, 1)))
        self.register_buffer('side_sd', torch.ones(max(n_side, 1)))
        self.head = mlp(2 * self.K + n_side, hidden, dropout)

    def centered(self):
        return self.protos - self.protos.mean(1, keepdim=True)

    def dist(self, x):
        """D (окна, K, места): кусок пути центрируется; у центрированной формы скалярное
           произведение с куском не зависит от его среднего, поэтому всё — три свёртки."""
        C = self.centered()
        xi = x[:, None, :]
        dot = F.conv1d(xi, C[:, None, :])                          # (B, K, места)
        s1 = F.conv1d(xi, self.ones_m)
        s2 = F.conv1d(xi * xi, self.ones_m)                        # (B, 1, места)
        seg = s2 - s1 * s1 / self.m                                 # |кусок − его среднее|^2
        return ((seg - 2.0 * dot + (C * C).sum(1)[None, :, None]) / self.m).clamp_min(0.0)

    def feats(self, D):
        T = self.log_T.exp()
        bag = torch.softmax(-D / T, dim=1).mean(2)                  # доля окна у каждой формы
        best = -T * (torch.logsumexp(-D / T, dim=2) - math.log(self.n_pos))   # мягкий минимум по местам
        return bag, best

    def forward(self, x, s=None):
        bag, best = self.feats(self.dist(x))
        e = self.fdrop(torch.cat([bag * self.K, (torch.log1p(best) - self.b_mu) / self.b_sd], dim=1))
        if self.side_cols:
            e = torch.cat([e, (s[:, list(self.side_cols)] - self.side_mu) / self.side_sd], dim=1)
        return self.head(e).squeeze(1), None, None, None

    @torch.no_grad()
    def set_side_stats(self, S):
        if self.side_cols:
            Z = S[:, list(self.side_cols)]
            self.side_mu.copy_(Z.mean(0))
            self.side_sd.copy_(Z.std(0).clamp_min(1e-6))

    @torch.no_grad()
    def set_stats(self, x):
        """T на старте — типичный зазор между ближайшей и второй формой у куска; масштабы входа головы."""
        D = self.dist(x)
        two = D.topk(2, dim=1, largest=False).values
        self.log_T.fill_(math.log(max(float((two[:, 1] - two[:, 0]).median()), 1e-6)))
        _, best = self.feats(D)
        lb = torch.log1p(best)
        self.b_mu.copy_(lb.mean(0))
        self.b_sd.copy_(lb.std(0).clamp_min(1e-6))

    @torch.no_grad()
    def usage(self, X, bs=16384):
        """Средняя доля окна у каждой формы по набору окон X."""
        self.eval()
        acc = torch.zeros(self.K, device=X.device)
        for i in range(0, len(X), bs):
            bag, _ = self.feats(self.dist(X[i:i + bs]))
            acc += bag.sum(0)
        self.train()
        return (acc / max(1, len(X))).cpu().numpy()

    def pine_cost(self):
        return self.n_pos * self.K * self.m + sum(m.in_features * m.out_features for m in self.head
                                                  if isinstance(m, nn.Linear))


def init_shapelets(cfg, Xs, gen_np):
    """Старт форм-шейплетов: 'noise' — белый шум в масштабе центрированных кусков реальных окон
       (лучший старт у оконных форм в раунде 4); 'sample' — случайные куски реальных окон FIT."""
    K, m = cfg['shp_K'], cfg['shp_m']
    X = Xs[:20000].cpu().numpy()
    L = X.shape[1]
    rows = gen_np.integers(0, len(X), K * 4)
    starts = gen_np.integers(0, L - m + 1, K * 4)
    segs = np.stack([X[r, s:s + m] for r, s in zip(rows, starts)])
    segs = segs - segs.mean(1, keepdims=True)
    rms = float(np.sqrt((segs ** 2).mean()))
    if cfg['shp_init'] == 'sample':
        return torch.from_numpy(segs[:K].astype(np.float32))
    if cfg['shp_init'] == 'noise':
        return torch.from_numpy(gen_np.normal(0.0, rms, (K, m)).astype(np.float32))
    raise ValueError(f"🍆 АЙ, ОШИБКА! shp_init '{cfg['shp_init']}'")


class SimpleBase(nn.Module):
    """Два числа окна вместо формы — то, что трейдер посчитает без всякой модели:
       log амплитуды пути в единицах своего шага (то, что по итогу ZMAD несёт главное
       отклонение от случайности) и эффективность хода ER = |итог| / сумма |шагов|.
       Сколько SMC добавляет сверх них — цена «формы» как таковой."""
    FEATS = ('log амплитуды', 'ER')

    def __init__(self, L, hidden):
        super().__init__()
        self.L = L
        self.register_buffer('mu', torch.zeros(2))
        self.register_buffer('sd', torch.ones(2))
        self.net = mlp(2, hidden)

    @staticmethod
    def raw(x):
        xc = x - x.mean(1, keepdim=True)
        log_amp = torch.log(xc.pow(2).mean(1).sqrt() + 1e-6)
        steps = x[:, 1:] - x[:, :-1]
        er = (x[:, -1] - x[:, 0]).abs() / steps.abs().sum(1).clamp_min(1e-6)
        return torch.stack([log_amp, er], dim=1)

    @torch.no_grad()
    def set_stats(self, x):
        f = self.raw(x)
        self.mu.copy_(f.mean(0))
        self.sd.copy_(f.std(0).clamp_min(1e-6))

    def forward(self, x):
        return self.net((self.raw(x) - self.mu) / self.sd).squeeze(1), None, None, None

    def pine_cost(self):
        return 3 * self.L + sum(m.in_features * m.out_features for m in self.net if isinstance(m, nn.Linear))


class LadderBase(SimpleBase):
    """Лестница масштабов пути — многомасштабная эффективность хода, без форм: log амплитуды,
       для масштабов s = 2, 4, 8, … < L — log(длина пути по точкам через s баров / длина пути по
       всем барам), и ER всего окна. У случайного блуждания длина пути на масштабе s падает как
       1/√s; у пилы — быстрее (ход «съедается» откатами), у тренда — медленнее. Если лестница
       догоняет SMC, «формы» сверх многомасштабного отката ничего не видят."""
    def __init__(self, L, hidden):
        nn.Module.__init__(self)
        self.L = L
        self.scales = [2 ** i for i in range(1, 10) if 2 ** i < L]
        n = 2 + len(self.scales)
        self.FEATS = tuple(['log амплитуды'] + [f'log путь@{s_}' for s_ in self.scales] + ['ER'])
        self.register_buffer('mu', torch.zeros(n))
        self.register_buffer('sd', torch.ones(n))
        self.net = mlp(n, hidden)

    def raw(self, x):
        xc = x - x.mean(1, keepdim=True)
        feats = [torch.log(xc.pow(2).mean(1).sqrt() + 1e-6)]
        base = (x[:, 1:] - x[:, :-1]).abs().sum(1).clamp_min(1e-6)
        for s_ in self.scales:
            xs = x[:, ::s_]
            feats.append(torch.log((xs[:, 1:] - xs[:, :-1]).abs().sum(1).clamp_min(1e-6) / base))
        feats.append((x[:, -1] - x[:, 0]).abs() / base)
        return torch.stack(feats, dim=1)


class FrozenDict(nn.Module):
    """Словарь SuMo как есть: ближайший центроид -> буква -> её log lift на FIT."""
    def __init__(self, C, group):
        super().__init__()
        self.register_buffer('protos', torch.as_tensor(C).float())
        self.register_buffer('group', torch.as_tensor(group).long())
        self.register_buffer('table', torch.zeros(int(group.max()) + 1))
        self.K, self.L = C.shape

    def dist_matrix(self, x):
        C = self.protos
        return ((x * x).mean(1, keepdim=True) - 2.0 * (x @ C.t()) / self.L
                + (C * C).mean(1)[None, :]).clamp_min(0.0)

    def forward(self, x):
        D = self.dist_matrix(x)
        k = D.argmin(dim=1)
        P = F.one_hot(k, self.K).float()
        return self.table[self.group[k]], D, P, D.min(dim=1).values

    def pine_cost(self):
        return self.K * self.L


def load_dict(name, L):
    """Словарь SuMo из npz: центроиды, группы, пол. 'auto' — FINAL при L=64, R1 при L=32."""
    if name == 'auto':
        name = {64: 'FINAL', 32: 'R1'}.get(L)
        if name is None:
            raise ValueError(f"🍆 АЙ, ОШИБКА! для L={L} нет словаря по умолчанию")
    a, tf = DATA['assets'][0], DATA['timeframe'].upper()
    for t in [name] + (['R17'] if name == 'FINAL' else []):
        p = project_path + f"sumo_{a}_{tf}_{t}.npz"
        if os.path.isfile(p):
            d = np.load(p, allow_pickle=True)
            norm = str(d['shape_norm']) if 'shape_norm' in d.files else 'ret_med'
            C = d['centers'].astype(np.float32)
            if C.shape[1] != L or norm != 'ret_med':
                raise ValueError(f"🍆 АЙ, ОШИБКА! словарь '{t}': L={C.shape[1]}, форма {norm} "
                                 f"(нужно L={L}, ret_med)")
            return {'name': name, 'tag': t, 'C': C, 'group': d['group'].astype(np.int64),
                    'floor': float(d['floor']) if 'floor' in d.files else None}
    raise FileNotFoundError(f"🍆 АЙ, ОШИБКА! нет словаря '{name}' ({a} {tf})")


# =====================================================================
# СХОДСТВО ПРОТОТИПОВ (из SuMo: корреляция со сдвигом, слияние complete-linkage)
# =====================================================================
def lag_corr(A, B, max_lag=None):
    """Максимум корреляции строк A и B по сдвигам до ±L/4 (как sumo_proto_corr)."""
    L = A.shape[1]
    max_lag = max(1, L // 4) if max_lag is None else max_lag
    A, B = A.astype(np.float64), B.astype(np.float64)
    best = np.full((len(A), len(B)), -1.0)
    for lag in range(-max_lag, max_lag + 1):
        if lag >= 0:
            a, b = A[:, lag:], B[:, :L - lag]
        else:
            a, b = A[:, :L + lag], B[:, -lag:]
        a = a - a.mean(1, keepdims=True)
        b = b - b.mean(1, keepdims=True)
        na = np.linalg.norm(a, axis=1)
        nb = np.linalg.norm(b, axis=1)
        a = a / np.where(na > 1e-12, na, 1.0)[:, None]
        b = b / np.where(nb > 1e-12, nb, 1.0)[:, None]
        best = np.maximum(best, a @ b.T)
    return np.clip(best, -1.0, 1.0)


def dict_prox(C, Dc, norm=False):
    """Близость формы к словарю SuMo: расстояние до ближайшей буквы словаря в долях
       типичного расстояния между соседними буквами самого словаря (< 0.5 — та же буква)."""
    if norm:
        C = np.stack([_prep_curve(c, True) for c in C])
        Dc = np.stack([_prep_curve(c, True) for c in Dc])
    d = np.sqrt(np.maximum(((C[:, None, :] - Dc[None]) ** 2).mean(-1), 0)).min(1)
    dd = np.sqrt(np.maximum(((Dc[:, None, :] - Dc[None]) ** 2).mean(-1), 0))
    np.fill_diagonal(dd, np.inf)
    return d / max(float(np.median(dd.min(1))), 1e-12)


# =====================================================================
# МЕТРИКИ (numpy): AUC с ошибкой по неделям, калибровка, покрытие
# =====================================================================
def bce_of(sp, sn):
    return float((np.logaddexp(0, -sp).sum() + np.logaddexp(0, sn).sum()) / (len(sp) + len(sn)))


def auc_parts(sp, sn):
    """AUC и вклады окон в него (проекция Хайека): их суммы по неделям дают честную
       ошибку при перекрытых окнах и сериальной зависимости."""
    n1, n0 = len(sp), len(sn)
    sn_s, sp_s = np.sort(sn), np.sort(sp)
    lo, hi = np.searchsorted(sn_s, sp, 'left'), np.searchsorted(sn_s, sp, 'right')
    v10 = (lo + 0.5 * (hi - lo)) / n0
    lo, hi = np.searchsorted(sp_s, sn, 'left'), np.searchsorted(sp_s, sn, 'right')
    v01 = ((n1 - hi) + 0.5 * (hi - lo)) / n1
    auc = float(v10.mean())
    return auc, (v10 - auc) / n1, (v01 - auc) / n0


def cluster_se(infl, weeks):
    x, w = np.concatenate(infl), np.concatenate(weeks)
    _, inv = np.unique(w, return_inverse=True)
    s = np.bincount(inv, weights=x)
    G = len(s)
    return float(np.sqrt(G / max(G - 1, 1) * np.sum(s ** 2)))


def auc_se(sp, sn, wp, wn):
    auc, ip, i0 = auc_parts(sp, sn)
    return auc, cluster_se([ip, i0], [wp, wn])


def auc_diff(spa, sna, spb, snb, wp, wn):
    a, ipa, ina = auc_parts(spa, sna)
    b, ipb, inb = auc_parts(spb, snb)
    return a - b, cluster_se([ipa - ipb, ina - inb], [wp, wn])


def paired_win(sp, sn, wk):
    """Доля пар «реальное окно оценено выше своего суррогата»; шум — 0.5."""
    x = (sp > sn) + 0.5 * (sp == sn)
    m = float(x.mean())
    return m, cluster_se([(x - m) / len(x)], [wk])


def platt_fit(sp, sn, iters=30):
    """Калибровка a·logit + b на TUNE (логистическая регрессия на одном признаке)."""
    s = np.concatenate([sp, sn])
    y = np.concatenate([np.ones(len(sp)), np.zeros(len(sn))])
    a, b = 1.0, 0.0
    for _ in range(iters):
        p = 1.0 / (1.0 + np.exp(-(a * s + b)))
        g = np.array([((p - y) * s).mean(), (p - y).mean()])
        w = p * (1 - p)
        H = np.array([[(w * s * s).mean(), (w * s).mean()], [(w * s).mean(), w.mean()]])
        step = np.linalg.solve(H + 1e-9 * np.eye(2), g)
        a, b = a - step[0], b - step[1]
        if np.abs(step).max() < 1e-10:
            break
    return float(a), float(b)


def calib_table(sp, sn, a, b, nb=10):
    """Бины по калиброванной p (квантили), средняя p, доля реальных, ECE."""
    s = a * np.concatenate([sp, sn]) + b
    p = 1.0 / (1.0 + np.exp(-s))
    y = np.concatenate([np.ones(len(sp)), np.zeros(len(sn))])
    edges = np.quantile(p, np.linspace(0, 1, nb + 1))
    idx = np.clip(np.searchsorted(edges, p, side='right') - 1, 0, nb - 1)
    rows, ece = [], 0.0
    for k in range(nb):
        m = idx == k
        if m.any():
            rows.append((float(p[m].min()), float(p[m].max()), float(p[m].mean()),
                         float(y[m].mean()), int(m.sum())))
            ece += m.mean() * abs(p[m].mean() - y[m].mean())
    return rows, float(ece)


def lift_ci(fp, fn, wp, wn, B=500, seed=0):
    """Покрытие реала и суррогата отмеченными окнами, реализованный lift и его
       95%-интервал бутстрепом по неделям (недели тянутся целиком)."""
    weeks = np.union1d(wp, wn)
    ip, in_ = np.searchsorted(weeks, wp), np.searchsorted(weeks, wn)
    G = len(weeks)
    a, na = np.bincount(ip, weights=fp, minlength=G), np.bincount(ip, minlength=G)
    c, nc = np.bincount(in_, weights=fn, minlength=G), np.bincount(in_, minlength=G)
    cov_p, cov_n = a.sum() / na.sum(), c.sum() / nc.sum()
    rng = np.random.default_rng(seed)
    pick = rng.integers(0, G, size=(B, G))
    bp = a[pick].sum(1) / np.maximum(na[pick].sum(1), 1)
    bn = c[pick].sum(1) / np.maximum(nc[pick].sum(1), 1)
    lifts = bp / np.maximum(bn, 1e-12)
    lift = cov_p / cov_n if cov_n > 0 else (np.inf if cov_p > 0 else np.nan)
    return (float(cov_p), float(cov_n), float(lift),
            float(np.percentile(lifts, 2.5)), float(np.percentile(lifts, 97.5)))


def bar_cover(data, starts, flags, L):
    """Доля баров VALIDATION, закрытых хотя бы одним отмеченным окном (краска на весь
       сэмпл). Для сравнения — доля окон, если красить только последний бар окна."""
    st = starts[flags]
    mark = np.zeros(len(data.r) + 1, dtype=np.int32)
    np.add.at(mark, st, 1)
    np.add.at(mark, st + L, -1)
    covered = np.cumsum(mark)[:-1] > 0
    bars = (data.part == 1) & np.isfinite(data.r)
    return float(covered[bars].mean())


# =====================================================================
# ОЦЕНКА МОДЕЛИ
# =====================================================================
def uses_side(model):
    """Модели нужен S: боковые входы в голову или (v5.4) нормы H_k пирамиды 'hist'."""
    return bool(getattr(model, 'needs_s', False) or getattr(model, 'side_cols', None))


def fwd(model, X, S=None):
    """Вызов модели: с боковыми входами (v4.4) — model(X, S), без — model(X)."""
    return model(X, S) if uses_side(model) else model(X)


def pine_weights(model):
    """v6.3: сколько чисел весов модели уходит в Pine — все обучаемые параметры (у потоковой CNN — свёртки и голова). Бюджет
       одного скрипта TradingView — PB_W_MAX (float32 тремя знаками CJK; замеры — в репо, docs/pine_limits.md). Буферы
       (масштабы входов, десятки чисел) не считаются."""
    return int(sum(p.numel() for p in model.parameters()))


def pine_weights_cfg(cfg):
    """v6.3: то же по конфигурации потоковой CNN, без постройки модели (у прогонов до v6.3 в json нет 'pine_w');
       None — не потоковая CNN (там бюджет весов не считается)."""
    if cfg.get('arch') != 'cnn' or cfg.get('cnn_in', 'steps') != 'steps' or cfg.get('cnn_pyr') or cfg.get('cnn_chan'):
        return None
    n_ch = (N_PATH + N_LEVEL.get(cfg.get('price'), 0)) if cfg.get('price') in MULTI_KINDS else 1
    ch, k, n_l, b = int(cfg['cnn_ch']), int(cfg['cnn_k']), len(cfg['cnn_dil']) - 1, bool(cfg.get('cnn_bias', True))
    conv = k * n_ch * ch + b * ch
    conv += n_l * ((k * ch + ch * ch + 2 * b * ch) if cfg.get('cnn_sep') else (k * ch * ch + b * ch))
    n_in = {'mml': 3, 'mm': 2, 'last': 1}[cfg.get('cnn_pool', 'mml')] * ch + (len(SIDE_COLS[cfg['side']]) if cfg.get('side') else 0)
    head = 0
    for h in tuple(cfg.get('head_hidden') or ()):
        head += n_in * int(h) + int(h)
        n_in = int(h)
    return int(conv + head + n_in + 1)


def pine_cost_cfg(cfg):
    """v6.3: умножений на бар в Pine у потоковой CNN по конфигурации (как CNNBase.pine_cost): два потока свёрток по одной
       новой позиции на бар + голова. None — не потоковая CNN."""
    if pine_weights_cfg(cfg) is None or not cfg.get('cnn_valid') or cfg.get('cnn_bias', True) or cfg.get('cnn_bn'):
        return None
    n_ch = (N_PATH + N_LEVEL.get(cfg.get('price'), 0)) if cfg.get('price') in MULTI_KINDS else 1
    ch, k, n_l = int(cfg['cnn_ch']), int(cfg['cnn_k']), len(cfg['cnn_dil']) - 1
    per_pos = k * ch * n_ch + n_l * ((k * ch + ch * ch) if cfg.get('cnn_sep') else k * ch * ch)
    n_in = {'mml': 3, 'mm': 2, 'last': 1}[cfg.get('cnn_pool', 'mml')] * ch + (len(SIDE_COLS[cfg['side']]) if cfg.get('side') else 0)
    head = 0
    for h in tuple(cfg.get('head_hidden') or ()) + (1,):
        head += n_in * int(h)
        n_in = int(h)
    return int(2 * per_pos + head)


def pine_of_run(r):
    """v6.3: (весов, умножений на бар) прогона — из json (v6.3) или по его конфигурации."""
    c_ = {**SMC_BASE, **(r.get('cfg') or {})}
    return (r.get('pine_w') or pine_weights_cfg(c_)), (r.get('pine') or pine_cost_cfg(c_))


@torch.no_grad()
def score(model, X, bs=65536, S=None):
    """Сырые logit окон X. Модели с боковыми входами нужен S (у непарных суррогатов его нет -> None)."""
    if uses_side(model) and S is None:
        return None
    bs = min(bs, getattr(model, 'EVAL_BS', bs))
    model.eval()
    out = torch.cat([fwd(model, X[i:i + bs], None if S is None else S[i:i + bs])[0].float().cpu()
                     for i in range(0, len(X), bs)])
    model.train()
    return out.numpy().astype(np.float64)


@torch.no_grad()
def assign(model, X, bs=65536):
    labs, dmin = [], []
    for i in range(0, len(X), bs):
        d, k = model.dist_matrix(X[i:i + bs]).min(dim=1)
        labs.append(k.cpu())
        dmin.append(d.cpu())
    return torch.cat(labs).numpy(), torch.cat(dmin).numpy()


@torch.no_grad()
def nearest(X, C, bs=65536):
    """Ближайший центроид словаря (евклид), без матрицы окна x центроиды x L."""
    Ct = torch.as_tensor(C, device=X.device, dtype=X.dtype)
    cn = (Ct * Ct).sum(1)
    return torch.cat([(cn[None, :] - 2.0 * X[i:i + bs] @ Ct.t()).argmin(1).cpu()
                      for i in range(0, len(X), bs)]).numpy()


def eval_set(model, ev):
    sp, sn = score(model, ev['Xp'], S=ev.get('Sp')), score(model, ev['Xn'], S=ev.get('Sn'))
    if sp is None or sn is None:          # модель с боковыми входами против непарного суррогата
        return None, None, None
    auc, se = auc_se(sp, sn, ev['wp'], ev['wn'])
    out = {'bce': bce_of(sp, sn), 'auc': auc, 'auc_se': se, 'n': len(sp),
           'lg_mean_p': float(sp.mean()), 'lg_mean_n': float(sn.mean()),
           'lg_sd': float(np.concatenate([sp, sn]).std())}
    if ev['paired']:
        out['win'], out['win_se'] = paired_win(sp, sn, ev['wp'])
    return out, sp, sn


# ---- v6.7: сеть видит направление — зеркальная проверка
def mirror_scores(model, X, S=None, bs=65536):
    """v6.7: сырые logit на зеркальных входах (mirror_inputs: каждый бар окна и истории перевёрнут — вход зеркального рынка).
       None — модели нужны боковые входы, а их нет."""
    if uses_side(model) and S is None:
        return None
    n_level, lvl_signed = getattr(model, 'n_level', 0), getattr(model, 'lvl_signed', ())
    out = []
    for i in range(0, len(X), bs):
        xm, sm = mirror_inputs(X[i:i + bs], None if S is None else S[i:i + bs], n_level, lvl_signed)
        out.append(score(model, xm, S=sm))
    return np.concatenate(out) if out else np.zeros(0)


def window_dir(X):
    """v6.7: направление окна — знак хода close за окно (конец формы минус начало; у входа без ориентации — настоящий знак)."""
    x0 = X[:, 0] if X.dim() == 3 else X
    return torch.sign(x0[:, -1] - x0[:, 0]).cpu().numpy().astype(np.int8)


def dir_check(model, parts):
    """v6.7, зеркальная проверка модели без ориентации. parts — {'tune' | 'val': (набор проверки, logit реала, logit суррогатов)}.
       f — logit, f̄ — logit на зеркальном входе; s = (f + f̄) / 2 — симметричная часть, a = (f − f̄) / 2 — антисимметричная.
       Δ_mirror = AUC(f) − AUC(f̄) на тех же парах «реал — его суррогат» (на зеркальном наборе оба зеркальные): у симметричного
       рынка зеркальный набор распределён так же, как исходный, — Δ_mirror ≈ 0 у любой модели; > 0 — асимметрия рынка, выученная
       верно. Рядом: AUC одной s, sd(a) / sd(s), корреляция a с направлением окна, Δ_mirror отдельно у окон вверх и вниз.
       Возвращает (сводка, массивы для npz: <часть>_spm / _snm — logit зеркальных наборов, <часть>_dirp — направление реала)."""
    info, arrs = {}, {}
    for nm, (ev, sp, sn) in parts.items():
        if ev is None or sp is None or sn is None:
            continue
        spm, snm = mirror_scores(model, ev['Xp'], ev.get('Sp')), mirror_scores(model, ev['Xn'], ev.get('Sn'))
        if spm is None or snm is None:
            continue
        wp, wn = ev['wp'], ev['wn']
        auc_m, _ = auc_se(spm, snm, wp, wn)
        d, dse = auc_diff(sp, sn, spm, snm, wp, wn)
        s_p, s_n, a_p, a_n = 0.5 * (sp + spm), 0.5 * (sn + snm), 0.5 * (sp - spm), 0.5 * (sn - snm)
        auc_s, _ = auc_se(s_p, s_n, wp, wn)
        dp = window_dir(ev['Xp'])
        by_dir = {}
        if ev['paired']:
            for key_, msk in (('up', dp > 0), ('down', dp < 0)):
                if msk.sum() >= 1000:
                    d_, se_ = auc_diff(sp[msk], sn[msk], spm[msk], snm[msk], wp[msk], wn[msk])
                    by_dir[key_] = {'n': int(msk.sum()), 'd': d_, 'se': se_, 'a_mean': float(a_p[msk].mean())}
        sd_a, sd_s = float(np.concatenate([a_p, a_n]).std()), float(np.concatenate([s_p, s_n]).std())
        ok = a_p.std() > 0 and dp.std() > 0
        info[nm] = {'auc': float(auc_se(sp, sn, wp, wn)[0]), 'auc_mirror': auc_m, 'd_mirror': d, 'd_mirror_se': dse,
                    'auc_sym': auc_s, 'sd_a': sd_a, 'sd_s': sd_s,
                    'corr_a_dir': float(np.corrcoef(a_p, dp)[0, 1]) if ok else np.nan, 'by_dir': by_dir,
                    'up_share': float((dp > 0).mean())}
        arrs[f'{nm}_spm'], arrs[f'{nm}_snm'] = spm.astype(np.float32), snm.astype(np.float32)
        arrs[f'{nm}_dirp'] = dp
    return info, arrs


def print_dir(info):
    """v6.7: печать зеркальной проверки (dir_check)."""
    if not info:
        return
    print("\n🧭 НАПРАВЛЕНИЕ (v6.7; вход без ориентации): f = s + a; s — симметричная часть (её видит и зеркально-симметричная сеть), "
          "a — антисимметричная (a(зеркало) = −a: асимметрия «вверх против вниз»). Δ_зеркало — AUC набора минус AUC того же набора у "
          "зеркального рынка (реал и суррогат перевёрнуты вместе); у симметричного рынка ≈ 0 у любой модели")
    print(f"   {'часть':<6} {'AUC':>8} {'AUC зерк.':>10} {'Δ_зеркало':>17} {'AUC только s':>13} {'sd a / sd s':>12} "
          f"{'corr(a, напр.)':>15} {'окон вверх':>11} {'Δ_зерк. вверх':>18} {'Δ_зерк. вниз':>18}")
    for nm, r in info.items():
        bd = r.get('by_dir') or {}

        def dd(k):
            x = bd.get(k)
            return f"{x['d']:+.4f}±{x['se']:.4f}" if x else '—'
        print(f"   {nm.upper():<6} {r['auc']:>8.4f} {r['auc_mirror']:>10.4f} {r['d_mirror']:>+9.4f}±{r['d_mirror_se']:.4f} "
              f"{r['auc_sym']:>13.4f} {r['sd_a'] / max(r['sd_s'], 1e-12):>12.3f} {_f(r['corr_a_dir'], '+.3f', width=15)} "
              f"{100 * r['up_share']:>10.1f}% {dd('up'):>18} {dd('down'):>18}")


def usage_stats(lab, K, dead_frac):
    u = np.bincount(lab, minlength=K) / max(1, len(lab))
    nz = u[u > 0]
    return {'effK': float(np.exp(-(nz * np.log(nz)).sum())), 'dead': int((u < dead_frac / K).sum()),
            'maxU': float(u.max()), 'u': u}


# =====================================================================
# РИСУНКИ (сохраняются в папку прогона)
# =====================================================================
def _lift_color(v):
    return C_MORE if v >= 1.05 else (C_LESS if v <= 1 / 1.05 else C_MID)


def _prep_curve(c, norm):
    y = c - c.mean()
    return y / max(np.sqrt((y ** 2).mean()), 1e-12) if norm else y


def _axes_clean(ax):
    ax.set_facecolor('#fcfcfb')
    ax.set_xticks([])
    ax.set_yticks([])
    for sp_ in ax.spines.values():
        sp_.set_color(C_GRID)


def fig_grid(C, usage, lift, title, path, show=False, norm=False):
    """Сетка форм по 8 в ряд, по убыванию частоты. У каждой формы своя шкала (иначе мелкие
       формы — плоские линии); амплитуда — в подписи: номер, доля окон реала, lift, a =
       средний квадратичный размах. Цвет: красный — чаще у реала, синий — реже, серый ≈ 1."""
    K, L = C.shape
    order = np.argsort(-usage)
    Y = np.stack([_prep_curve(c, norm) for c in C])
    ncol = 8
    nrow = int(math.ceil(K / ncol))
    fig, axes = plt.subplots(nrow, ncol, figsize=(2.0 * ncol, 1.45 * nrow + 0.6), squeeze=False)
    fig.patch.set_facecolor('#fcfcfb')
    for j, ax in enumerate(axes.ravel()):
        _axes_clean(ax)
        if j >= K:
            ax.axis('off')
            continue
        k = order[j]
        amp = np.sqrt((Y[k] ** 2).mean())
        ax.axhline(0, color=C_GRID, lw=0.8)
        ax.plot(np.arange(L), Y[k], color=_lift_color(lift[k]), lw=1.6)
        ax.set_title(f"#{k} {100 * usage[k]:.1f}% ×{lift[k]:.2f} a{amp:.1f}", fontsize=8, color=C_INK2)
    fig.suptitle(title + (" (формы нормированы)" if norm else ", шкала у каждой своя"), fontsize=10,
                 color=C_INK)
    fig.tight_layout()
    fig.savefig(path, dpi=110, facecolor=fig.get_facecolor())
    if show and IN_COLAB:
        plt.show()
    plt.close(fig)


def fig_evolution(snaps, order, path, norm=False):
    """Эволюция форм (замечание 8): строки — эпохи (последняя — лучшая), столбцы —
       8 самых частых форм итоговой модели; шкала общая внутри столбца."""
    cols = order[:8]
    Y = {lab: np.stack([_prep_curve(C[k], norm) for k in cols]) for lab, C in snaps}
    lim = np.max(np.stack([np.abs(y).max(1) for y in Y.values()]), axis=0) * 1.08
    fig, axes = plt.subplots(len(snaps), len(cols), figsize=(2.0 * len(cols), 1.2 * len(snaps) + 0.5),
                             squeeze=False)
    fig.patch.set_facecolor('#fcfcfb')
    for i, (lab, _) in enumerate(snaps):
        for j, k in enumerate(cols):
            ax = axes[i, j]
            _axes_clean(ax)
            ax.axhline(0, color=C_GRID, lw=0.8)
            ax.plot(Y[lab][j], color=C_LESS, lw=1.4)
            ax.set_ylim(-lim[j], lim[j])
            if i == 0:
                ax.set_title(f"#{k}", fontsize=8, color=C_INK2)
            if j == 0:
                ax.set_ylabel(lab, fontsize=8, color=C_INK2)
    fig.tight_layout()
    fig.savefig(path, dpi=100, facecolor=fig.get_facecolor())
    plt.close(fig)


def fig_heat(C, R, path, title):
    """Сходство форм между собой: слева — евклидово расстояние (на точку; тёмное — почти
       дубль), справа — корреляция со сдвигом до ±L/4. Порядок — иерархическая
       кластеризация: похожие формы видны блоками. Только картинка, склейки нет."""
    from scipy.cluster.hierarchy import linkage, leaves_list
    from scipy.spatial.distance import squareform
    K, L = C.shape
    Dm = np.sqrt(np.maximum(((C[:, None, :] - C[None, :, :]) ** 2).mean(-1), 0))
    order = leaves_list(linkage(squareform(Dm, checks=False), 'average')) if K > 2 else np.arange(K)
    seq = LinearSegmentedColormap.from_list('smc_seq', ['#0d366b', '#2a78d6', '#86b6ef', '#cde2fb',
                                                        '#fcfcfb'])
    fig, axes = plt.subplots(1, 2, figsize=(12.4, 5.6))
    fig.patch.set_facecolor('#fcfcfb')
    Do = Dm[np.ix_(order, order)].copy()
    np.fill_diagonal(Do, np.nan)
    for ax, M, cmap, lim, lab in ((axes[0], Do, seq, (0, np.nanpercentile(Do, 95)),
                                   'расстояние (корень из среднего квадрата разности)'),
                                  (axes[1], R[np.ix_(order, order)], CMAP_DIV, (-1, 1),
                                   'корреляция со сдвигом до ±L/4')):
        im = ax.imshow(M, cmap=cmap, vmin=lim[0], vmax=lim[1], interpolation='nearest')
        ax.set_xticks(range(K))
        ax.set_yticks(range(K))
        ax.set_xticklabels(order, fontsize=5 if K > 48 else 7, rotation=90, color=C_INK2)
        ax.set_yticklabels(order, fontsize=5 if K > 48 else 7, color=C_INK2)
        cb = fig.colorbar(im, ax=ax, shrink=0.8)
        cb.ax.tick_params(labelsize=7, colors=C_INK2)
        cb.set_label(lab, fontsize=8, color=C_INK2)
    fig.suptitle(title, fontsize=10, color=C_INK)
    fig.tight_layout()
    fig.savefig(path, dpi=110, facecolor=fig.get_facecolor())
    plt.close(fig)


def _pick_apart(order, st, L, n):
    """Первые n окон по порядку order, чьи начала дальше L баров от уже взятых (окна не перекрыты)."""
    out = []
    for i in order:
        if all(abs(int(st[i]) - int(st[j])) >= L for j in out):
            out.append(int(i))
            if len(out) == n:
                break
    return out


def fig_extremes(store, sp, a, b, title, path, n=16, show=False):
    """v4.2: реальные окна VALIDATION, которые модель считает самыми «неслучайными» (верхние строки,
       красные — наибольшая оценка lift) и самыми «похожими на суррогат» (нижние, синие — наименьшая).
       Окна не перекрываются. Рисуется путь цены окна: сумма шагов от нуля в единицах медианы |шага|
       окна, у каждого окна своя шкала; модель видит путь с точностью до зеркала (форма
       симметризуется по знаку). Подпись — время конца окна и оценка lift после калибровки на TUNE.
       sp — сырые logit реальных окон набора store.get('val', ...) в его порядке."""
    P = store.positives('val')
    L, st = store.L, P['st']
    if len(sp) != len(st):
        print(f"⚠️ extremes: оценок {len(sp)}, окон {len(st)} — рисунок пропущен")
        return False
    lift = np.exp(a * np.asarray(sp, dtype=np.float64) + b)
    order = np.argsort(-lift, kind='stable')
    groups = ((_pick_apart(order, st, L, n), C_MORE), (_pick_apart(order[::-1], st, L, n), C_LESS))
    ncol = 8
    nr = int(math.ceil(n / ncol))
    fig, axes = plt.subplots(2 * nr, ncol, figsize=(2.0 * ncol, 3.0 * nr + 1.0), squeeze=False)
    fig.patch.set_facecolor('#fcfcfb')
    for g, (idx, col) in enumerate(groups):
        it = torch.from_numpy(np.asarray(idx, dtype=np.int64)).to(DEVICE)
        W = P['W'][it]
        if W.dim() == 3:                       # v4.6: у 'multi' рисуется путь close
            W = W[:, 0]
        div = torch.maximum(median_abs(W), P['fl'][it])
        Y = (torch.cumsum(W, dim=1) / div[:, None]).cpu().numpy()
        Y = np.concatenate([np.zeros((len(Y), 1)), Y], axis=1)
        for j in range(nr * ncol):
            ax = axes[g * nr + j // ncol, j % ncol]
            _axes_clean(ax)
            if j >= len(idx):
                ax.axis('off')
                continue
            i = idx[j]
            ax.axhline(0, color=C_GRID, lw=0.8)
            ax.plot(np.arange(L + 1), Y[j], color=col, lw=1.4)
            t_end = pd.Timestamp(int(store.data.t[st[i] + L - 1]))
            ax.set_title(f"{t_end:%Y-%m-%d %H:%M} ×{lift[i]:.2f}", fontsize=7.5, color=C_INK2)
    fig.suptitle(f"{title}\nверхние {nr} ряда — наибольшая оценка lift (красные), нижние {nr} — наименьшая (синие); "
                 f"путь цены окна в единицах медианы |шага|, шкала у каждого своя", fontsize=9.5, color=C_INK)
    fig.tight_layout()
    fig.savefig(path, dpi=110, facecolor=fig.get_facecolor())
    if show and IN_COLAB:
        plt.show()
    plt.close(fig)
    return True


@torch.no_grad()
def cnn_forms(model, X, st, S=None, n_top=48, bs=16384):
    """v4.4, «формы чемпиона»: что видит каждый канал последнего слоя CNN. Для канала — n_top окон,
       где он включается сильнее всего (разные события: места активации дальше поля зрения друг от
       друга), и средний путь цены по его полю зрения. Вклад канала в оценку — «градиент × значение»
       его признаков после пулинга, среднее по окнам: + — толкает к «реалу», − — к «суррогату».
       v5.4: у пирамид 'sum' / 'haar' места — клетки пирамиды, а не время: «форм» нет (None)."""
    pyr = getattr(model, 'pyr', None)
    if pyr in ('sum', 'haar') or (pyr is not None and model.pyr_norm == 'hist' and S is None):
        return None
    if getattr(model, 'chan_cols', None) and S is None:   # v5.5: постоянным каналам нужны боковые входы
        return None
    model.eval()
    dev = X.device
    ch, k = model.ch, model.k
    R = sum(model.dils) * (k - 1)                        # поле зрения последнего слоя − 1, в шагах
    valid = model.blocks[0][0].padding[0] == 0
    n_pool = {'mml': 3, 'mm': 2, 'last': 1}[model.pool]
    cand = 4 * n_top
    vals = torch.full((ch, cand), -float('inf'), device=dev)
    idxs = torch.zeros((ch, cand), dtype=torch.long, device=dev)
    poss = torch.zeros((ch, cand), dtype=torch.long, device=dev)
    contrib = torch.zeros(ch, device=dev)
    for i in range(0, len(X), bs):
        h = model.conv_maps(X[i:i + bs], None if S is None else S[i:i + bs])
        m, p_ = h.max(2)
        cv = torch.cat([vals, m.t()], 1)
        ci = torch.cat([idxs, torch.arange(i, i + len(m), device=dev)[None, :].expand(ch, -1)], 1)
        cp = torch.cat([poss, p_.t()], 1)
        top = cv.topk(cand, dim=1).indices
        vals, idxs, poss = cv.gather(1, top), ci.gather(1, top), cp.gather(1, top)
        with torch.enable_grad():
            f = model.pooled(h).detach().requires_grad_(True)
            g_in = f
            if model.side_cols:
                if S is None:
                    continue
                Sc = S[i:i + bs][:, list(model.side_cols)]
                g_in = torch.cat([f, (Sc - model.side_mu) / model.side_sd], dim=1)
            g, = torch.autograd.grad(model.head(g_in).sum(), f)
        contrib += (g * f).view(len(f), n_pool, ch).sum(1).sum(0)
    contrib = (contrib / len(X)).cpu().numpy()
    vals, idxs, poss = vals.cpu().numpy(), idxs.cpu().numpy(), poss.cpu().numpy()
    X0 = X[:, 0] if X.dim() == 3 else X        # v4.6: у 'multi' «формы» — по close-каналу
    Z = ((X0[:, 1:] - X0[:, :-1]) if model.inp != 'shape' else X0).cpu().numpy()
    if pyr == 'ms':                             # v5.4: места 'ms' — 64 бара окна, шаг на месте 0 потерян (0)
        Z = np.pad(Z, ((0, 0), (1, 0)))
    off = 0 if valid else -(R // 2)
    forms, acts = [], []
    for c in range(ch):
        picked = []
        for v_, i_, p_ in zip(vals[c], idxs[c], poss[c]):
            if not np.isfinite(v_):
                continue
            a_ = int(st[i_]) + int(p_)
            if all(abs(a_ - b_) > R for _, _, b_ in picked):
                picked.append((int(i_), int(p_), a_))
                if len(picked) == n_top:
                    break
        segs = np.full((len(picked), R + 1), np.nan)
        for j, (i_, p_, _) in enumerate(picked):
            z = Z[i_]
            lo = p_ + off
            q0, q1 = max(0, -lo), min(R + 1, len(z) - lo)
            if q1 > q0:
                segs[j, q0:q1] = z[lo + q0:lo + q1]
        with warnings.catch_warnings():         # места вне окна у всех примеров -> пусто, это не ошибка
            warnings.simplefilter('ignore', RuntimeWarning)
            mean_seg = np.nan_to_num(np.nanmean(segs, axis=0)) if len(picked) else np.zeros(R + 1)
        # шаги -> путь (сумма средних шагов = средний путь); у входа-формы куски — уже уровни пути
        forms.append(mean_seg if model.inp == 'shape' else np.concatenate([[0.0], np.cumsum(mean_seg)]))
        acts.append(float(np.mean([v_ for v_ in vals[c][:n_top] if np.isfinite(v_)])))
    model.train()
    return np.stack(forms), contrib, np.array(acts)


def fig_cnn_forms(forms, contrib, acts, title, path, show=False):
    """Сетка «форм» каналов: по 8 в ряд, по убыванию |вклада|; красный — канал толкает к «реалу»,
       синий — к «суррогату»; шкала у каждой своя."""
    ch, n = forms.shape
    order = np.argsort(-np.abs(contrib))
    ncol = 8
    nrow = int(math.ceil(ch / ncol))
    fig, axes = plt.subplots(nrow, ncol, figsize=(2.0 * ncol, 1.45 * nrow + 0.7), squeeze=False)
    fig.patch.set_facecolor('#fcfcfb')
    for j, ax in enumerate(axes.ravel()):
        _axes_clean(ax)
        if j >= ch:
            ax.axis('off')
            continue
        c = order[j]
        y = forms[c] - forms[c].mean()
        ax.axhline(0, color=C_GRID, lw=0.8)
        ax.plot(np.arange(n), y, color=C_MORE if contrib[c] > 0 else C_LESS, lw=1.5)
        ax.set_title(f"#{c} вклад {contrib[c]:+.3f}", fontsize=8, color=C_INK2)
    fig.suptitle(title + "\nсредний путь по полю зрения канала в окнах, где канал включён сильнее всего; "
                 "красный — толкает оценку к «реалу», синий — к «суррогату»", fontsize=9.5, color=C_INK)
    fig.tight_layout()
    fig.savefig(path, dpi=110, facecolor=fig.get_facecolor())
    if show and IN_COLAB:
        plt.show()
    plt.close(fig)


def backfill_cnn_forms(r, datas, stores):
    """Рисунок cnn_forms.png для CNN, посчитанной до v4.4: модель восстанавливается из весов в npz
       (у CNN раунда 4 другие имена слоёв — пропуск)."""
    out_dir = RUN_DIR + r['tag'] + '/'
    if (r['cfg'].get('arch') != 'cnn' or r['name'].startswith('C0_')
            or os.path.isfile(out_dir + 'cnn_forms.png')):
        return False
    npz = RUN_DIR + f"smc_{r['tag']}.npz"
    if not os.path.isfile(npz):
        return False
    cfg = {**SMC_BASE, **r['cfg']}
    ev = get_store(datas, stores, cfg.get('price', 'close'), cfg['L']).get('val', r['spec'])
    model, _ = build_model(cfg, ev['Xp'][:5000], np.random.default_rng(0))
    d = np.load(npz)
    sd_ = {k_[3:]: torch.from_numpy(d[k_]) for k_ in d.files if k_.startswith('sd_')}
    try:
        res = model.load_state_dict(sd_, strict=False)
        bad = list(res.unexpected_keys) + [k_ for k_ in res.missing_keys if k_ not in ('side_mu', 'side_sd')]
    except Exception as e:
        bad = [str(e)[:80]]
    if bad:                                # в весах до v4.4 нет только буферов боковых входов — это можно
        print(f"⏭️ {r['tag']}: веса другой версии сети ({bad[0]}…) — «формы» не рисуются")
        return False
    cf = cnn_forms(model, ev['Xp'], ev['st'], ev.get('Sp'))
    if cf is None:                         # v5.4: у пирамид 'sum' / 'haar' места — не время
        return False
    forms, contrib, acts = cf
    os.makedirs(out_dir, exist_ok=True)
    fig_cnn_forms(forms, contrib, acts, f"{r['tag']}: «формы» каналов последнего слоя", out_dir + 'cnn_forms.png')
    print(f"🖼️ дорисовано: {out_dir}cnn_forms.png")
    return True


def backfill_extremes(r, datas, stores):
    """Рисунок extremes.png для прогона, посчитанного до v4.2 (папки MLP / CNN были пустыми: рисунки
       делались только у прототипных моделей). Модель не нужна: оценки окон VALIDATION лежат в npz
       прогона, а сами окна — те же (наборы проверки фиксированы)."""
    out_dir = RUN_DIR + r['tag'] + '/'
    if r['name'].startswith('C0_') or os.path.isfile(out_dir + 'extremes.png'):
        return False
    npz = RUN_DIR + f"smc_{r['tag']}.npz"
    if not os.path.isfile(npz):
        return False
    price = r['cfg'].get('price', 'close')
    store = get_store(datas, stores, price, r['cfg']['L'])
    sp_v = np.load(npz)['val_sp'].astype(np.float64)
    a, b = r['platt']
    os.makedirs(out_dir, exist_ok=True)
    px_note = f" (путь {PRICE_NAMES[price]})" if price != 'close' else ""
    ok = fig_extremes(store, sp_v, a, b, f"{r['tag']}: реальные окна VALIDATION с крайними оценками модели{px_note}",
                      out_dir + 'extremes.png')
    if ok:
        print(f"🖼️ дорисовано: {out_dir}extremes.png")
    return ok


