# ОБУЧЕНИЕ
# =====================================================================
def make_cfg(name, over, seed_key):
    if name not in RUNS:
        raise KeyError(f"🍆 АЙ, ОШИБКА! нет прогона '{name}' в RUNS")
    cfg = copy.deepcopy(SMC_BASE)
    cfg.update(copy.deepcopy(RUNS[name]))
    cfg.update(copy.deepcopy(over or {}))
    cfg['name'], cfg['seed_key'], cfg['seed'] = name, seed_key, SEEDS[seed_key]
    cfg['dict'] = None
    if cfg['arch'] == 'frozen' or str(cfg['init']).startswith('dict:'):
        D = load_dict(str(cfg['init'])[5:], cfg['L'])
        cfg['dict'], cfg['K'] = D, len(D['C'])
    extra = "".join(f"_{k}{v}" for k, v in sorted((over or {}).items()) if k not in ('L', 'K'))
    cfg['label'] = f"{name}_L{cfg['L']}_K{cfg['K']}{extra}".replace(' ', '')
    cfg['tag'] = f"{cfg['label']}_{seed_key}"
    return cfg


def cfg_line(cfg):
    keys = ['arch', 'L', 'K', 'null', 'control', 'dist', 'head_in', 'head_hidden', 'init',
            'temp_learn', 'temp_init', 'freeze_protos', 'lam_clu', 'clu_mode', 'lam_use',
            'use_mode', 'lam_div', 'reinit_dead', 'lr', 'lr_protos', 'batch', 'epochs', 'patience',
            'lr_plateau', 'trim_q', 'fit_from', 'fit_holdout', 'hold_block', 'fit_halflife', 'head_amp', 'p_topk',
            'dropout', 'mlp_in', 'wd', 'aug_mag', 'ema', 'bank2', 'bank_route', 'stop_on', 'fit_plus_tune']
    if cfg['arch'] == 'cnn':
        keys += ['cnn_ch', 'cnn_k', 'cnn_dil', 'cnn_bn', 'cnn_res', 'cnn_cdrop', 'cnn_sdrop', 'cnn_pool', 'cnn_in',
                 'cnn_valid', 'cnn_bias', 'cnn_ma', 'side'] + (['cnn_pyr', 'pyr_norm'] if cfg.get('cnn_pyr') else [])
        keys += ['cnn_chan'] if cfg.get('cnn_chan') else []          # v5.5: постоянные каналы на вход свёрток
        keys += ['lvl_log'] if cfg.get('lvl_log') else []            # v5.7: диапазон бара — логарифмом
        keys += ['cnn_sep'] if cfg.get('cnn_sep') else []            # v6.3: раздельные свёртки
        keys += ['cnn_sym'] if cfg.get('cnn_sym') else []            # v6.4: зеркально-симметричная сеть
        keys += ['cnn_anti'] if cfg.get('cnn_anti') else []          # v6.7: антисимметричная голова
    elif cfg['arch'] == 'attn':
        keys += ['attn_d', 'attn_heads', 'attn_layers']
    elif cfg['arch'] == 'shapelet':
        keys += ['shp_K', 'shp_m', 'shp_init', 'shp_fdrop', 'side']
    if cfg.get('smooth_lam'):                                        # v6.4: штраф скачков соседних окон
        keys += ['smooth_lam', 'smooth_frac', 'smooth_on', 'smooth_warm', 'smooth_mode']   # v6.5: smooth_mode
    keys += ['orient'] if not cfg.get('orient', True) else []        # v6.7: вход без ориентации (абсолютное направление)
    keys += ['mir_aug'] if cfg.get('mir_aug') else []                # v6.7: контроль C0_mir — симметризованный рынок
    keys += ['price', 'price_null']
    return " | ".join(f"{k}={cfg.get(k)}" for k in keys)


def div_loss(C, cfg, st):
    K = len(C)
    iu = torch.triu_indices(K, K, 1, device=C.device)
    if cfg['div_mode'] == 'cos':
        Cn = F.normalize(C - C.mean(1, keepdim=True), dim=1)
        g = (Cn @ Cn.t())[iu[0], iu[1]]
        thr = cfg['div_thr']
        return (F.relu(g - thr) ** 2).mean() / (1 - thr) ** 2
    d = torch.cdist(C, C)[iu[0], iu[1]] / math.sqrt(C.shape[1])
    m = cfg['div_margin'] * st['nn0']
    return (F.relu(m - d) ** 2).mean() / m ** 2


def loss_terms(model, logit, y, D, cfg, st, tau, w_bce):
    """BCE на всех окнах + три лосса на реальных, только для прототипов:
       clu — мягкий минимум расстояния (−τ·logsumexp(−D/τ), τ отжигается);
       use — штраф почти пустым прототипам (или энтропия, как в концепте);
       div — штраф парам почти одинаковых прототипов.
       bank2 (v4.3): clu и use — по банку R на реальных окнах и по банку S на суррогатах."""
    t = {'bce': w_bce * F.binary_cross_entropy_with_logits(logit, y)}
    if D is None or not model.protos.requires_grad:
        return t
    real = y > 0.5
    if cfg.get('bank2'):
        # v4.3, два банка: R (первая половина форм) описывает реальные окна, S — суррогатные
        K2 = D.shape[1] // 2
        parts = [D[real][:, :K2], D[~real][:, K2:]]
    else:
        parts = [D[real]]

    def clu_of(Dx):
        if cfg['clu_mode'] == 'hard':
            return Dx.min(dim=1).values.mean()
        return (-tau * torch.logsumexp(-Dx / tau, dim=1)).mean()

    def use_of(Dx):
        # T отцеплена: иначе лосс частот «выравнивает» использование, просто поднимая T
        Kx = Dx.shape[1]
        u = torch.softmax(-Dx / model.log_T.exp().detach(), dim=1).mean(0)
        if cfg['use_mode'] == 'entropy':
            return (u * torch.log(u + 1e-8)).sum() + math.log(Kx)
        return F.relu(math.log(cfg['use_floor'] / Kx) - torch.log(u + 1e-8)).mean()

    if cfg['lam_clu'] > 0:
        t['clu'] = cfg['lam_clu'] * sum(clu_of(Dx) for Dx in parts) / len(parts) / st['D0']
    if cfg['lam_use'] > 0 and cfg['use_mode'] != 'none':
        t['use'] = cfg['lam_use'] * sum(use_of(Dx) for Dx in parts) / len(parts)
    if cfg['lam_div'] > 0:
        t['div'] = cfg['lam_div'] * div_loss(model.protos, cfg, st)
    return t


def tau_at(ep, cfg, gap0):
    if cfg['clu_mode'] == 'const':
        return cfg['tau0'] * gap0
    a = min(1.0, ep / max(1, cfg['tau_epochs']))
    return gap0 * cfg['tau0'] * (cfg['tau1'] / cfg['tau0']) ** a


@torch.no_grad()
def reinit_dead(model, opt, Xr, cfg, gen):
    """Пустые прототипы (доля окон < dead_frac/K) переезжают на плохо описанные
       реальные окна; их состояние Adam обнуляется."""
    K = model.K
    lab, dmin = assign(model, Xr)
    u = np.bincount(lab, minlength=K) / len(lab)
    dead = np.where(u < cfg['dead_frac'] / K)[0]
    if len(dead) == 0:
        return 0
    worst = np.argsort(-dmin)[:max(len(dead) * 10, len(dmin) // 20)]
    pick = worst[torch.randperm(len(worst), generator=gen, device=gen.device).cpu().numpy()[:len(dead)]]
    dead_t = torch.from_numpy(dead).to(DEVICE)
    model.protos.data[dead_t] = Xr[torch.from_numpy(pick).to(DEVICE)]
    stt = opt.state.get(model.protos, {})
    for k in ('exp_avg', 'exp_avg_sq'):
        if k in stt:
            stt[k][dead_t] = 0.0
    return len(dead)


def init_protos(cfg, Xs, gen_np):
    K, L = cfg['K'], cfg['L']
    how = str(cfg['init'])
    if how.startswith('dict:'):
        return torch.from_numpy(cfg['dict']['C'].copy())
    if how == 'randn':
        return torch.randn(K, L, generator=torch.Generator().manual_seed(cfg['seed'])) * 0.01
    X = Xs.cpu().numpy()
    rms_x = float(np.sqrt(((X - X.mean(1, keepdims=True)) ** 2).mean()))
    if how == 'sample':            # K случайных реальных окон FIT («случайные блоки реального ряда»)
        return torch.from_numpy(X[gen_np.choice(len(X), K, replace=False)].copy())
    if how == 'noise':             # белый шум в масштабе форм: никакой структуры пути
        return torch.from_numpy(gen_np.normal(0.0, rms_x, (K, L)).astype(np.float32))
    if how == 'randwalk':          # случайное блуждание, нормированное как форма ret_med
        W = torch.from_numpy(gen_np.standard_normal((K, L)).astype(np.float32))
        return to_shapes(W, torch.zeros(K))
    if how == 'kmeans':
        Z = X
        if cfg['dist'] == 'cos':
            Z = X - X.mean(1, keepdims=True)
            Z = Z / np.maximum(np.linalg.norm(Z, axis=1, keepdims=True), 1e-12)
        km = MiniBatchKMeans(n_clusters=K, random_state=cfg['seed'], n_init=3, max_iter=300,
                             batch_size=4096).fit(Z)
        C = km.cluster_centers_.astype(np.float32)
        if cfg['dist'] == 'cos':
            # косинусу масштаб прототипа безразличен, а Adam делает шаги одного размера в любых
            # единицах: у единичных векторов (элементы ~0.2) шум шагов в ~10 раз заметнее, чем у
            # форм в единицах шага (элементы ~2) — v1 давал «зубчатые» прототипы. Масштаб форм.
            C = C - C.mean(1, keepdims=True)
            rms_c = np.sqrt((C ** 2).mean(1, keepdims=True)).clip(1e-12)
            C = C / rms_c * rms_x
        return torch.from_numpy(C)
    raise ValueError(f"🍆 АЙ, ОШИБКА! init '{how}'")


def build_model(cfg, Xs, gen_np, Ss=None):
    """Модель и масштабы на старте: D0 (типичное расстояние до ближайшей формы),
       gap0 (типичный зазор до второй ближайшей) — единицы для τ и T. Ss — боковые входы тех же окон."""
    st = {'D0': 1.0, 'gap0': 1.0, 'nn0': 1.0}
    n_level = N_LEVEL.get(cfg.get('price'), 0)              # v5.6-5.7: каналы-уровни (диапазон, положение close) — последние
    if Xs.dim() == 3 and Xs.shape[1] != N_PATH + n_level:
        raise ValueError(f"🍆 АЙ, ОШИБКА! каналов окна {Xs.shape[1]}, а цене '{cfg.get('price')}' нужно {N_PATH + n_level}")
    Xp_ = Xs[:, :N_PATH] if n_level else Xs                  # масштаб шагов — только по каналам-путям
    steps_sd = float((Xp_[..., 1:] - Xp_[..., :-1]).std())
    if Xs.dim() == 3 and cfg['arch'] != 'cnn':
        raise ValueError("🍆 АЙ, ОШИБКА! три цены бара ('multi') — только у CNN")
    if cfg['arch'] == 'mlp':
        sd = float(Xs.std()) if cfg['mlp_in'] == 'shape' else steps_sd
        return MLPBase(cfg['L'], cfg['head_hidden'], sd, cfg['dropout'], cfg['mlp_in']).to(DEVICE), st
    if cfg['arch'] == 'cnn':
        sd = float(Xs.std()) if cfg['cnn_in'] == 'shape' else steps_sd
        model = CNNBase(cfg['L'], cfg['cnn_ch'], cfg['cnn_k'], cfg['cnn_dil'], cfg['head_hidden'],
                        cfg['dropout'], sd, cfg['cnn_bn'], cfg['cnn_res'], cfg['cnn_cdrop'],
                        cfg['cnn_pool'], cfg['cnn_in'], cfg['cnn_sdrop'], cfg['cnn_valid'],
                        cfg['cnn_bias'], cfg['cnn_ma'],
                        SIDE_COLS[cfg['side']] if cfg.get('side') else None,
                        Xs.shape[1] if Xs.dim() == 3 else 1,
                        cfg.get('cnn_pyr'), cfg.get('pyr_norm', 'rw'),
                        CHAN_COLS[cfg['cnn_chan']] if cfg.get('cnn_chan') else None, n_level,
                        cfg.get('lvl_log', False), cfg.get('cnn_sep', False), cfg.get('cnn_sym', False),
                        cfg.get('cnn_anti')).to(DEVICE)                  # v6.7: антисимметричная голова
        if Ss is not None:                     # боковые входы головы и (v5.5) постоянные каналы — масштабы по FIT
            model.set_side_stats(Ss)
        model.set_pyr_sd(Xs, Ss)               # v5.4: у пирамиды — масштаб её значений (иначе ничего не делает)
        model.set_lvl_stats(Xs)                # v5.6: у каналов-уровней — их среднее и sd (иначе ничего не делает)
        return model, st
    if cfg['arch'] == 'shapelet':
        model = ShapeletBase(init_shapelets(cfg, Xs, gen_np), cfg['L'], cfg['head_hidden'],
                             cfg['dropout'], cfg.get('shp_fdrop', 0.0),
                             SIDE_COLS[cfg['side']] if cfg.get('side') else None).to(DEVICE)
        model.set_stats(Xs[:20000])
        if model.side_cols and Ss is not None:
            model.set_side_stats(Ss)
        return model, st
    if cfg['arch'] == 'attn':
        return AttnBase(cfg['L'], cfg['attn_d'], cfg['attn_heads'], cfg['attn_layers'], cfg['head_hidden'],
                        cfg['dropout'], steps_sd).to(DEVICE), st
    if cfg['arch'] in ('simple', 'ladder'):
        model = (SimpleBase if cfg['arch'] == 'simple' else LadderBase)(cfg['L'], cfg['head_hidden']).to(DEVICE)
        model.set_stats(Xs[:50000])
        return model, st
    if cfg['arch'] == 'frozen':
        D = cfg['dict']
        group = np.arange(len(D['C']))                  # клетки словаря; склейки в группы нет
        return FrozenDict(D['C'], group).to(DEVICE), st
    model = SMCModel(init_protos(cfg, Xs, gen_np), cfg).to(DEVICE)
    with torch.no_grad():
        D = model.dist_matrix(Xs[:20000])
        two = D.topk(2, dim=1, largest=False).values
        st['D0'] = float(two[:, 0].median().clamp_min(1e-6))
        st['gap0'] = float((two[:, 1] - two[:, 0]).median().clamp_min(1e-6 * st['D0']))
        C = model.protos
        dd = torch.cdist(C, C) / math.sqrt(cfg['L'])
        dd.fill_diagonal_(float('inf'))
        st['nn0'] = float(dd.min(dim=1).values.median())
        if cfg['temp_init'] == 'auto':
            T0 = st['gap0']
        elif cfg['temp_init'] == 'sum1':        # T = 1 в единицах суммы квадратов (концепт)
            T0 = 1.0 / cfg['L']
        else:
            T0 = float(cfg['temp_init'])
        model.log_T.data.fill_(math.log(T0))
        model.set_stats(Xs[:50000])
    if cfg['freeze_protos'] and cfg['warmup_epochs'] == 0:
        model.protos.requires_grad_(False)
    return model, st


@torch.no_grad()
def fit_frozen(model, data, w, cfg, gen, passes=4):
    """«Обучение» словаря: доли букв реала на FIT и доли у суррогатов (passes проходов
       свежих знаков) -> log lift буквы. Без градиента, как рейтинг lift."""
    pm = PairMaker(data, cfg['L'], cfg, float('inf'), gen)
    G = int(model.group.max()) + 1
    n_p, n_n = np.zeros(G), np.zeros(G)
    idx = fit_windows(w, cfg)
    for p in range(passes):
        for i in range(0, len(idx), 65536):
            j = idx[i:i + 65536]
            st_t = torch.from_numpy(w['st'][j]).to(DEVICE)
            sid_t = torch.from_numpy(w['sid'][j]).to(DEVICE)
            Wp, Wn, fl = pm.make(st_t, sid_t)
            if p == 0:
                k = model.dist_matrix(to_shapes(Wp, fl)).argmin(1)
                n_p += np.bincount(model.group[k].cpu().numpy(), minlength=G)
            k = model.dist_matrix(to_shapes(Wn, fl)).argmin(1)
            n_n += np.bincount(model.group[k].cpu().numpy(), minlength=G)
    n_n /= passes
    model.table.copy_(torch.from_numpy(np.log((n_p + 0.5) / (n_n + 0.5))).float())
    return n_p, n_n


HOLD_PHASE = 2         # какие недели откладываются: номер недели % H == HOLD_PHASE
HOLD_MIN_GAP = 0.01    # разрыв «FIT − TUNE» меньше этого (~2 SE) не делится на части
DAY_NS = 86400 * 10 ** 9


def holdout_masks(t_end, H, B=1):
    """v4.2-4.3, проверка «запоминание или дрейф»: FIT режется на блоки по B недель (B=1 — неделя,
       B=13 — квартал), каждый H-й блок откладывается. excl — окна, которые в обучение НЕ идут:
       конец окна в отложенном блоке или в первые сутки после него (такое окно захватывает бары
       блока). out — окна проверки: конец окна в отложенном блоке, но не в его первые сутки (окно
       целиком внутри блока). Общих баров у окон обучения и проверки нет (окно L <= 256 баров 5M
       короче суток)."""
    blk_end = (t_end // WEEK_NS) // B % H == HOLD_PHASE
    blk_prev = ((t_end - DAY_NS) // WEEK_NS) // B % H == HOLD_PHASE
    return blk_end & blk_prev, blk_end | blk_prev


def hold_key(kind, cfg, year=None):
    """Ключ набора отложенных ('fitout') или обучающих ('fitin') окон FIT для EvalStore."""
    key = f"{kind}:{int(cfg['fit_holdout'])}:{int(cfg.get('hold_block') or 1)}"
    return key + (f":Y{year}" if year is not None else "")


def fit_windows(w, cfg):
    """Окна FIT для градиента: весь FIT или только с fit_from (свежая история); при fit_holdout = H
       без отложенных блоков (каждый H-й блок по hold_block недель и сутки после него); v4.4: при
       fit_plus_tune — FIT и TUNE вместе (TUNE тогда в выборке: сравнение таких моделей — по VAL)."""
    fit = w['fit']
    if cfg.get('fit_plus_tune'):
        fit = np.sort(np.concatenate([w['fit'], w['tune']]))
    if cfg.get('fit_from'):
        fit = fit[w['t_end'][fit] >= pd.Timestamp(cfg['fit_from']).value]
    if cfg.get('fit_holdout'):
        _, excl = holdout_masks(w['t_end'][fit], cfg['fit_holdout'], cfg.get('hold_block') or 1)
        fit = fit[~excl]
    return fit


# =====================================================================
# v6.4: ГЛАДКОСТЬ ЛИНИИ — штраф скачков в обучении и мерки в отчёте
# =====================================================================
def next_in_set(st):
    """v6.4: у каждого окна набора (начала st по возрастанию) — есть ли в том же наборе окно на следующем баре (st + 1)."""
    st = np.asarray(st, dtype=np.int64)
    if len(st) > 1 and not np.all(np.diff(st) > 0):
        raise ValueError("🍆 АЙ, ОШИБКА! next_in_set: начала окон не по возрастанию")
    pos = np.searchsorted(st, st + 1)
    ok = pos < len(st)
    ok[ok] = st[pos[ok]] == st[ok] + 1
    return ok


def _smooth_mode_txt(cfg):
    """v6.5: режим модели в штрафе скачков — для заголовка обучения."""
    return ("модель в штрафе с dropout, маски у пары общие" if cfg.get('smooth_mode', 'train') == 'train'
            else "модель в штрафе без dropout (режим v6.4 — с ошибкой, для воспроизведения)")


def smooth_penalty(model, data, L, st_a, sid_a, floor_t, cfg, lam=None):
    """v6.4: штраф за скачок оценки между соседними реальными окнами (окна на барах st и st + 1, оба из обучения):
       λ · mean((z(st + 1) − z(st))²) / max(var(z), SMOOTH_V0) по тем же окнам — у обученной модели (var(z) > 1) это λ · R² пар
       (R — шероховатость линии из отчёта). Знаменатель — без градиента и с полом SMOOTH_V0: в начале обучения logit почти
       постоянны, и без пола градиент штрафа ~1 / var(z) взрывается — сеть схлопывается в константу (стенд: AUC 0.50 при любом λ);
       сжатию масштаба logit (оно чуть снижает штраф) противостоит BCE, а шкалу R оно не меняет. lam — вес этой эпохи (разгон
       smooth_warm), по умолчанию smooth_lam. smooth_on 'ghost' — среднее только по «призрачным» парам: крупный бар (|шаг close|
       >= LINE_BIG медиан |шага| окна st) уходит из свёрток (бар st + 1), из окна (st) или входит в историю перед окном (st − 1).
       v6.5, smooth_mode — в каком режиме модель в штрафе:
         'train' (по умолчанию) — как у BCE, с dropout, и у обоих окон пары одни и те же маски dropout (перед вторым окном
                 состояние генератора случайных чисел возвращается к тому, что было перед первым): скачок — от сдвига окна на бар,
                 а не от разных масок;
         'eval'  — как в v6.4 (так обучены SM_l05 / l2 / l8 / gh / sym_l2; оставлен для воспроизведения): модель в штрафе без
                 dropout. Это ошибка Claude: BCE видит сеть с dropout, штраф — без, и сеть развела два режима — без dropout гладкая
                 и слепая, с dropout различает (волна SM на BTC: BCE обучения падает до 0.39, BCE на FIT без dropout растёт до 0.97,
                 лучшая эпоха по TUNE — 0; стенд в 300 шагов этого не ловил)."""
    fl = floor_t[sid_a]
    Wa, Wb = data.gw(st_a, L), data.gw(st_a + 1, L)
    Xa, Xb = to_shapes(Wa, fl), to_shapes(Wb, fl)
    Sa = Sb = None
    if uses_side(model):
        Sa, Sb = side_feats(data, st_a, L, Wa, fl), side_feats(data, st_a + 1, L, Wb, fl)
    mode = cfg.get('smooth_mode', 'train')
    if mode == 'eval':
        was = model.training
        model.eval()
        za, zb = fwd(model, Xa, Sa)[0], fwd(model, Xb, Sb)[0]
        if was:
            model.train()
    elif mode == 'train':
        cuda = Xa.is_cuda
        rng = torch.cuda.get_rng_state() if cuda else torch.get_rng_state()
        za = fwd(model, Xa, Sa)[0]
        if cuda:                               # те же маски dropout у второго окна пары
            torch.cuda.set_rng_state(rng)
        else:
            torch.set_rng_state(rng)
        zb = fwd(model, Xb, Sb)[0]
    else:
        raise ValueError(f"🍆 АЙ, ОШИБКА! smooth_mode '{mode}' — есть 'train' и 'eval'")
    lam = cfg['smooth_lam'] if lam is None else lam
    d2 = (zb - za).pow(2)
    var = torch.cat([za, zb]).var().detach().clamp_min(SMOOTH_V0)
    if cfg.get('smooth_on', 'all') == 'ghost':
        w0 = Wa[:, 0] if Wa.dim() == 3 else Wa
        div = torch.maximum(median_abs(w0), fl)
        prev = torch.nan_to_num(data.r_t[(st_a - 1).clamp_min(0)], nan=0.0).abs()
        big = (torch.maximum(torch.maximum(prev, w0[:, 0].abs()), w0[:, 1].abs()) / div >= LINE_BIG).float()
        return lam * (big * d2).sum() / big.sum().clamp_min(1.0) / var
    if cfg.get('smooth_on', 'all') != 'all':
        raise ValueError(f"🍆 АЙ, ОШИБКА! smooth_on '{cfg.get('smooth_on')}' — есть 'all' и 'ghost'")
    return lam * d2.mean() / var


@torch.no_grad()
def line_info(data, st, L, fl):
    """v6.4, для разбора скачков линии — у каждого окна (начала st): sgn — знак ориентации формы (правило to_shapes); prev, a0, a1,
       last — |шаг close| бара перед окном, первого и второго бара окна и последнего бара, в медианах |шага| окна (делитель формы с
       полом fl — одно число или по окну). data.r — close (у 'multi' — close-канал)."""
    st_t = torch.as_tensor(np.asarray(st, dtype=np.int64), device=DEVICE)
    fl_t = torch.as_tensor(fl, dtype=torch.float32, device=DEVICE)
    if fl_t.dim() == 0:
        fl_t = fl_t.expand(len(st_t))
    out = {k: [] for k in ('sgn', 'prev', 'a0', 'a1', 'last')}
    for i in range(0, len(st_t), 262144):
        s_, f_ = st_t[i:i + 262144], fl_t[i:i + 262144]
        W = gather(data.r_t, s_, L)
        div = torch.maximum(median_abs(W), f_)
        cs = torch.cumsum(W, dim=1)
        out['sgn'].append(torch.where(cs[:, -1] - cs.mean(dim=1) < -ORIENT_EPS * div, -1.0, 1.0))
        out['prev'].append(torch.nan_to_num(data.r_t[(s_ - 1).clamp_min(0)], nan=0.0).abs() / div)
        out['a0'].append(W[:, 0].abs() / div)
        out['a1'].append(W[:, 1].abs() / div)
        out['last'].append(W[:, -1].abs() / div)
    return {k: torch.cat(v).cpu().numpy() for k, v in out.items()}


def line_stats(st, z, info=None, ab=None):
    """v6.4, гладкость линии модели на реальных окнах части: st — начала окон по возрастанию, z — их logit; соседи — окна на барах
       s и s + 1. n — окон, pairs — пар соседей, sd — разброс z, R = RMS(Δz) / sd (у скользящего среднего 64 независимых чисел
       √(2/64) ≈ 0.18), acf — автокорреляция z на лагах 1 / 4 / 16 / 64 бара, top1 / top5 — доля Σ Δz² в 1% / 5% крупнейших
       скачков, q99 — 99-й перцентиль |Δz| / sd. С info (line_info) — разбор пар: flip — у соседей разная ориентация формы, new —
       крупный новый бар, old — крупный бар уходит из свёрток / из окна / входит в историю (бары s + 1, s, s − 1), rest — остальное;
       у группы — доля пар, rel (средний Δz² к rest), energy (доля Σ Δz²), excess (энергия сверх уровня rest), top1 (доля группы
       в 1% крупнейших скачков). С ab (Платт a, b) — на 100 баров: side100 — смен стороны (знак a·z + b: оранжевый / синий),
       shade100 — смен оттенка (сторона × корзина M по LINE_SHADES), jump2_100 — скачков lift в 2 раза и больше."""
    st, z = np.asarray(st, dtype=np.int64), np.asarray(z, dtype=np.float64)
    out = {'n': int(len(z))}
    i0 = np.where(st[1:] == st[:-1] + 1)[0]
    if len(i0) < 1000:
        return out
    i1 = i0 + 1
    dz = z[i1] - z[i0]
    e = dz ** 2
    sd = float(z.std())
    out.update({'pairs': int(len(i0)), 'sd': sd, 'R': float(math.sqrt(e.mean()) / max(sd, 1e-12))})
    acf = {}
    for k in (1, 4, 16, 64):
        pos = np.searchsorted(st, st + k)
        ok = pos < len(st)
        ok[ok] = st[pos[ok]] == st[ok] + k
        acf[str(k)] = float(np.corrcoef(z[ok], z[pos[ok]])[0, 1]) if ok.sum() > 100 else float('nan')
    out['acf'] = acf
    srt = np.sort(e)[::-1]
    tot = float(srt.sum()) or 1e-12
    n1, n5 = max(1, len(srt) // 100), max(1, len(srt) // 20)
    out.update({'top1': float(srt[:n1].sum() / tot), 'top5': float(srt[:n5].sum() / tot),
                'q99': float(np.quantile(np.abs(dz), 0.99) / max(sd, 1e-12))})
    if info is not None:
        flip = info['sgn'][i1] != info['sgn'][i0]
        new = info['last'][i1] >= LINE_BIG
        old = np.maximum(np.maximum(info['prev'][i0], info['a0'][i0]), info['a1'][i0]) >= LINE_BIG
        grp = {'flip': flip, 'new': ~flip & new, 'old': ~flip & ~new & old}
        grp['rest'] = ~flip & ~new & ~old
        m_rest = float(e[grp['rest']].mean()) if grp['rest'].any() else float('nan')
        top = e >= srt[n1 - 1]
        out['groups'] = {}
        for k_, m_ in grp.items():
            if not m_.any():
                out['groups'][k_] = {'share': 0.0}
                continue
            out['groups'][k_] = {'share': float(m_.mean()), 'rel': float(e[m_].mean() / m_rest),
                                 'energy': float(e[m_].sum() / tot),
                                 'excess': float((e[m_].mean() - m_rest) * m_.sum() / tot), 'top1': float(m_[top].mean())}
    if ab is not None:
        lg = ab[0] * z + ab[1]
        side = np.where(lg >= 0, 1, -1)
        cls = side * (1 + np.searchsorted(np.log(LINE_SHADES), np.abs(lg)))
        out.update({'side100': 100 * float(np.mean(side[i1] != side[i0])), 'shade100': 100 * float(np.mean(cls[i1] != cls[i0])),
                    'jump2_100': 100 * float(np.mean(np.abs(lg[i1] - lg[i0]) >= math.log(2)))})
    return out


def line_echo(st, z, info, r, L=64, ages=LINE_ECHO_AGES, q=LINE_ECHO_Q):
    """v6.4, «эхо» крупного бара: средний Δz² пары (окно → следующее окно) в зависимости от возраста бара a — сколько баров назад
       он вошёл в окно последним баром (0 — вход; 63 — стал шагом 0 и ушёл из свёрток; 64 — ушёл из окна; 65 — вошёл в признаки
       истории перед окном; 80 / 128 — ушёл из средних диапазона за 16 / 64 бара; 264 — ушёл из 200 баров истории), в долях
       среднего Δz² всех пар; пары с переворотом ориентации не берутся. Крупный бар — |r| в верхних (1 − q) баров части. r — ряд
       close (numpy, позиции — как у st). Возвращает (профиль по возрасту 0 … ages, число пар у каждого возраста, порог |r|)."""
    st, z = np.asarray(st, dtype=np.int64), np.asarray(z, dtype=np.float64)
    e = np.full(len(z), np.nan)
    i1 = np.where(st[1:] == st[:-1] + 1)[0] + 1
    keep = info['sgn'][i1] == info['sgn'][i1 - 1]
    e[i1[keep]] = (z[i1[keep]] - z[i1[keep] - 1]) ** 2              # e[i] — скачок пары (i − 1 → i)
    base = np.nanmean(e)
    lo, hi = int(st.min()), int(st.max()) + L
    ra = np.abs(np.asarray(r[lo:hi], dtype=np.float64))
    thr = float(np.nanquantile(ra, q))
    big = lo + np.where(np.nan_to_num(ra) >= thr)[0]
    prof, cnt = np.full(ages + 1, np.nan), np.zeros(ages + 1, dtype=np.int64)
    for a in range(ages + 1):
        s_ = big + a - (L - 1)                                       # окно, у которого последний бар — big + a
        pos = np.searchsorted(st, s_)
        ok = pos < len(st)
        ok[ok] = st[pos[ok]] == s_[ok]
        v = e[pos[ok]]
        v = v[np.isfinite(v)]
        cnt[a] = len(v)
        prof[a] = v.mean() / base if len(v) else np.nan
    return prof, cnt, thr


ECHO_MARKS = {0: 'вход', 1: '+1', 63: 'ушёл из свёрток', 64: 'ушёл из окна', 65: 'вошёл в историю', 66: '+1',
              80: 'ушёл из r16', 128: 'ушёл из r64', 264: 'ушёл из 200 баров'}


def _line_weeks(st, z, wk):
    """v6.4: суммы по неделям для бутстрепа R — Σ Δz² и число пар (пара — к неделе второго окна), Σ z, Σ z², число окон.
       Возвращает (недели, массив (5, недели))."""
    st, z, wk = np.asarray(st, dtype=np.int64), np.asarray(z, dtype=np.float64), np.asarray(wk, dtype=np.int64)
    i0 = np.where(st[1:] == st[:-1] + 1)[0]
    i1 = i0 + 1
    weeks, inv = np.unique(wk, return_inverse=True)
    G = len(weeks)
    A = np.stack([np.bincount(inv[i1], weights=(z[i1] - z[i0]) ** 2, minlength=G),
                  np.bincount(inv[i1], minlength=G).astype(np.float64),
                  np.bincount(inv, weights=z, minlength=G), np.bincount(inv, weights=z * z, minlength=G),
                  np.bincount(inv, minlength=G).astype(np.float64)])
    return weeks, A


def _R_from(A):
    """v6.4: R по суммам _line_weeks, сложенным по неделям (A — (5, …))."""
    e2, npr, s1, s2, nw = A
    return np.sqrt(e2 / npr / np.maximum(s2 / nw - (s1 / nw) ** 2, 1e-12))


def _r_ratio(st, za, zb, wk, B=LINE_BOOT, seed=0):
    """v6.4: log(R_a / R_b) у двух моделей на одних окнах и его SE бутстрепом по неделям (неделя тянется целиком и одна у обеих)."""
    _, Aa = _line_weeks(st, za, wk)
    _, Ab = _line_weeks(st, zb, wk)
    lr = float(np.log(_R_from(Aa.sum(1)) / _R_from(Ab.sum(1))))
    G = Aa.shape[1]
    pick = np.random.default_rng(seed).integers(0, G, size=(B, G))
    return lr, float(np.std(np.log(_R_from(Aa[:, pick].sum(2)) / _R_from(Ab[:, pick].sum(2))), ddof=1))


def _print_line(line, title="〰️ ГЛАДКОСТЬ ЛИНИИ"):
    """v6.4: таблица line_stats по частям (TUNE / VALIDATION) одного прогона."""
    print(f"\n{title} (реальные окна подряд: z — logit, Δz — скачок между окнами на соседних барах; R = RMS(Δz) / sd(z), у "
          f"скользящего среднего 64 независимых чисел R = {math.sqrt(2 / 64):.3f}; «перевороты» — пары с разной ориентацией "
          f"формы; на 100 баров — с калибровкой Платта на TUNE)")
    print(f"   {'часть':<6} {'окон':>7} {'sd z':>6} {'R':>6} {'ρ1':>6} {'ρ16':>6} {'топ-1%':>7} {'топ-5%':>7} {'переворотов':>11} "
          f"{'×скачок':>8} {'энергия':>8} {'в топ-1%':>9} {'нов.круп. ×':>11} {'ух.круп. ×':>10} {'сторона':>8} {'оттенок':>8} "
          f"{'×2':>6}")
    for nm_, ls in line.items():
        if 'R' not in ls:
            continue
        g = ls.get('groups') or {}
        fl_, nw_, od_ = g.get('flip', {}), g.get('new', {}), g.get('old', {})
        print(f"   {nm_.upper():<6} {ls['n']:>7} {ls['sd']:>6.3f} {ls['R']:>6.3f} {ls['acf']['1']:>6.3f} {ls['acf']['16']:>6.3f} "
              f"{100 * ls['top1']:>6.1f}% {100 * ls['top5']:>6.1f}% {_f(100 * fl_.get('share', np.nan), '.1f', width=10)}% "
              f"{_f(fl_.get('rel'), '.2f', width=8)} {_f(100 * fl_.get('energy', np.nan), '.1f', width=7)}% "
              f"{_f(100 * fl_.get('top1', np.nan), '.1f', width=8)}% {_f(nw_.get('rel'), '.2f', width=11)} "
              f"{_f(od_.get('rel'), '.2f', width=10)} {_f(ls.get('side100'), '.1f', width=8)} {_f(ls.get('shade100'), '.1f', width=8)} "
              f"{_f(ls.get('jump2_100'), '.2f', width=6)}")


@torch.no_grad()
def letter_auc(model, data, w, cfg, store, spec, passes=2):
    """AUC «жёсткой буквы»: ближайший прототип -> log lift этой формы на FIT (счёт окон реала и
       суррогатов, как у словаря) -> AUC на TUNE / VAL. Это модель, сжатая до номера формы
       (log2 K бит); разница с полной моделью — цена такого сжатия (вопрос горла для токенов)."""
    K = model.K
    g = torch.Generator(device=DEVICE)
    g.manual_seed(cfg['seed'] + 7)
    pm = PairMaker(data, cfg['L'], cfg, float('inf'), g)
    n_p, n_n = np.zeros(K), np.zeros(K)
    idx = fit_windows(w, cfg)
    for p in range(passes):
        for i in range(0, len(idx), 65536):
            j = idx[i:i + 65536]
            Wp, Wn, fl = pm.make(torch.from_numpy(w['st'][j]).to(DEVICE),
                                 torch.from_numpy(w['sid'][j]).to(DEVICE))
            if p == 0:
                n_p += np.bincount(model.dist_matrix(to_shapes(Wp, fl)).argmin(1).cpu().numpy(), minlength=K)
            n_n += np.bincount(model.dist_matrix(to_shapes(Wn, fl)).argmin(1).cpu().numpy(), minlength=K)
    n_n /= passes
    table = np.log((n_p + 0.5) / (n_n + 0.5))
    out = {}
    for nm in ('tune', 'val'):
        ev = store.get(nm, spec)
        lp, _ = assign(model, ev['Xp'])
        ln, _ = assign(model, ev['Xn'])
        a_, se_ = auc_se(table[lp], table[ln], ev['wp'], ev['wn'])
        out[nm] = {'auc': a_, 'se': se_}
    return out


def _lift_at(lg_p, lg_n, thr=1.25):
    """Фактический lift отметок «оценка lift >= thr» и «<= 1/thr» и доля отмеченных реальных окон."""
    t = math.log(thr)
    up_p, up_n = float(np.mean(lg_p >= t)), float(np.mean(lg_n >= t))
    dn_p, dn_n = float(np.mean(lg_p <= -t)), float(np.mean(lg_n <= -t))
    return {'lift_up': up_p / up_n if up_n > 0 else np.nan, 'lift_dn': dn_p / dn_n if dn_n > 0 else np.nan,
            'cov': up_p + dn_p}


def year_profile(model, store, spec, ab=None):
    """AUC и разница средних logit (реал − суррогат) по календарным годам: FIT-годы (в выборке
       обучения — оценка оптимистична, но одинаково для всех лет), TUNE и VALIDATION (вне).
       Отвечает, ровный ли эффект во времени или слабеет (калибровка Платта a ≈ 0.5 в v1).
       v4.4: у TUNE / VAL и полугодий — фактический lift отметок силы >= 1.25 (калибровка ab с TUNE):
       насколько обещания индикатора держатся во времени."""
    rows = []
    for y in store.fit_years():
        ev = store.get(f'fitY{y}', spec)
        if ev is None or len(ev['Xp']) < 2000:
            continue
        r, _, _ = eval_set(model, ev)
        rows.append({'part': str(y), 'n': r['n'], 'auc': r['auc'], 'se': r['auc_se'],
                     'gap': r['lg_mean_p'] - r['lg_mean_n']})
    halves = []
    for nm in ('tune', 'val'):
        ev = store.get(nm, spec)
        r, sp, sn = eval_set(model, ev)
        rows.append({'part': nm.upper(), 'n': r['n'], 'auc': r['auc'], 'se': r['auc_se'],
                     'gap': r['lg_mean_p'] - r['lg_mean_n']})
        if ab is not None:
            rows[-1].update(_lift_at(ab[0] * sp + ab[1], ab[0] * sn + ab[1]))
        # v4.3: по полугодиям (вне выборки) — слабеет ли эффект после FIT
        if ev['paired']:
            ts = pd.to_datetime(np.asarray(ev['wp']) * WEEK_NS)
            lab = np.array([f"{'T' if nm == 'tune' else 'V'}{y_ % 100:02d}H{1 if m_ <= 6 else 2}"
                            for y_, m_ in zip(ts.year, ts.month)])
            for hl in sorted(set(lab), key=lambda s_: (s_[1:3], s_[-1])):
                msk = lab == hl
                if msk.sum() < 5000:
                    continue
                a_, se_ = auc_se(sp[msk], sn[msk], ev['wp'][msk], ev['wn'][msk])
                halves.append({'part': hl, 'n': int(msk.sum()), 'auc': a_, 'se': se_,
                               'gap': float(sp[msk].mean() - sn[msk].mean())})
                if ab is not None:
                    halves[-1].update(_lift_at(ab[0] * sp[msk] + ab[1], ab[0] * sn[msk] + ab[1]))
    return rows + halves


def _roughness(C):
    """Шероховатость форм: средний |вторая разность| формы в единицах её собственного разброса.
       Гладкая кривая — около 0.01-0.05, «зубчатая» — выше."""
    C = np.asarray(C, dtype=np.float64)
    C = C - C.mean(1, keepdims=True)
    C = C / np.maximum(np.sqrt((C ** 2).mean(1, keepdims=True)), 1e-12)
    return float(np.abs(np.diff(C, 2, axis=1)).mean())


@torch.no_grad()
def smooth_auc(model, store, spec, width=5):
    """AUC той же модели, но с прототипами, сглаженными треугольным окном width (края — повтором
       крайней точки). Голова не переучивается. Если AUC почти не падает — зубцы форм шум
       (дрейф без привязки к данным), если падает — в зубцах информация."""
    k = torch.tensor([min(i + 1, width - i) for i in range(width)], dtype=torch.float32,
                     device=model.protos.device)
    k = (k / k.sum()).view(1, 1, -1)
    C0 = model.protos.detach().clone()
    Cs = F.conv1d(F.pad(C0[:, None, :], (width // 2, width // 2), mode='replicate'), k).squeeze(1)
    model.protos.data.copy_(Cs)
    out = {}
    try:
        for nm in ('tune', 'val'):
            r, _, _ = eval_set(model, store.get(nm, spec))
            out[nm] = r['auc']
    finally:
        model.protos.data.copy_(C0)
    out['rough'] = _roughness(C0.cpu().numpy())
    out['rough_s'] = _roughness(Cs.cpu().numpy())
    return out


@torch.no_grad()
def p_sparsity(model, X, bs=65536):
    """Сколько форм реально участвует в P окна: n_eff = exp(энтропия P) (1 — одна форма, K — все
       поровну) и доля массы P на самой близкой форме. Меряет «разреженность токена» без оглядки
       на масштаб расстояний, в отличие от T."""
    ne, top = [], []
    for i in range(0, len(X), bs):
        P = model.soft_p(model.dist_matrix(X[i:i + bs]))
        H = -(P * torch.log(P.clamp_min(1e-12))).sum(1)
        ne.append(torch.exp(H).cpu())
        top.append(P.max(1).values.cpu())
    ne, top = torch.cat(ne).numpy(), torch.cat(top).numpy()
    return {'neff_med': float(np.median(ne)), 'neff_p90': float(np.percentile(ne, 90)),
            'top_med': float(np.median(top))}


def proto_report(model, ev, sp, K, dict_C, dead_frac, top=None, norm=False):
    """Таблица форм на наборе ev: доля окон реала и суррогата, lift, средний logit
       реальных окон формы, амплитуда, близость к ближайшей букве словаря SuMo."""
    lab_p, _ = assign(model, ev['Xp'])
    lab_n, _ = assign(model, ev['Xn'])
    cp, cn = np.bincount(lab_p, minlength=K), np.bincount(lab_n, minlength=K)
    up, un = cp / cp.sum(), cn / cn.sum()
    lift = (up + 0.5 / cp.sum()) / (un + 0.5 / cn.sum())
    mlg = np.bincount(lab_p, weights=sp, minlength=K) / np.maximum(cp, 1)
    C = model.protos.detach().cpu().numpy()
    amp = np.sqrt(((C - C.mean(1, keepdims=True)) ** 2).mean(1))
    near = dict_prox(C, dict_C, norm) if dict_C is not None else np.full(K, np.nan)
    us = usage_stats(lab_p, K, dead_frac)
    order = np.argsort(-up)
    show = order if (top is None or K <= top) else np.concatenate([order[:top - 8], order[-8:]])
    print(f"   {'форма':>6} {'реал':>7} {'сурр':>7} {'lift':>6} {'logit':>7} {'ампл':>6} "
          f"{'~слов':>6}  shape")
    for j, k in enumerate(show):
        if top is not None and K > top and j == top - 8:
            print(f"   {'…':>6}")
        print(f"   {('#' + str(k)):>6} {100 * up[k]:>6.2f}% {100 * un[k]:>6.2f}% {lift[k]:>6.2f} "
              f"{mlg[k]:>+7.3f} {amp[k]:>6.2f} {_f(near[k], '.2f', width=6)}  {spark(C[k])}")
    return {'usage': up, 'usage_n': un, 'lift': lift, 'mean_logit': mlg, 'amp': amp,
            'near_dict': near, 'effK': us['effK'], 'dead': us['dead'], 'maxU': us['maxU'],
            'lab_p': lab_p}


def check_absv(cfg, data):
    """v5.5: варианту с абсолютной волой (столбец 36) нужен close в файлах данных (smc_series: close_tr / close_va)."""
    cols = set(SIDE_COLS[cfg['side']] if cfg.get('side') else ()) | set(CHAN_COLS[cfg['cnn_chan']] if cfg.get('cnn_chan') else ())
    if TOK_COLS[-1] in cols and not data.absv_ok:
        raise ValueError(f"🍆 АЙ, ОШИБКА! {cfg['name']}: признаку абсолютной волы нужен close в smc_series (close_tr / "
                         f"close_va) — в файлах данных его нет, перезапусти TrendyCoins_SMC_Data")
    nt = sorted(c for c in cols if c >= NT_COL0)          # v6.0: признаки истории в барах
    if nt and not data.nt_ok:
        raise ValueError(f"🍆 АЙ, ОШИБКА! {cfg['name']}: признакам истории нужен smc_bars у всех ассетов — сначала "
                         f"TrendyCoins_SMC_Bars (в той же папке, что smc_series)")
    lost = [c for c in nt if c - NT_COL0 not in data.nt_rows]
    if lost:
        raise ValueError(f"🍆 АЙ, ОШИБКА! {cfg['name']}: столбцы истории {lost} не загружены — добавь их в NT_KEEP")


def run_one(name, over, seed_key, datas, stores, job):
    """Один прогон на BTC. v6.7: весь прогон — в ориентации окна своей конфигурации (cfg 'orient'; наборы проверки — свои)."""
    with orientation(make_cfg(name, over, seed_key).get('orient', True)):
        return _run_one(name, over, seed_key, datas, stores, job)


def _run_one(name, over, seed_key, datas, stores, job):
    t_run = time.time()
    cfg = make_cfg(name, over, seed_key)
    if cfg.get('mir_aug') and not (cfg['arch'] == 'cnn' and not ORIENT):
        raise ValueError("🍆 АЙ, ОШИБКА! mir_aug (контроль C0_mir) — только у CNN без ориентации (orient False)")
    L, K = cfg['L'], cfg['K']
    tag = cfg['tag']
    out_dir = RUN_DIR + tag + '/'
    os.makedirs(out_dir, exist_ok=True)
    data = get_data(datas, cfg.get('price', 'close'))
    check_absv(cfg, data)
    torch.manual_seed(cfg['seed'])
    rng = np.random.default_rng(cfg['seed'])
    gen = torch.Generator(device=DEVICE)
    gen.manual_seed(cfg['seed'])
    print(f"\n\n{'#' * 78}\n# SMC v{SMC_VER} | прогон {tag} | задание {job} | {DEVICE}\n"
          f"# {cfg_line(cfg)}\n{'#' * 78}")
    if data.price != 'close':
        naive = cfg.get('price_null', 'mirror') == 'naive'
        print(f"💱 цена бара {PRICE_NAMES[data.price]}: суррогат — "
              + ("НАИВНЫЙ sflip приращений (нечестен: засчитывает арифметику усреднения — только для демонстрации)"
                 if naive else "зеркало бара (бары переворачиваются целиком, блоками; те же бары, что у close)"))
    if cfg['arch'] == 'frozen' or cfg['dict'] is not None:
        D = cfg['dict']
        fl = data.floor(0, L)
        ok = D['floor'] is not None and abs(D['floor'] - fl) / fl < 1e-6
        print(f"📚 словарь '{D['tag']}': K={len(D['C'])}, групп {int(D['group'].max()) + 1}, пол "
              f"{_f(D['floor'], '.6f')} против {fl:.6f} у данных {'✅' if ok else '⚠️ РАЗНЫЕ'}")

    store = get_store(datas, stores, data.price, L)
    w = store.w
    spec = primary_spec(cfg)
    ev_tune = store.get('tune', spec)
    ev_fitp = store.get('fitprobe', spec)
    H = int(cfg.get('fit_holdout') or 0)
    HB = int(cfg.get('hold_block') or 1)
    ev_out = store.get(hold_key('fitout', cfg), spec) if H else None   # отложенные блоки FIT: в обучение не идут

    # ---- обрезка хвоста размаха (от знаков не зависит) по FIT
    fit = fit_windows(w, cfg)
    fl_fit = w['floor_t'][torch.from_numpy(w['sid'][fit]).to(DEVICE)]
    tv = torch.cat([tv_ratio(gather(data.r_t, torch.from_numpy(w['st'][fit[i:i + 262144]]).to(DEVICE), L),
                             fl_fit[i:i + 262144]) for i in range(0, len(fit), 262144)])
    thr = float(torch.quantile(tv[torch.randperm(len(tv), device=DEVICE)[:1000000]],
                               1 - cfg['trim_q'] / 100.0)) if cfg['trim_q'] else float('inf')
    keep = (tv <= thr).cpu().numpy()
    fit_st = torch.from_numpy(w['st'][fit][keep]).to(DEVICE)
    fit_sid = torch.from_numpy(w['sid'][fit][keep]).to(DEVICE)
    del tv
    # v4.3: вес свежей истории — окно берётся в обучение с вероятностью ~ 0.5^(возраст / полураспад)
    fit_wt, wt_note = None, ""
    if cfg.get('fit_halflife'):
        te = w['t_end'][fit][keep]
        age = (te.max() - te) / (365.25 * DAY_NS)
        wt = 0.5 ** (age / float(cfg['fit_halflife']))
        fit_wt = torch.from_numpy(wt).float().to(DEVICE)
        ess = wt.sum() ** 2 / (wt ** 2).sum()
        wt_note = (f" | вес свежей истории: полураспад {cfg['fit_halflife']:g} г., вес самого старого окна "
                   f"{wt.min():.2f}, эффективно окон {ess / len(wt) * 100:.0f}%")
    hold_note = ""
    if H:
        n_out = int(holdout_masks(w['t_end'][w['fit']], H, HB)[0].sum())
        what = 'неделя' if HB == 1 else f'{HB} нед.'
        hold_note = (f" (без каждого {H}-го блока, блок — {what}, и суток после него; окон в отложенных блоках "
                     f"{n_out}, в проверке {len(ev_out['Xp'])})")
    print(f"📦 окон: FIT {len(fit)}{' (с ' + str(cfg['fit_from'])[:10] + ')' if cfg.get('fit_from') else ''}"
          f"{hold_note} "
          f"(в обучение {int(keep.sum())}, обрезано {100 * (1 - keep.mean()):.2f}% "
          f"по размаху > {thr:.1f}) | TUNE {len(w['tune'])} | VAL {len(w['val'])} | "
          f"нулевая обучения '{cfg['null']}'{' | КОНТРОЛЬ ' + cfg['control'] if cfg['control'] else ''}"
          + wt_note)

    # ---- модель
    pick = torch.from_numpy(rng.choice(len(fit_st), size=min(150000, len(fit_st)), replace=False)).to(DEVICE)
    W_s, fl_s = data.gw(fit_st[pick], L), w['floor_t'][fit_sid[pick]]
    Xs = to_shapes(W_s, fl_s)
    Ss = side_feats(data, fit_st[pick], L, W_s, fl_s)
    del W_s
    t0 = time.time()
    model, st = build_model(cfg, Xs, rng, Ss)
    if cfg['arch'] == 'frozen':
        n_p, n_n = fit_frozen(model, data, w, cfg, gen)
        lift_fit = (n_p + 0.5) / (n_n + 0.5)
        what = 'клеток (кластеров)'
        print(f"📚 lift {what} на FIT: {len(lift_fit)} шт., >= 1.25 у {np.sum(lift_fit >= 1.25)}, <= 0.80 у "
              f"{np.sum(lift_fit <= 0.8)} | от {lift_fit.min():.2f} до {lift_fit.max():.2f} | "
              f"{time.time() - t0:.0f} c")
    n_par = sum(p.numel() for p in model.parameters() if p.requires_grad)
    print(f"🧠 {type(model).__name__}: обучаемых параметров {n_par} | умножений на бар (Pine) "
          f"~{model.pine_cost()}{' (потоком, бар за баром)' if getattr(model, 'streamable', False) else ''} | "
          f"старт {time.time() - t0:.1f} c"
          + (f" | D0 {st['D0']:.3f} зазор {st['gap0']:.4f} T0 {float(model.log_T.detach().exp()):.4f}"
             if cfg['arch'] == 'smc' else "")
          + (f" | форм {model.K} по {model.m} баров, мест в окне {model.L - model.m + 1}, T0 "
             f"{float(model.log_T.detach().exp()):.4f}" if cfg['arch'] == 'shapelet' else "")
          + (f" | два банка: R {model.K // 2} форм (к реальным окнам), S {model.K - model.K // 2} (к суррогатам)"
             + ("; BCE реального окна двигает только R, суррогата — только S" if cfg['bank_route'] else "")
             if cfg['arch'] == 'smc' and cfg['bank2'] else ""))

    hist, snaps, best = [], {}, {'bce': float('inf'), 'auc': -float('inf'), 'ep': -1, 'state': None}
    epochs_run, stop_note = 0, ''
    trainable = cfg['arch'] != 'frozen'
    if trainable:
        groups = [{'params': [p for n, p in model.named_parameters()
                              if p.requires_grad and n != 'protos' and n != 'log_T'],
                   'lr': cfg['lr'], 'weight_decay': cfg['wd']}]
        if cfg['arch'] in ('smc', 'shapelet'):
            if model.log_T.requires_grad:
                groups.append({'params': [model.log_T], 'lr': cfg['lr'], 'weight_decay': 0.0})
            groups.append({'params': [model.protos], 'lr': cfg['lr_protos'], 'weight_decay': 0.0})
        opt = torch.optim.AdamW(groups)
        for g_ in opt.param_groups:
            g_['lr0'] = g_['lr']                  # стартовый lr группы: от него считается нижняя граница
        # v4.2: скользящее среднее весов (EMA): проверка, лучшая эпоха и итог — по усреднённой копии
        ema, n_upd = None, 0
        if cfg['ema']:
            ema = copy.deepcopy(model)
            for p_ in ema.parameters():
                p_.requires_grad_(False)
        judge = ema if ema is not None else model
        half = cfg['batch'] // 2
        steps = cfg['steps'] or max(1, len(fit_st) // half)
        protos_train = cfg['arch'] == 'smc' and (not cfg['freeze_protos'] or cfg['warmup_epochs'] > 0)
        min_ep = cfg['min_epochs']
        if min_ep is None:
            min_ep = cfg['warmup_epochs'] + (cfg['tau_epochs'] if (protos_train and cfg['lam_clu'] > 0
                                             and cfg['clu_mode'] == 'anneal') else 3)
        bad = 0
        pm = PairMaker(data, L, cfg, thr, gen)
        crit = (f"AUC на TUNE (рост >= {cfg['stop_delta']:g})" if cfg['stop_on'] == 'auc'
                else "BCE на TUNE")
        if cfg['stop_on'] == 'fixed':
            crit = "без ранней остановки: итог — последняя эпоха"
        if cfg.get('fit_plus_tune'):
            crit += "; TUNE в обучении (его AUC — в выборке), сравнение — по VALIDATION"
        if getattr(model, 'side_cols', None):
            crit += "; боковые входы: " + ", ".join(SIDE_NAMES[i] for i in model.side_cols)
        if getattr(model, 'chan_cols', None):  # v5.5
            crit += "; постоянные каналы свёрток: " + ", ".join(SIDE_NAMES[i] for i in model.chan_cols)
        if cfg['ema']:
            crit += f"; веса — скользящее среднее (EMA {cfg['ema']:g}, ~{1 / (1 - cfg['ema']) / steps:.1f} эпохи)"
        if cfg['aug_mag']:
            crit += f"; шум модулей шагов ×exp({cfg['aug_mag']:g}·N(0,1)), общий у пары"
        if cfg['lr_plateau']:
            crit += (f"; lr ×{cfg['lr_factor']:g} после каждых {cfg['lr_plateau']} эпох без роста "
                     f"(не ниже 1/{round(1 / cfg['lr_min_frac'])} стартового)")
        if getattr(model, 'sym', False):       # v6.4
            crit += "; зеркально-симметричная сеть: logit = (g(окно) + g(зеркало окна)) / 2"
        if getattr(model, 'anti', None):       # v6.7
            crit += (f"; + антисимметричная голова ({'как основная' if model.anti == 'mlp' else 'линейная'}): "
                     f"logit = s + a, a(зеркало) = −a, старт a ≡ 0")
        if not ORIENT:                         # v6.7
            crit += "; вход БЕЗ ориентации — сеть видит абсолютное направление (вверх / вниз)"
        mir_p = float(cfg.get('mir_aug') or 0.0)
        if mir_p > 0:                          # v6.7: контроль C0_mir
            crit += (f"; КОНТРОЛЬ C0_mir: у {100 * mir_p:.0f}% пар шага реал и его суррогат заменены зеркальными — рынок "
                     f"симметризован, асимметрии в данных нет")
        lam_s = float(cfg.get('smooth_lam') or 0.0)
        if lam_s > 0:                          # v6.4: пары соседних окон обучения для штрафа скачков линии
            nxt_ok = torch.from_numpy(next_in_set(fit_st.cpu().numpy())).to(DEVICE)
            n_pen = max(8, int(round(cfg['smooth_frac'] * half)))
            crit += (f"; штраф скачков соседних окон λ = {lam_s:g} · mean(Δz²) / max(var(z), {SMOOTH_V0:g}) на {n_pen} парах шага, "
                     f"разгон {cfg.get('smooth_warm')} эп., {_smooth_mode_txt(cfg)}"
                     + (" — только «призрачные» пары (крупный бар уходит из свёрток / окна / входит в историю)"
                        if cfg.get('smooth_on') == 'ghost' else "")
                     + f" (соседнее окно в обучении есть у {100 * float(nxt_ok.float().mean()):.1f}% окон)")
        if cfg['stop_on'] == 'fixed':
            print(f"🏋️ эпоха = {steps} шагов по {cfg['batch']} окон | ровно {cfg['epochs']} эпох, {crit}")
        else:
            print(f"🏋️ эпоха = {steps} шагов по {cfg['batch']} окон | не меньше {min_ep} эпох, не больше "
                  f"{cfg['epochs']}, терпение {cfg['patience']} по {crit}")
        protos_ok = cfg['arch'] == 'smc'
        if protos_ok:
            snaps[-1] = model.protos.detach().cpu().numpy().copy()     # старт
        for ep in range(cfg['epochs']):
            t_ep = time.time()
            tau = tau_at(ep, cfg, st['gap0'])
            w_bce = 0.0 if ep < cfg['warmup_epochs'] else 1.0
            if protos_ok and cfg['freeze_protos'] and ep == cfg['warmup_epochs']:
                model.protos.requires_grad_(False)
            if fit_wt is not None:             # v4.3: окна с весом свежести, с повторами
                perm = torch.multinomial(fit_wt, len(fit_st), replacement=True, generator=gen)
            else:
                perm = torch.randperm(len(fit_st), generator=gen, device=DEVICE)
            acc, grads = {}, {}
            prev = model.protos.detach().clone() if protos_ok else None
            for s in range(steps):
                j = perm[(s * half) % len(perm):(s * half) % len(perm) + half]
                Wp, Wn, fl = pm.make(fit_st[j], fit_sid[j])
                if cfg['aug_mag'] > 0:
                    # один и тот же множитель модулей у реального окна и его суррогата: пара и знаки
                    # не меняются, |r| у пары по-прежнему общий, а точный путь реала каждый раз новый
                    f_ = torch.exp(cfg['aug_mag'] * torch.randn(Wp.shape, generator=gen, device=DEVICE))
                    Wp, Wn = Wp * f_, Wn * f_
                X = torch.cat([to_shapes(Wp, fl), to_shapes(Wn, fl)])
                y = torch.cat([torch.ones(len(Wp), device=DEVICE), torch.zeros(len(Wn), device=DEVICE)])
                S = None
                if uses_side(model):           # v4.4-4.5: боковые входы — каждого окна по нему самому
                    S = torch.cat([side_feats(data, fit_st[j], L, Wp, fl), side_feats(data, fit_st[j], L, Wn, fl)])
                if mir_p > 0:                  # v6.7, C0_mir: у случайной доли пар — зеркальный рынок (реал и суррогат вместе)
                    m_ = torch.rand(len(Wp), generator=gen, device=DEVICE) < mir_p
                    rows = torch.where(torch.cat([m_, m_]))[0]
                    if len(rows):
                        xm_, sm_ = mirror_inputs(X[rows], None if S is None else S[rows], model.n_level, model.lvl_signed)
                        X[rows] = xm_
                        if S is not None:
                            S[rows] = sm_
                if cfg['arch'] == 'smc' and cfg['bank_route']:
                    # v4.3: значения те же, но градиент BCE реального окна идёт только в банк R,
                    # суррогатного — только в банк S (другой банк для этой строки отцеплен)
                    D = model.dist_matrix(X)
                    in_r = torch.arange(model.K, device=DEVICE)[None, :] < model.K // 2
                    own = torch.where((y > 0.5)[:, None], in_r, ~in_r)
                    e_, P, _ = model.features(X, torch.where(own, D, D.detach()))
                    logit = model.head(e_).squeeze(1)
                else:
                    logit, D, P, _ = fwd(model, X, S)
                terms = loss_terms(model, logit, y, D, cfg, st, tau, w_bce)
                if lam_s > 0:                  # v6.4: штраф скачков между соседними реальными окнами (разгон smooth_warm эпох)
                    jj = j[nxt_ok[j]][:n_pen]
                    if len(jj) >= 8:
                        terms['smooth'] = smooth_penalty(model, data, L, fit_st[jj], fit_sid[jj], w['floor_t'], cfg,
                                                         lam_s * min(1.0, (ep + 1) / max(1, int(cfg.get('smooth_warm') or 1))))
                total = sum(terms.values())
                if s == 0 and protos_ok and model.protos.requires_grad:
                    for k_, v_ in terms.items():
                        if v_.requires_grad:
                            g_, = torch.autograd.grad(v_, model.protos, retain_graph=True,
                                                      allow_unused=True)
                            grads[k_] = 0.0 if g_ is None else float(g_.norm())
                opt.zero_grad(set_to_none=True)
                total.backward()
                opt.step()
                if ema is not None:
                    # разгон: пока шагов мало, среднее по ~последней десятой части пути, а не по старту
                    n_upd += 1
                    dk = min(cfg['ema'], (1.0 + n_upd) / (10.0 + n_upd))
                    with torch.no_grad():
                        for pe, pw in zip(ema.parameters(), model.parameters()):
                            pe.mul_(dk).add_(pw.detach(), alpha=1.0 - dk)
                        for be, bw in zip(ema.buffers(), model.buffers()):
                            be.copy_(bw)
                for k_, v_ in terms.items():
                    acc[k_] = acc.get(k_, 0.0) + v_.detach()
            epochs_run = ep + 1
            loss = {k_: float(v_) / steps for k_, v_ in acc.items()}
            n_re = 0
            if (protos_ok and cfg['reinit_dead'] and model.protos.requires_grad
                    and ep < cfg['reinit_until'] * cfg['epochs']):
                n_re = reinit_dead(model, opt, ev_fitp['Xp'], cfg, gen)
            r_t, sp_tn, _ = eval_set(judge, ev_tune)
            r_f, _, _ = eval_set(judge, ev_fitp)
            row = {'ep': ep, 'sec': time.time() - t_ep, 'loss': loss, 'tune': r_t, 'fit': r_f,
                   'reinit': n_re, 'grads': grads, 'tau': tau}
            line = (f"эп {ep:>3} | {row['sec']:5.1f}c | loss {sum(loss.values()):.4f} = "
                    + " + ".join(f"{k_} {v_:.4f}" for k_, v_ in loss.items())
                    + f" | FIT bce {r_f['bce']:.5f} auc {r_f['auc']:.4f}")
            if ev_out is not None:
                r_o, _, _ = eval_set(judge, ev_out)
                row['out'] = r_o
                line += f" | FIT-отлож auc {r_o['auc']:.4f}"
            line += (f" | TUNE bce {r_t['bce']:.5f} auc {r_t['auc']:.4f}±{r_t['auc_se']:.4f}"
                     + (f" win {r_t['win']:.4f}" if 'win' in r_t else ""))
            if protos_ok:
                lab, _ = assign(model, ev_tune['Xp'])
                us = usage_stats(lab, K, cfg['dead_frac'])
                C = model.protos.detach()
                drift = float((C - prev).pow(2).mean().sqrt() / C.pow(2).mean().sqrt().clamp_min(1e-12))
                row.update({'T': float(model.log_T.detach().exp()), 'effK': us['effK'], 'dead': us['dead'],
                            'maxU': us['maxU'], 'drift': drift})
                gtot = sum(grads.values()) or 1.0
                tau_s = f" τ {tau:.4f}" if (cfg['lam_clu'] > 0 and cfg['clu_mode'] != 'hard') else ""
                line += (f" | T {row['T']:.4f}{tau_s} | effK {us['effK']:.1f}/{K} dead {us['dead']}"
                         f" maxU {100 * us['maxU']:.1f}% | Δформ {drift:.4f}"
                         + (f" | рост-заново {n_re}" if n_re else "")
                         + (" | градиент формам: " + " ".join(f"{k_} {100 * v_ / gtot:.0f}%"
                                                             for k_, v_ in grads.items()) if grads else ""))
                if ep in cfg['fig_epochs']:
                    snaps[ep] = model.protos.detach().cpu().numpy().copy()
            if cfg['stop_on'] == 'fixed':      # v4.4: фиксированное число эпох, итог — последняя
                improved = True
            elif cfg['stop_on'] == 'auc':
                improved = r_t['auc'] > best['auc'] + cfg['stop_delta']
            else:
                improved = r_t['bce'] < best['bce'] - 1e-6
            if improved:
                best = {'bce': r_t['bce'], 'auc': r_t['auc'], 'ep': ep,
                        'state': {k_: v_.detach().cpu().clone() for k_, v_ in judge.state_dict().items()}}
                bad = 0
            else:
                bad += 1
            lr_note = ""
            if cfg['lr_plateau'] and not improved and bad % cfg['lr_plateau'] == 0:
                for g_ in opt.param_groups:
                    g_['lr'] = max(g_['lr'] * cfg['lr_factor'], g_['lr0'] * cfg['lr_min_frac'])
                lr_note = f" | lr -> {opt.param_groups[0]['lr']:.1e}"
            row['lr'] = opt.param_groups[0]['lr']
            if lam_s > 0 and 'bce' in loss and r_f['bce'] - loss['bce'] > 0.15:   # v6.5: признак развода режимов (smooth_penalty)
                lr_note += f" | ❗ BCE на FIT без dropout выше BCE обучения на {r_f['bce'] - loss['bce']:.2f}"
            print(line + lr_note + (" ★" if improved else ""))
            hist.append(row)
            if protos_ok and cfg['log_every'] and (ep + 1) % cfg['log_every'] == 0:
                print(f"   🧩 формы после эпохи {ep} (TUNE, реал против '{spec}'):")
                proto_report(model, ev_tune, sp_tn, K, None, cfg['dead_frac'], top=24)
            if ep + 1 >= min_ep and bad >= cfg['patience']:
                stop_note = f"ранняя остановка на эпохе {ep} (лучшая {best['ep']})"
                break
        if best['state'] is not None:
            model.load_state_dict(best['state'])
        how = {'auc': 'по AUC', 'bce': 'по BCE', 'fixed': 'последняя, без остановки'}[cfg['stop_on']]
        print(f"⏹️ {stop_note or 'все эпохи пройдены'} | итоговая эпоха {best['ep']} ({how}): TUNE AUC "
              f"{best['auc']:.4f}, BCE {best['bce']:.5f} | {(time.time() - t_run) / 60:.1f} мин")
    return finish_run(cfg, model, data, store, spec, hist, snaps, best, t_run, out_dir, st, epochs_run)


def finish_run(cfg, model, data, store, spec, hist, snaps, best, t_run, out_dir, st, epochs_run):
    L, K, tag = cfg['L'], cfg['K'], cfg['tag']
    ev_t, ev_v = store.get('tune', spec), store.get('val', spec)
    r_t, sp_t, sn_t = eval_set(model, ev_t)
    r_v, sp_v, sn_v = eval_set(model, ev_v)
    a, b = platt_fit(sp_t, sn_t)
    cal_rows, ece = calib_table(sp_v, sn_v, a, b)
    _, ece_raw = calib_table(sp_v, sn_v, 1.0, 0.0)
    r_v['bce_cal'] = bce_of(a * sp_v + b, a * sn_v + b)
    print(f"\n{'=' * 78}\n🎯 ИТОГ {tag}: реал против '{spec}' (лучшая эпоха {best['ep']})\n{'=' * 78}")
    print(f"   {'':<11} {'окон':>8} {'BCE':>9} {'AUC':>8} {'±SE':>7} {'пары: реал выше':>16} "
          f"{'logit реал':>11} {'logit сурр':>11} {'sd logit':>9}")
    for nm, r in (('TUNE', r_t), ('VALIDATION', r_v)):
        print(f"   {nm:<11} {r['n']:>8} {r['bce']:>9.5f} {r['auc']:>8.4f} {r['auc_se']:>7.4f} "
              f"{_f(r.get('win'), '.4f', width=10)}±{_f(r.get('win_se'), '.4f', width=5)} "
              f"{r['lg_mean_p']:>+11.4f} {r['lg_mean_n']:>+11.4f} {r['lg_sd']:>9.4f}")
    print(f"   BCE шума = {math.log(2):.5f}; SE — по неделям (окна перекрыты, соседние недели "
          f"связаны). Калибровка на TUNE: logit' = {a:.3f}·logit {b:+.3f}; VALIDATION BCE "
          f"{r_v['bce']:.5f} -> {r_v['bce_cal']:.5f}, ECE {ece_raw:.4f} -> {ece:.4f}")

    # ---- v6.7: сеть видит направление — зеркальная проверка (у контроля «суррогат против суррогата» — нет)
    dir_info, dir_arrs = None, {}
    if not ORIENT and cfg['control'] is None:
        dir_info, dir_arrs = dir_check(model, {'tune': (ev_t, sp_t, sn_t), 'val': (ev_v, sp_v, sn_v)})
        print_dir(dir_info)

    # ---- v6.4: гладкость линии (реальные окна подряд), разбор скачков, смены покраски на 100 баров
    line = {}
    for nm_, ev_, sp_ in (('tune', ev_t, sp_t), ('val', ev_v, sp_v)):
        if ev_.get('st') is not None and sp_ is not None:
            line[nm_] = line_stats(ev_['st'], sp_, line_info(data, ev_['st'], L, store.positives(nm_)['fl']), (a, b))
    if any('R' in v for v in line.values()):
        _print_line(line)

    # ---- проверка против других нулевых
    cross = {}
    if cfg['control'] is None:
        mirror = data.price != 'close'
        print("\n🔀 ДРУГИЕ НУЛЕВЫЕ (VALIDATION; модель та же, меняется только суррогат)"
              + (f"; цена бара {PRICE_NAMES[data.price]}: sflip<b> — зеркало баров блоками по b" if mirror else ""))
        print(f"   {'нулевая':<20} {'AUC':>8} {'±SE':>7} {'пары':>8}")
        b_ = parse_null(spec)[1] if parse_null(spec)[0] in ('sflip', 'nsflip') else 4
        extra = [f'nsflip{b_}'] if (mirror and spec != f'nsflip{b_}') else []
        for sp_ in EVAL_NULLS + extra + [f"shuf{b_}"]:
            ev = store.get('val', sp_)
            if ev is None:
                print(f"   {sp_:<20} нет в данных")
                continue
            rr, _, _ = eval_set(model, ev)
            if rr is None:
                print(f"   {sp_:<20} — (боковым входам нужен суррогат той же позиции)")
                continue
            cross[sp_] = rr
            note = ""
            if sp_.startswith('shuf'):
                note = "  <- перемешанный ряд против своего sflip: перекос «знак-размер», не порядок"
            elif sp_.startswith('nsflip'):
                note = "  <- наивный sflip приращений: у средней цены бара нечестен (видна арифметика усреднения)"
            elif mirror and sp_ == f'sflip{b_}' and spec.startswith('nsflip'):
                note = "  <- честная нулевая (зеркало бара): настоящий навык наивной модели"
            print(f"   {sp_:<20} {rr['auc']:>8.4f} {rr['auc_se']:>7.4f} "
                  f"{_f(rr.get('win'), '.4f', width=8)}{note}")

    # ---- жёсткая буква: модель, сжатая до номера ближайшей формы
    letter = None
    if cfg['name'].startswith('C0_'):
        pass
    elif cfg['arch'] == 'smc':
        letter = letter_auc(model, data, store.w, cfg, store, spec)
        print(f"\n🔤 ЖЁСТКАЯ БУКВА (ближайшая форма -> её log lift на FIT; {math.log2(K):.0f} бит на окно): "
              f"TUNE AUC {letter['tune']['auc']:.4f} ± {letter['tune']['se']:.4f} | VALIDATION "
              f"{letter['val']['auc']:.4f} ± {letter['val']['se']:.4f} | полная модель на VALIDATION "
              f"{r_v['auc']:.4f}: буква сохраняет {_f(100 * (letter['val']['auc'] - 0.5) / max(r_v['auc'] - 0.5, 1e-9), '.0f')}% "
              f"превышения над 0.5")
    elif cfg['arch'] == 'frozen':
        letter = {'tune': {'auc': r_t['auc'], 'se': r_t['auc_se']}, 'val': {'auc': r_v['auc'], 'se': r_v['auc_se']}}

    # ---- разреженность P: сколько форм реально участвует в токене окна
    sparsity = None
    if cfg['arch'] == 'smc' and not cfg['name'].startswith('C0_'):
        sparsity = p_sparsity(model, ev_v['Xp'])
        print(f"🎯 РАЗРЕЖЕННОСТЬ P (VALIDATION): форм в окне n_eff = exp(энтропия P) — медиана "
              f"{sparsity['neff_med']:.1f}, 90-й перцентиль {sparsity['neff_p90']:.1f} из {K}; доля P на "
              f"ближайшей форме — медиана {sparsity['top_med']:.2f}"
              + (f" | P только по {model.topk} ближайшим" if 0 < model.topk < K else " | P плотное"))

    # ---- гладкие формы: несут ли зубцы прототипов информацию
    smooth = None
    if cfg['arch'] == 'smc' and not cfg['name'].startswith('C0_'):
        smooth = smooth_auc(model, store, spec)
        print(f"🌊 ГЛАДКИЕ ФОРМЫ (прототипы сглажены окном 5, голова та же): TUNE AUC {smooth['tune']:.4f} "
              f"(было {r_t['auc']:.4f}), VALIDATION {smooth['val']:.4f} (было {r_v['auc']:.4f}) | "
              f"шероховатость форм {smooth['rough']:.3f} -> {smooth['rough_s']:.3f}")

    # ---- по годам
    years = None
    if not cfg['name'].startswith('C0_'):
        years = year_profile(model, store, spec, (a, b))
        print(f"\n📅 ПО ГОДАМ (реал против '{spec}'; FIT-годы — в выборке обучения, TUNE и VALIDATION — "
              f"вне; Δlogit — разница средних logit реала и суррогата, до калибровки; сила>=1.25 и lift в/н — "
              f"отметки индикатора с калибровкой TUNE)")
        print(f"   {'часть':<11} {'окон':>7} {'AUC':>8} {'±SE':>7} {'Δlogit':>8} {'сила>=1.25':>11} {'lift в/н':>10}")
        for y_ in years:
            extra = (f" {100 * y_['cov']:>10.1f}% {_f(y_['lift_up'], '.2f', width=4)}/{_f(y_['lift_dn'], '.2f')}"
                     if 'cov' in y_ else "")
            print(f"   {y_['part']:<11} {y_['n']:>7} {y_['auc']:>8.4f} {y_['se']:>7.4f} {y_['gap']:>+8.4f}{extra}")

    # ---- v4.2: запоминание окон или дрейф рынка (только при fit_holdout)
    holdout = None
    H = int(cfg.get('fit_holdout') or 0)
    if H:
        HB = int(cfg.get('hold_block') or 1)
        blk = 'неделя' if HB == 1 else f'{HB} нед.'
        r_in, _, _ = eval_set(model, store.get(hold_key('fitin', cfg), spec))
        r_out, _, _ = eval_set(model, store.get(hold_key('fitout', cfg), spec))
        gap = r_in['auc'] - r_t['auc']
        share = (r_in['auc'] - r_out['auc']) / gap if gap >= HOLD_MIN_GAP else np.nan
        holdout = {'H': H, 'B': HB, 'share': share, 'years': [],
                   'in': {'auc': r_in['auc'], 'se': r_in['auc_se'], 'n': r_in['n']},
                   'out': {'auc': r_out['auc'], 'se': r_out['auc_se'], 'n': r_out['n']}}
        print(f"\n🧪 ЗАПОМИНАНИЕ ИЛИ ДРЕЙФ (отложен каждый {H}-й блок FIT, блок — {blk}; в обучение не шёл): AUC на "
              f"блоках обучения {r_in['auc']:.4f} ± {r_in['auc_se']:.4f} | на отложенных блоках тех же лет "
              f"{r_out['auc']:.4f} ± {r_out['auc_se']:.4f} | TUNE {r_t['auc']:.4f} ± {r_t['auc_se']:.4f}")
        if np.isfinite(share):
            print(f"   доля разрыва «FIT − TUNE», которую даёт запоминание окон (а не смена рынка): "
                  f"(обуч − отлож) / (обуч − TUNE) = {100 * share:.0f}%")
        else:
            print(f"   разрыва «FIT − TUNE» почти нет (< {HOLD_MIN_GAP:g}) — делить его не на что")
        # отложенные окна по годам: AUC вне выборки по всей истории FIT (тренд эффекта во времени)
        line = []
        for y_ in store.fit_years():
            ev = store.get(hold_key('fitout', cfg, y_), spec)
            if ev is None or len(ev['Xp']) < 3000:
                continue
            ry, _, _ = eval_set(model, ev)
            holdout['years'].append({'part': str(y_), 'n': ry['n'], 'auc': ry['auc'], 'se': ry['auc_se']})
            line.append(f"{y_} {ry['auc']:.4f}")
        if line:
            print("   отложенные окна по годам (вне выборки): " + " | ".join(line))

    # ---- калибровка и покрытие
    print(f"\n📏 КАЛИБРОВКА (VALIDATION, p после калибровки на TUNE; ECE {ece:.4f})")
    print(f"   {'p от':>7} {'p до':>7} {'средняя p':>10} {'доля реала':>11} {'окон':>8}")
    for lo_, hi_, pm_, fr_, n_ in cal_rows:
        print(f"   {lo_:>7.4f} {hi_:>7.4f} {pm_:>10.4f} {fr_:>11.4f} {n_:>8}")

    cov = {'q': [], 'lift': []}
    print("\n🎨 ПОКРЫТИЕ И LIFT (VALIDATION; пороги — с TUNE). Отмечено реальных окон / "
          "суррогатных; lift = их отношение, 95% по неделям")
    print(f"   {'порог':<24} {'реал':>7} {'сурр':>7} {'lift':>6} {'95%':>13} {'бары (весь сэмпл)':>18}")
    for q in TOP_Q:
        t_hi = float(np.quantile(sp_t, 1 - q))
        row = lift_ci(sp_v >= t_hi, sn_v >= t_hi, ev_v['wp'], ev_v['wn'], seed=1)
        bars = bar_cover(data, ev_v['st'], sp_v >= t_hi, L) if ev_v['st'] is not None else np.nan
        cov['q'].append({'q': q, 'side': 'up', 'thr': t_hi, 'cov_p': row[0], 'cov_n': row[1],
                         'lift': row[2], 'lo': row[3], 'hi': row[4], 'bars': bars})
        print(f"   {'верх ' + str(int(100 * q)) + '% TUNE':<24} {100 * row[0]:>6.1f}% "
              f"{100 * row[1]:>6.1f}% {row[2]:>6.3f} {row[3]:>6.3f}-{row[4]:<6.3f} "
              f"{_f(100 * bars, '.1f', width=17)}%")
    for q in TOP_Q:
        t_lo = float(np.quantile(sp_t, q))
        row = lift_ci(sp_v <= t_lo, sn_v <= t_lo, ev_v['wp'], ev_v['wn'], seed=2)
        cov['q'].append({'q': q, 'side': 'down', 'thr': t_lo, 'cov_p': row[0], 'cov_n': row[1],
                         'lift': row[2], 'lo': row[3], 'hi': row[4]})
        print(f"   {'низ ' + str(int(100 * q)) + '% TUNE':<24} {100 * row[0]:>6.1f}% "
              f"{100 * row[1]:>6.1f}% {row[2]:>6.3f} {row[3]:>6.3f}-{row[4]:<6.3f}")
    lg_v, ln_v = a * sp_v + b, a * sn_v + b
    for thr_ in LIFT_THR:
        up = lift_ci(lg_v >= math.log(thr_), ln_v >= math.log(thr_), ev_v['wp'], ev_v['wn'], seed=3)
        dn = lift_ci(lg_v <= -math.log(thr_), ln_v <= -math.log(thr_), ev_v['wp'], ev_v['wn'], seed=4)
        bars = (bar_cover(data, ev_v['st'], lg_v >= math.log(thr_), L)
                if ev_v['st'] is not None else np.nan)
        cov['lift'].append({'thr': thr_, 'up': up, 'down': dn, 'both': up[0] + dn[0], 'bars_up': bars})
        print(f"   {'оценка lift >= ' + format(thr_, 'g'):<24} {100 * up[0]:>6.1f}% {100 * up[1]:>6.1f}% "
              f"{up[2]:>6.3f} {up[3]:>6.3f}-{up[4]:<6.3f} {_f(100 * bars, '.1f', width=17)}%")
        print(f"   {'оценка lift <= 1/' + format(thr_, 'g'):<24} {100 * dn[0]:>6.1f}% {100 * dn[1]:>6.1f}% "
              f"{dn[2]:>6.3f} {dn[3]:>6.3f}-{dn[4]:<6.3f}")
    c125 = next(c for c in cov['lift'] if c['thr'] == 1.25)
    print(f"   сила >= 1.25 (обе стороны) покрывает {100 * c125['both']:.1f}% реальных окон VALIDATION "
          f"(ориентир рейтинга lift FINAL: 8.9% по медиане ядра). «бары» — доля баров, если красить "
          f"все L баров отмеченного окна; «реал» — если красить только последний бар окна")

    # ---- формы
    protos_info = {}
    dict_C = None
    try:
        dict_C = load_dict('auto', L)['C']
    except Exception:
        pass
    if cfg['arch'] in ('smc', 'frozen'):
        dname = 'FINAL' if L == 64 else ('R1' if L == 32 else '—')
        norm = cfg.get('dist') == 'cos'
        print(f"\n🧩 ФОРМЫ (VALIDATION, реал против '{spec}', по убыванию частоты; ~слов — расстояние до "
              f"ближайшей буквы {dname} в долях типичного расстояния между соседними буквами {dname}: "
              f"< 0.5 — та же буква)")
        pr = proto_report(model, ev_v, sp_v, K, dict_C, cfg['dead_frac'],
                          top=None if K <= 64 else 48, norm=norm)
        C = model.protos.detach().cpu().numpy()
        Cn = np.stack([_prep_curve(c, norm) for c in C])
        R = lag_corr(Cn, Cn)
        near = pr['near_dict']
        near_med = float(np.nanmedian(near)) if np.isfinite(near).any() else np.nan
        near_same = float(np.mean(near < 0.5)) if np.isfinite(near).any() else np.nan
        probe_n = min(60000, len(pr['lab_p']))
        ari = np.nan
        if dict_C is not None:
            ari = adjusted_rand_score(nearest(ev_v['Xp'][:probe_n], dict_C), pr['lab_p'][:probe_n])
        print(f"   эффективных форм {pr['effK']:.1f} из {K} | пустых (< {cfg['dead_frac']:g}/K) {pr['dead']} | "
              f"крупнейшая {100 * pr['maxU']:.1f}% | шероховатость форм {_roughness(C):.3f} | ~слов медиана "
              f"{_f(near_med, '.2f')}, та же буква у {_f(100 * near_same, '.0f')}% форм | ARI разметки с {dname} "
              f"{_f(ari, '.3f')}")
        order = np.argsort(-pr['usage'])
        fig_grid(C, pr['usage'], pr['lift'], f"{tag}: формы (VALIDATION, lift против {spec})",
                 out_dir + 'grid_final.png', show=SHOW_FIGS, norm=norm)
        fig_heat(Cn, R, out_dir + 'heat.png', f"{tag}: сходство форм между собой")
        for e, Cs in snaps.items():
            nm = 'старт' if e < 0 else f'после эпохи {e}'
            fig_grid(Cs, pr['usage'], pr['lift'], f"{tag}: формы {nm} (подписи — итоговые)",
                     out_dir + ('grid_start.png' if e < 0 else f'grid_e{e:03d}.png'), norm=norm)
        if snaps:
            evo = ([('старт' if e < 0 else f"эп {e}", Cs) for e, Cs in sorted(snaps.items())]
                   + [(f"лучш. эп {best['ep']}", C)])
            fig_evolution(evo, order, out_dir + 'evolution.png', norm=norm)
        protos_info = {'effK': pr['effK'], 'dead': pr['dead'], 'maxU': pr['maxU'], 'rough': _roughness(C),
                       'near_dict_med': near_med, 'near_dict_same': near_same,
                       'ari_dict': ari, 'usage': pr['usage'], 'lift': pr['lift'], 'amp': pr['amp'],
                       'mean_logit': pr['mean_logit']}
        print(f"🖼️ рисунки форм: {out_dir} (grid_final, heat, evolution, grid_start, grid_eNNN)")
    if cfg['arch'] == 'shapelet':
        # v4.3: формы-шейплеты — доля окна у каждой формы у реала и у суррогата, lift = их отношение
        C = model.centered().detach().cpu().numpy()
        u_p, u_n = model.usage(ev_v['Xp']), model.usage(ev_v['Xn'])
        lift_s = u_p / np.maximum(u_n, 1e-12)
        q = u_p / max(u_p.sum(), 1e-12)
        effK = float(np.exp(-(q[q > 0] * np.log(q[q > 0])).sum()))
        print(f"\n🧩 ФОРМЫ-ШЕЙПЛЕТЫ (VALIDATION, реал против '{spec}'): {model.K} форм по {model.m} баров, ищутся в "
              f"любом месте окна; доля — средняя доля окна, описанная формой, у реальных окон; lift — доля у "
              f"реала / доля у суррогата | эффективных форм {effK:.1f} из {model.K} | T {float(model.log_T.exp()):.4f}")
        by_lift = np.argsort(-lift_s)
        for title_, idx_ in (('чаще у реала', by_lift[:10]), ('чаще у суррогата', by_lift[::-1][:10])):
            print(f"   {title_:<17} " + "  ".join(f"#{k} {100 * u_p[k]:.1f}% ×{lift_s[k]:.2f}" for k in idx_))
        fig_grid(C, u_p, lift_s, f"{tag}: формы-шейплеты (VALIDATION, lift против {spec})",
                 out_dir + 'grid_final.png', show=SHOW_FIGS)
        protos_info = {'effK': effK, 'K': model.K, 'usage': u_p, 'lift': lift_s, 'rough': _roughness(C)}
        print(f"🖼️ рисунок форм: {out_dir}grid_final.png")
    # v4.2: окна с крайними оценками — у любой модели (у MLP / CNN других рисунков нет: форм у них нет)
    if not cfg['name'].startswith('C0_'):
        px_note = f" (путь {PRICE_NAMES[data.price]})" if data.price != 'close' else ""
        if fig_extremes(store, sp_v, a, b, f"{tag}: реальные окна VALIDATION с крайними оценками модели{px_note}",
                        out_dir + 'extremes.png', show=SHOW_FIGS and cfg['arch'] not in ('smc', 'frozen')):
            print(f"🖼️ окна с крайними оценками: {out_dir}extremes.png")
    cf = (cnn_forms(model, ev_v['Xp'], ev_v['st'], ev_v.get('Sp'))
          if cfg['arch'] == 'cnn' and not cfg['name'].startswith('C0_') else None)
    if cf is not None:                     # v5.4: у пирамид 'sum' / 'haar' «форм» нет (места — не время)
        forms, contrib, acts = cf
        fig_cnn_forms(forms, contrib, acts, f"{tag}: «формы» каналов последнего слоя", out_dir + 'cnn_forms.png')
        top = np.argsort(-np.abs(contrib))[:8]
        print(f"🖼️ «формы» каналов CNN: {out_dir}cnn_forms.png | сильнейшие каналы: "
              + ", ".join(f"#{c} {contrib[c]:+.3f}" for c in top))

    # ---- сохранение
    secs = time.time() - t_run
    ep_secs = float(np.median([h['sec'] for h in hist])) if hist else 0.0
    res = {'ver': SMC_VER, 'tag': tag, 'label': cfg['label'], 'name': cfg['name'],
           'seed_key': cfg['seed_key'], 'cfg': {k: v for k, v in cfg.items() if k != 'dict'},
           'dict': cfg['dict']['tag'] if cfg['dict'] else None, 'spec': spec,
           'data': {'assets': DATA['assets'], 'tf': DATA['timeframe'], 'N': DATA['N'],
                    'tune_start': DATA['tune_start'], 'price': data.price,
                    'same_windows': bool(store.w.get('same_as_close', True))},
           'best_ep': best['ep'], 'epochs_run': epochs_run, 'tune': r_t, 'val': r_v,
           'platt': [a, b], 'ece': ece, 'cross': cross, 'cov': cov, 'protos': protos_info,
           'letter': letter, 'years': years, 'smooth': smooth, 'sparsity': sparsity, 'holdout': holdout,
           'st': st, 'pine': model.pine_cost(), 'secs': secs, 'sec_ep': ep_secs, 'hist': hist,
           'pine_w': pine_weights(model) if cfg['arch'] == 'cnn' else None,      # v6.3: чисел весов в Pine (бюджет одного скрипта)
           'line': line,                                                         # v6.4: гладкость линии (TUNE / VAL)
           'dir': dir_info,                                                      # v6.7: зеркальная проверка (без ориентации)
           'when': time.strftime('%Y-%m-%d %H:%M:%S'),
           'eval_fp': zlib.crc32(np.asarray(ev_v['wp'][:1000]).tobytes() + np.asarray(sn_v[:1000]).tobytes()) % 10 ** 9}
    with open(RUN_DIR + f"smc_{tag}.json", 'w', encoding='utf-8') as fh:
        json.dump(_jsonable(res), fh, ensure_ascii=False, indent=1)
    arrs = {'tune_sp': sp_t.astype(np.float32), 'tune_sn': sn_t.astype(np.float32),
            'val_sp': sp_v.astype(np.float32), 'val_sn': sn_v.astype(np.float32),
            'tune_wp': ev_t['wp'], 'tune_wn': ev_t['wn'], 'val_wp': ev_v['wp'], 'val_wn': ev_v['wn'],
            'platt': np.array([a, b])}
    for nm_, ev_ in (('tune', ev_t), ('val', ev_v)):        # v4.5: начала окон — для сверки окон между прогонами
        if ev_['st'] is not None:
            arrs[f'{nm_}_st'] = np.asarray(ev_['st'], dtype=np.int64)
    arrs.update(dir_arrs)                                    # v6.7: оценки зеркальных наборов, направление реальных окон
    for k_, v_ in model.state_dict().items():
        arrs['sd_' + k_] = v_.detach().cpu().numpy()
    if protos_info and cfg['arch'] in ('smc', 'frozen'):
        arrs['probe_lab'] = np.asarray(pr['lab_p'][:60000], dtype=np.int16)
    np.savez_compressed(RUN_DIR + f"smc_{tag}.npz", **arrs)
    print(f"\n📋 {tag} | VAL AUC {r_v['auc']:.4f}±{r_v['auc_se']:.4f}"
          + (f" пары {r_v['win']:.4f}" if 'win' in r_v else "")
          + f" | TUNE AUC {r_t['auc']:.4f} | BCE {r_v['bce_cal']:.5f}"
          + f" | сила>=1.25 {100 * c125['both']:.1f}% (lift {_f(c125['up'][2], '.2f')}/{_f(c125['down'][2], '.2f')})"
          + (f" | R линии TUNE {line['tune']['R']:.3f} VAL {line['val']['R']:.3f}"
             if 'R' in line.get('tune', {}) and 'R' in line.get('val', {}) else "")
          + (f" | буква VAL {letter['val']['auc']:.4f}" if letter and cfg['arch'] == 'smc' else "")
          + (f" | effK {protos_info['effK']:.1f}/{protos_info.get('K', K)}" if protos_info else "")
          + (f" | гладкие формы VAL {smooth['val']:.4f}" if smooth else "")
          + (f" | n_eff P {sparsity['neff_med']:.1f}" if sparsity else "")
          + (f" | FIT обуч/отлож {holdout['in']['auc']:.4f}/{holdout['out']['auc']:.4f}" if holdout else "")
          + (f" | Δ_зеркало TUNE {dir_info['tune']['d_mirror']:+.4f} VAL {dir_info['val']['d_mirror']:+.4f}"
             if dir_info and 'tune' in dir_info and 'val' in dir_info else "")
          + f" | эпох {epochs_run} ({ep_secs:.1f} c) | {secs / 60:.1f} мин")
    print(f"💾 {RUN_DIR}smc_{tag}.json / .npz")
    return res


# =====================================================================
# РЕЖИМЫ
# =====================================================================
def _lag1(x):
    ok = np.isfinite(x[1:]) & np.isfinite(x[:-1])
    return float(np.corrcoef(x[1:][ok], x[:-1][ok])[0, 1]) if ok.sum() > 2 else np.nan


def load_data(price='close'):
    t0 = time.time()
    data = SeriesData(DATA['assets'], DATA['timeframe'], DATA['N'], DATA['tune_start'], price)
    for s in data.series:
        m = s['meta']
        print(f"📈 {s['asset']} {m['tf']}: TRAINING {m['parts']['TRAINING']['from'][:10]} → "
              f"{m['parts']['TRAINING']['to'][:10]}, VALIDATION {m['parts']['VALIDATION']['from'][:10]} → "
              f"{m['parts']['VALIDATION']['to'][:10]} | CSV до {m['csv_last'][:16]}"
              + (" | полы " + ", ".join(f"L={L} {f:.5f}" for L, f in sorted(s['floors'].items()))
                 if s['floors'] else ""))
    if price in MULTI_KINDS:
        lags = ", ".join(f"{PRICE_NAMES[p_]} {_lag1(e_ - d_):+.3f}" for p_, e_, d_ in zip(MULTI_PRICES, data.chan_e, data.chan_d))
        print(f"💱 три цены бара одной сетью ({PRICE_NAMES[price]}): каналы средних цен из TrendyCoins_SMC_Prices | "
              f"конечны там же, где close: {'✅' if data.same_fin else '❗ НЕТ'} | lag-1: close {_lag1(data.rc):+.3f}, {lags}")
        if price in LEVEL_KINDS:               # v5.6: диапазон бара
            gv = data.chan_g[np.isfinite(data.chan_g)]
            print(f"📏 диапазон бара (TrendyCoins_SMC_Range, в единицах делителя r): медиана {np.median(gv):.3f}, p99 "
                  f"{np.percentile(gv, 99):.2f} | бар без движения {100 * (gv == 0).mean():.3f}%")
        if price == 'multi_gc':                # v5.7: положение close в баре
            fin = np.isfinite(data.chan_o) & np.isfinite(data.chan_g) & (data.chan_g > 0)
            q = data.chan_o[fin] / data.chan_g[fin]
            rr = data.r[fin]
            print(f"📍 положение close в баре (close − HL/2) / (high − low): медиана {np.median(q):+.3f}, |…| > 0.45 у "
                  f"{100 * (np.abs(q) > 0.45).mean():.1f}% баров | бар вверх: {np.median(q[rr > 0]):+.3f}, вниз: "
                  f"{np.median(q[rr < 0]):+.3f} (медианы) | за пределы ±0.5: {int((np.abs(q) > 0.5 + 1e-4).sum())} баров")
    elif price != 'close':
        print(f"💱 цена бара {PRICE_NAMES[price]}: приращения из TrendyCoins_SMC_Prices | конечны там же, где close: "
              f"{'✅' if data.same_fin else '❗ НЕТ'} | lag-1 корреляция приращений: close {_lag1(data.rc):+.3f}, "
              f"{PRICE_NAMES[price]} {_lag1(data.r):+.3f} (у средней цены бара — во многом арифметика усреднения)")
    print(f"📦 данные в памяти {data.r.nbytes / 1e6:.0f} МБ | {DEVICE} | {time.time() - t0:.1f} c")
    return data


def get_data(datas, price='close'):
    """v4.5: данные по цене бара — загружаются один раз на задание."""
    if price not in datas:
        datas[price] = load_data(price)
    return datas[price]


def get_store(datas, stores, price, L):
    """v4.5: наборы проверки по (цена бара, L) — кэш на всё задание. v6.7: без ориентации (ORIENT = False) — свои наборы."""
    key = (price, L) if ORIENT else (price, L, 'abs')
    if key not in stores:
        stores[key] = EvalStore(get_data(datas, price), L)
    return stores[key]


def check_mode(data):
    """Сверка torch-формы с numpy-формой SuMo на пробе + разметка окон + скорость шага."""
    print("\n🔎 СВЕРКА ФОРМ torch против numpy (проба из SMC_Data)")
    for i, s in enumerate(data.series):
        for L, (pos, Xnp) in sorted(s['probe'].items()):
            st = torch.from_numpy(pos + s['off']['tr']).to(DEVICE)
            fl = torch.full((len(pos),), data.floor(i, L), device=DEVICE)
            X = to_shapes(gather(data.r_t, st, L), fl).cpu().numpy()
            same = np.sign(X[:, -1]) == np.sign(Xnp[:, -1])
            d = np.abs(X - Xnp)[same].max() if same.any() else np.nan
            rel = d / max(np.abs(Xnp).max(), 1e-12)
            ok = (1 - same.mean()) < 1e-3 and rel < 1e-4
            print(f"   {'✅' if ok else '❌'} {s['asset']} L={L}: окон {len(pos)} | расхождение переворота "
                  f"{100 * (1 - same.mean()):.3f}% | max|Δ| {d:.2e} (отн. {rel:.1e})")
    for L in sorted({32, 64} | {it[1].get('L', SMC_BASE['L']) for j in JOBS.values() for it in j}):
        w = data.windows(L)
        print(f"   L={L}: окон FIT {len(w['fit'])}, TUNE {len(w['tune'])}, VAL {len(w['val'])} | "
              f"недель VAL {len(np.unique(w['t_end'][w['val']] // WEEK_NS))}")
    cfg = make_cfg('A1_base', {'L': SMC_BASE['L']}, 'a')
    w = data.windows(cfg['L'])
    gen = torch.Generator(device=DEVICE)
    gen.manual_seed(1)
    pm = PairMaker(data, cfg['L'], cfg, float('inf'), gen)
    idx = torch.from_numpy(w['st'][w['fit'][:cfg['batch'] // 2]]).to(DEVICE)
    sid = torch.from_numpy(w['sid'][w['fit'][:cfg['batch'] // 2]]).to(DEVICE)
    Xs = to_shapes(gather(data.r_t, idx, cfg['L']), w['floor_t'][sid])
    model, st = build_model(cfg, Xs, np.random.default_rng(0))
    opt = torch.optim.AdamW(model.parameters(), lr=1e-3)
    for rep in range(2):
        if DEVICE.type == 'cuda':
            torch.cuda.synchronize()
        t0 = time.time()
        for _ in range(20):
            Wp, Wn, fl = pm.make(idx, sid)
            X = torch.cat([to_shapes(Wp, fl), to_shapes(Wn, fl)])
            y = torch.cat([torch.ones(len(Wp), device=DEVICE), torch.zeros(len(Wn), device=DEVICE)])
            logit, D, P, _ = model(X)
            total = sum(loss_terms(model, logit, y, D, cfg, st, st['gap0'], 1.0).values())
            opt.zero_grad()
            total.backward()
            opt.step()
        if DEVICE.type == 'cuda':
            torch.cuda.synchronize()
    ms = (time.time() - t0) / 20 * 1000
    steps = len(w['fit']) // (cfg['batch'] // 2)
    print(f"⏱️ шаг A1_base L={cfg['L']} K={cfg['K']}: {ms:.1f} мс -> эпоха ~{steps * ms / 1000:.0f} c "
          f"({steps} шагов) + проверка")
    mdata = check_prices(data)
    check_pyr(mdata)                       # v5.4: пирамида доходностей — на данных трёх цен бара
    check_tok(mdata)                       # v5.5: признаки токена
    gdata = check_range(data, mdata)       # v5.6: диапазон бара
    check_rx(gdata)                        # v5.7: положение close в баре, ориентация знаковых уровней, старые RG_den
    check_nt(gdata)                        # v6.0: признаки истории в барах, глубина, честность, старые F3_g


def check_range(close_data, mdata, L=64):
    """v5.6: канал «диапазон бара» (цена 'multi_g', VALIDATION BTC): (1) файл smc_range есть и посчитан для того же ряда
       (контрольная сумма — при загрузке), окна те же, что у close и у трёх цен 'multi'; (2) каналы 0-2 окна и формы — бит в
       бит как у 'multi', канал 3 формы — диапазон бара / делитель окна (уровень: без суммы, центрирования и ориентации);
       (3) наборы проверки (зеркало sflip4): каналы 0-2 и боковые входы — бит в бит как у 'multi' (те же перевёрнутые бары —
       сравнение с F1 парное), диапазон у суррогата — как у его реального окна; переворот с одними +1 — реальное окно;
       (4) справочно — диапазон в шагах close окна."""
    print("\n🔎 ДИАПАЗОН БАРА (v5.6)")
    if mdata is None:
        print("   ⏭️ нет данных трёх цен бара")
        return
    try:
        data = load_data('multi_g')
    except (FileNotFoundError, ValueError) as e:
        print(f"   ⏭️ {e}")
        return
    w = data.windows(L)
    same = bool(np.array_equal(w['st'], close_data.windows(L)['st']) and np.array_equal(w['st'], mdata.windows(L)['st']))
    pick = w['val'][:5000]
    st = torch.from_numpy(w['st'][pick]).to(DEVICE)
    fl = w['floor_t'][torch.from_numpy(w['sid'][pick]).to(DEVICE)]
    W, Wm = data.gw(st, L), mdata.gw(st, L)
    exact = bool(torch.equal(W, data.flip_multi(st, L, torch.ones(len(st), L + 1, device=DEVICE), W)))
    ch_same = bool(torch.equal(W[:, :N_PATH], Wm))
    X, Xm = to_shapes(W, fl), to_shapes(Wm, fl)
    div = torch.maximum(median_abs(W[:, 0]), fl)
    shp_same = bool(torch.equal(X[:, :N_PATH], Xm))
    lvl_ok = bool(torch.equal(X[:, N_PATH], W[:, N_PATH] / div[:, None]))
    print(f"   {'✅' if same and exact and ch_same else '❌'} {PRICE_NAMES['multi_g']} L={L}: окна те же, что у close и у трёх цен — "
          f"{same} | переворот с одними +1 = реальное окно — {exact} | каналы 0-2 = 'multi' — {ch_same}")
    print(f"   {'✅' if shp_same and lvl_ok else '❌'} форма: каналы 0-2 бит в бит как у 'multi' — {shp_same} | канал 3 = диапазон / "
          f"делитель окна (без суммы, центрирования и ориентации) — {lvl_ok}")
    store, storem = EvalStore(data, L), EvalStore(mdata, L)
    ev, evm = store.get('val', 'sflip4'), storem.get('val', 'sflip4')
    sur_same = bool(torch.equal(ev['Xp'][:, :N_PATH], evm['Xp']) and torch.equal(ev['Xn'][:, :N_PATH], evm['Xn'])
                    and torch.equal(ev['Sp'], evm['Sp']) and torch.equal(ev['Sn'], evm['Sn']))
    lvl_pair = bool(torch.equal(ev['Xn'][:, N_PATH], ev['Xp'][:, N_PATH]))
    print(f"   {'✅' if sur_same and lvl_pair else '❌'} наборы проверки (зеркало sflip4): реальные окна, суррогаты и боковые входы — "
          f"бит в бит как у 'multi' (сравнение с F1 парное) — {sur_same} | диапазон у суррогата = у его реального окна — {lvl_pair}")
    g = ev['Xp'][:, N_PATH, 1:].reshape(-1)
    g = g[::max(1, g.numel() // 1_000_000)]                  # подвыборка: quantile не берёт больше 16 млн чисел
    print(f"   справочно: диапазон бара в шагах close окна (медиана |шага| close = 1) — медиана {float(g.median()):.2f}, p90 "
          f"{float(g.quantile(0.9)):.2f} | бар без движения {100 * float((g == 0).float().mean()):.3f}%")
    del store, storem
    return data


def _orient_invariant(data, st, fl, L):
    """v5.7: форма окна не меняется, если перевернуть все его бары (зеркало бара со всеми −1): путь становится −X, ориентация
       возвращает его обратно, знаковые уровни — тоже. Окна в полосе ничьей ориентации (|конец центрированного close-пути|
       <= ORIENT_EPS · делитель, v6.0) не считаются: там не переворачиваются ни окно, ни его зеркало. Возвращает (совпало бит в
       бит, окон в сверке)."""
    W = data.gw(st, L)
    Wm = data.flip_multi(st, L, -torch.ones(len(st), L + 1, device=DEVICE), W)
    X, Xm = to_shapes(W, fl), to_shapes(Wm, fl)
    cs = torch.cumsum(W[:, 0], dim=1)
    keep = (cs[:, -1] - cs.mean(dim=1)).abs() > ORIENT_EPS * torch.maximum(median_abs(W[:, 0]), fl)
    return bool(torch.equal(X[keep], Xm[keep])), int(keep.sum())


def check_rx(gdata, L=64):
    """v5.7: канал «положение close в баре» (цена 'multi_gc', VALIDATION BTC) и новые пути кода: (1) окна — те же, что у
       'multi_g'; каналы 0-3 окна — бит в бит как у 'multi_g'; переворот с одними +1 — реальное окно; (2) данные: close внутри
       диапазона бара (|o| <= g / 2); (3) суррогат: у перевёрнутого бара o меняет знак (o' = s·o бит в бит), диапазон — тот же;
       (4) форма не меняется от переворота всех баров окна (ориентация переворачивает и знаковый уровень) — у 'multi_g' и
       'multi_gc'; (5) наборы проверки (зеркало sflip4): каналы 0-3 и боковые входы — бит в бит как у 'multi_g' (сравнение с
       RG_den парное), |o| у суррогата — как у его реального окна; (6) старые RG_den через новый код — VAL AUC как в json."""
    print("\n🔎 ПОЛОЖЕНИЕ CLOSE В БАРЕ И НОВЫЕ ПУТИ КОДА (v5.7)")
    if gdata is None:
        print("   ⏭️ нет данных с диапазоном бара ('multi_g')")
        return
    try:
        data = load_data('multi_gc')
    except (FileNotFoundError, ValueError) as e:
        print(f"   ⏭️ {e}")
        return
    w = data.windows(L)
    same = bool(np.array_equal(w['st'], gdata.windows(L)['st']))
    pick = w['val'][:5000]
    st = torch.from_numpy(w['st'][pick]).to(DEVICE)
    fl = w['floor_t'][torch.from_numpy(w['sid'][pick]).to(DEVICE)]
    W, Wg = data.gw(st, L), gdata.gw(st, L)
    exact = bool(torch.equal(W, data.flip_multi(st, L, torch.ones(len(st), L + 1, device=DEVICE), W)))
    ch_same = bool(torch.equal(W[:, :N_PATH + 1], Wg))
    print(f"   {'✅' if same and exact and ch_same else '❌'} {PRICE_NAMES['multi_gc']} L={L}: окна те же, что у 'multi_g' — {same} | "
          f"переворот с одними +1 = реальное окно — {exact} | каналы 0-3 = 'multi_g' — {ch_same}")
    o, g = W[:, N_PATH + 1], W[:, N_PATH]
    inside = bool((o.abs() <= 0.5 * g * (1 + 1e-5) + 1e-6).all())
    print(f"   {'✅' if inside else '❌'} close внутри диапазона своего бара: |o| <= g / 2 у всех баров сверки — {inside}")
    gen = torch.Generator()
    gen.manual_seed(7)
    S = block_signs_prev(len(st), L, 4, gen, 'cpu').to(DEVICE)
    Wn = data.flip_multi(st, L, S, W)
    o_ok = bool(torch.equal(Wn[:, N_PATH + 1], S[:, 1:] * o)) and bool(torch.equal(Wn[:, N_PATH], g))
    inv_g, n_g = _orient_invariant(gdata, st, fl, L)
    inv_c, n_c = _orient_invariant(data, st, fl, L)
    print(f"   {'✅' if o_ok else '❌'} суррогат: o' = s·o у каждого бара, диапазон тот же (бит в бит) — {o_ok} | "
          f"{'✅' if inv_g and inv_c else '❌'} форма не меняется от переворота всех баров окна: 'multi_g' — {inv_g} ({n_g} окон), "
          f"'multi_gc' — {inv_c} ({n_c} окон)")
    store, storeg = EvalStore(data, L), EvalStore(gdata, L)
    ev, evg = store.get('val', 'sflip4'), storeg.get('val', 'sflip4')
    sur_same = bool(torch.equal(ev['Xp'][:, :N_PATH + 1], evg['Xp']) and torch.equal(ev['Xn'][:, :N_PATH + 1], evg['Xn'])
                    and torch.equal(ev['Sp'], evg['Sp']) and torch.equal(ev['Sn'], evg['Sn']))
    o_pair = bool(torch.equal(ev['Xn'][:, N_PATH + 1].abs(), ev['Xp'][:, N_PATH + 1].abs()))
    print(f"   {'✅' if sur_same and o_pair else '❌'} наборы проверки (зеркало sflip4): каналы 0-3, суррогаты и боковые входы — бит в "
          f"бит как у 'multi_g' (сравнение с RG_den парное) — {sur_same} | |o| у суррогата = у его реального окна — {o_pair}")
    for seed in ('a', 'b', 'c'):
        try:
            model, r = load_finalist('RG_den', seed, L)
        except FileNotFoundError as e:
            print(f"   ⏭️ {e}")
            continue
        a_ = auc_se(score(model, evg['Xp'], S=evg['Sp']), score(model, evg['Xn'], S=evg['Sn']), evg['wp'], evg['wn'])[0]
        ok = abs(a_ - r['val']['auc']) < 2e-4
        print(f"   {'✅' if ok else '❌'} старый RG_den через новый код ({r['tag']}): VAL AUC {a_:.4f}, в json прогона "
              f"{r['val']['auc']:.4f}" + ("" if ok else " — проверка изменилась, сравнение с RG_den не читать"))
        del model
    del store, storeg


def orient_sign(W, floor):
    """v6.0: знак ориентации формы окна (−1 — форма перевёрнута): то же правило ничьей, что в to_shapes и side_feats."""
    if W.dim() == 3:
        W = W[:, 0]
    div = torch.maximum(median_abs(W), floor)
    cs = torch.cumsum(W, dim=1)
    return torch.where(cs[:, -1] - cs.mean(dim=1) < -ORIENT_EPS * div, -1.0, 1.0)


def check_nt(gdata, L=64):
    """v6.0: признаки истории в барах (цена 'multi_g', BTC): (1) файл smc_bars (при загрузке — контрольная сумма r, длины,
       close бит в бит): медиана диапазона за 200 баров перед баром — тот же нормировщик, что у r; (2) глубина — на пробе
       (первые 1200 баров первой части с разогревом) бар j возмущается: признаки меняются только у окон с началом s в
       [j + 1, j + 200], последнее — ровно s = j + 200; сдвиг бара j целиком (диапазон и тело те же) не меняет окно s = j + 1
       (бар перед окном в знакозависимое не идёт); (3) честность — у реального окна и его суррогата (зеркало sflip4, VAL)
       столбцы без знака совпадают бит в бит, со знаком — с точностью до знака ориентации своего окна; (4) справочно — средние
       и sd признаков на FIT, AUC одного признака «реал против суррогата» на VAL; (5) старая F3_g через новый код (с правилом
       ничьей) — VAL AUC как в json (старая RG_den — в сверке v5.7 выше); (6) правило ничьей — доля окон в полосе ничьей."""
    print("\n🔎 ПРИЗНАКИ ИСТОРИИ В БАРАХ И ПРАВИЛО НИЧЬЕЙ (v6.0)")
    if gdata is None:
        print("   ⏭️ нет данных с диапазоном бара ('multi_g')")
        return
    if not gdata.nt_ok:
        print("   ❌ нет smc_bars — сначала TrendyCoins_SMC_Bars (в той же папке, что smc_series): модели NT1 / NT3 не запустятся")
        return
    st_ = gdata.nt_stats
    print(f"   {'✅' if st_['norm_err'] < 1e-5 else '❌'} медиана диапазона за 200 баров перед баром = нормировщик r: max отн. "
          f"|r · медиана − Δclose| / |Δclose| = {st_['norm_err']:.1e} | open ≠ прошлого close у {100 * st_['open_gap']:.2f}% баров "
          f"| медиана |close − open| / (high − low) {st_['body_rng']:.3f}")
    o, h, l, c = gdata.nt_probe
    f0 = nt_segment(o, h, l, c)
    j = 600
    rng0 = h[j] - l[j]
    p = [x.copy() for x in (o, h, l, c)]
    p[0][j] += 0.3 * rng0
    p[3][j] -= 0.4 * rng0
    p[1][j] = max(p[0][j], p[3][j], h[j]) + 0.2 * rng0
    p[2][j] = min(p[0][j], p[3][j], l[j]) - 0.2 * rng0
    ch = np.where(np.any(nt_segment(*p) != f0, axis=0))[0] + NT_HIST          # начала окон, у которых что-то поменялось
    ok_depth = len(ch) > 0 and ch.min() >= j + 1 and ch.max() == j + NT_HIST
    q = [x.copy() for x in (o, h, l, c)]
    for x in q:
        x[j] += 0.37 * rng0                                                  # бар j целиком: диапазон и тело те же
    ch2 = np.where(np.any(nt_segment(*q) != f0, axis=0))[0] + NT_HIST
    ok_prev = len(ch2) > 0 and ch2.min() == j + 2
    print(f"   {'✅' if ok_depth else '❌'} глубина: возмущение бара {j} меняет признаки окон с началом {ch.min() if len(ch) else '—'} … "
          f"{ch.max() if len(ch) else '—'} (обязано: {j + 1} … {j + NT_HIST}, не глубже 200 баров) | "
          f"{'✅' if ok_prev else '❌'} сдвиг бара {j} целиком — первое изменённое окно {ch2.min() if len(ch2) else '—'} "
          f"(обязано {j + 2}: бар перед окном в знакозависимое не идёт)")
    w = gdata.windows(L)
    pick = w['val'][:20000]
    st = torch.from_numpy(w['st'][pick]).to(DEVICE)
    fl = w['floor_t'][torch.from_numpy(w['sid'][pick]).to(DEVICE)]
    W = gdata.gw(st, L)
    gen = torch.Generator()
    gen.manual_seed(11)
    Wn = gdata.flip_multi(st, L, block_signs_prev(len(st), L, 4, gen, 'cpu').to(DEVICE), W)
    cols = slice(NT_COL0, NT_COL0 + NT_N)
    Sp, Sn = side_feats(gdata, st, L, W, fl)[:, cols], side_feats(gdata, st, L, Wn, fl)[:, cols]
    gp, gn = orient_sign(W, fl), orient_sign(Wn, fl)
    ori = torch.from_numpy(NT_ORIENT).to(DEVICE)
    free_same = bool(torch.equal(Sp[:, ~ori], Sn[:, ~ori]))
    or_same = bool(torch.equal(Sp[:, ori] * gp[:, None], Sn[:, ori] * gn[:, None]))
    flip_share = float((gp != gn).float().mean())
    print(f"   {'✅' if free_same and or_same else '❌'} честность (зеркало sflip4, {len(st)} окон VAL): столбцы без знака у реала и "
          f"суррогата бит в бит — {free_same} | со знаком — те же с точностью до знака ориентации своего окна — {or_same} "
          f"(ориентация у суррогата другая в {100 * flip_share:.0f}% пар)")
    X0 = W[:, 0]
    cs = torch.cumsum(X0, dim=1)
    endv = (cs[:, -1] - cs.mean(dim=1)).abs() / torch.maximum(median_abs(X0), fl)
    print(f"   правило ничьей: окон в полосе |конец пути| <= {ORIENT_EPS:g} · делитель — {100 * float((endv <= ORIENT_EPS).float().mean()):.4f}%, "
          f"конец пути ровно 0 — {100 * float((endv == 0).float().mean()):.4f}%")
    store = EvalStore(gdata, L)
    fp = store.get('fitprobe', 'sflip4')
    ev = store.get('val', 'sflip4')
    print(f"   {'':>3} {'признак':<66} {'ср. FIT':>8} {'sd FIT':>7} {'AUC одного':>10}")
    for jj, (nm, orient, _) in enumerate(_NT):
        cidx = NT_COL0 + jj
        zf = fp['Sp'][:, cidx]
        a_ = (auc_parts(ev['Sp'][:, cidx].double().cpu().numpy(), ev['Sn'][:, cidx].double().cpu().numpy())[0]
              if orient else np.nan)
        print(f"   {cidx:>3} {nm[:66]:<66} {float(zf.mean()):>8.3f} {float(zf.std()):>7.3f} {_f(a_, '.4f', width=10)}")
    print("   «AUC одного» — реал против суррогата по одному признаку (выше — реал); у столбцов без знака он ровно 0.5 (—): сами "
          "по себе реал от суррогата они не отличают, только через узор знаков окна")
    for seed in ('a', 'b', 'c'):
        try:
            model, r = load_finalist('F3_g', seed, L)
        except FileNotFoundError as e:
            print(f"   ⏭️ {e}")
            continue
        a_ = auc_se(score(model, ev['Xp'], S=ev['Sp']), score(model, ev['Xn'], S=ev['Sn']), ev['wp'], ev['wn'])[0]
        ok = abs(a_ - r['val']['auc']) < 2e-4
        print(f"   {'✅' if ok else '❌'} старая F3_g через новый код ({r['tag']}): VAL AUC {a_:.4f}, в json прогона "
              f"{r['val']['auc']:.4f}" + ("" if ok else " — проверка изменилась, сравнение с F3_g не читать"))
        del model
    del store


def check_tok(data, L=64):
    """v5.5: признаки токена (столбцы side_feats 26-36) на реальных данных (цена 'multi', VALIDATION BTC): (1) столбцы без
       знаков (28-30, 36) у реального окна и его суррогата (зеркало sflip4) совпадают бит в бит, остальные у суррогата —
       свои (считаются по его окну); (2) амплитуда и ER — те же, что у формы окна (log_amp и ER B_simple по close-каналу);
       (3) close в файлах данных есть (абсолютная вола) и её уровень по ассетам; (4) справочно — признаки у реала и
       суррогата: средние, sd по FIT (масштаб входа модели), AUC одного признака «выше — реал» (у признаков без знаков —
       ровно 0.5: сами по себе они реал от суррогата не отличают). Что совпадение у пары само по себе честности не
       доказывает (утечку нормировщика ловит только стенд на случайном блуждании) — см. check_pyr: 28-30 считаются по
       модулям шагов окна (у sflip те же), 36 — по прошлому до бара start − 2 и от знаков не зависит вовсе."""
    print("\n🔎 ПРИЗНАКИ ТОКЕНА (v5.5)")
    if data is None:
        print("   ⏭️ нет данных трёх цен бара")
        return
    store = EvalStore(data, L)
    ev = store.get('val', 'sflip4')
    Sp, Sn = ev['Sp'], ev['Sn']
    sf = list(TOK_SIGNFREE)
    sg = [c for c in TOK_COLS if c not in TOK_SIGNFREE]
    same = bool(torch.equal(Sp[:, sf], Sn[:, sf]))
    diff = float((Sp[:, sg] != Sn[:, sg]).float().mean())
    print(f"   {'✅' if same else '❌'} столбцы без знаков ({', '.join(map(str, sf))}) у реального окна и его суррогата совпадают "
          f"бит в бит | столбцы со знаками ({sg[0]}, {sg[1]}, {sg[2]}-{sg[-1]}) у суррогата свои: отличаются в "
          f"{100 * diff:.1f}% значений")
    X0 = ev['Xp'][:, 0] if ev['Xp'].dim() == 3 else ev['Xp']
    ref = SimpleBase.raw(X0)
    d_amp, d_er = float((Sp[:, TOK_COL0] - ref[:, 0]).abs().max()), float((Sp[:, TOK_COL0 + 1] - ref[:, 1]).abs().max())
    print(f"   {'✅' if d_amp < 1e-3 and d_er < 1e-4 else '❌'} амплитуда и ER — те же, что у формы окна (log_amp и ER B_simple "
          f"по close-каналу): max|Δ| {d_amp:.1e} / {d_er:.1e}")
    if not data.absv_ok:
        print("   ❌ в smc_series нет close_tr / close_va — абсолютной волы нет (TK_absv, TK_all, TK_all_c не запустятся): "
              "перезапусти TrendyCoins_SMC_Data")
    else:
        lv = data.absv_log_t.cpu().numpy()
        cells = []
        for i, s in enumerate(data.series):
            o, n = s['off']['tr'], s['n']['tr']
            ov, nv = s['off']['va'], s['n']['va']
            cells.append(f"{s['asset']} TRAINING {np.exp(np.median(lv[o:o + n])):.1f}, VAL {np.exp(np.median(lv[ov:ov + nv])):.1f}")
        print("   ✅ абсолютная вола (делитель r = медиана диапазона бара за 200 баров, в б.п. цены; медиана): " + " | ".join(cells))
    fp = store.get('fitprobe', 'sflip4')
    print(f"   {'признак':<38} {'реал VAL':>9} {'сурр VAL':>9} {'sd FIT':>8} {'AUC одного':>10}")
    for c in TOK_COLS:
        a_ = auc_parts(Sp[:, c].double().cpu().numpy(), Sn[:, c].double().cpu().numpy())[0]
        print(f"   {c:>2} {SIDE_NAMES[c]:<35} {float(Sp[:, c].mean()):>9.4f} {float(Sn[:, c].mean()):>9.4f} "
              f"{float(fp['Sp'][:, c].std()):>8.4f} {a_:>10.4f}")
    print("   «AUC одного» — реал против суррогата по одному признаку (выше — реал); у признаков без знаков ровно 0.5, у "
          "остальных — сколько различения признак даёт сам (сеть видит те же шаги и может посчитать его сама). Что столбцы "
          f"0-{TOK_COL0 - 1} не сдвинулись, проверяет сверка старых F1 выше (AUC как в json)")
    del store


def check_pyr(data, L=64):
    """v5.4: пирамида доходностей на реальных данных (цена 'multi', VALIDATION BTC): (1) устройство входа — канал k = 1
       у 'ms' — те же шаги, что у сети на шагах; уровни 'sum' — суммы соседних клеток уровня ниже; 'haar' без потерь;
       (2) нормы H_k у реального окна и его суррогата совпадают бит в бит (у пары одна норма). Что норма смотрит только в
       прошлое, обеспечено построением (бар start − 2), а не этой сверкой: норма, заглянувшая в окно, у пары тоже была бы
       одна — такую утечку ловит только стенд на случайном блуждании; (3) старые F1 волны 9 через новый код — VAL AUC как в
       json прогона (проверка не изменилась); (4) справочно — размер доходностей за k баров у реала и суррогата."""
    print("\n🔎 ПИРАМИДА ДОХОДНОСТЕЙ (v5.4)")
    if data is None:
        print("   ⏭️ нет данных трёх цен бара")
        return
    store = EvalStore(data, L)
    ev = store.get('val', 'sflip4')
    n = min(20000, len(ev['Xp']))
    X, S = ev['Xp'][:n], ev['Sp'][:n]
    C = X.shape[1]
    u = F.pad(X[..., 1:] - X[..., :-1], (1, 0))
    ms = pyr_input(X, 'ms', 'rw').view(n, C, len(PYR_MS_K), L)
    ok_ms = bool(torch.equal(ms[:, :, 0], u))
    sm, lv, off = pyr_input(X, 'sum', 'rw'), [], 0
    for j in range(1, 7):
        lv.append(sm[..., off:off + (L >> j)] * math.sqrt(2 ** j))
        off += L >> j
    tol = 1e-4 * float(u.abs().max())
    err_sum = max(float((lv[j + 1] - lv[j][..., 0::2] - lv[j][..., 1::2]).abs().max()) for j in range(5))
    err_sum = max(err_sum, float((lv[5][..., 0] - u.sum(-1)).abs().max()), float((sm[..., -1] - u[..., -1]).abs().max()))
    hr = pyr_input(X, 'haar', 'rw')
    a, pos = hr[..., -1:], L - 1                      # обратный Хаар: от суммы окна к шагам
    while a.shape[2] < L:
        m_ = a.shape[2]
        d = hr[..., pos - m_:pos]
        pos -= m_
        a = torch.stack([(a + d) * math.sqrt(0.5), (a - d) * math.sqrt(0.5)], dim=3).reshape(n, C, 2 * m_)
    err_haar = float((a - u).abs().max())
    hk = slice(HIST_COL0, HIST_COL0 + len(HIST_K))           # v5.5: дальше идут признаки токена — у суррогата свои
    ok_hist = bool(torch.equal(ev['Sp'][:, hk], ev['Sn'][:, hk]))
    print(f"   {'✅' if ok_ms else '❌'} 'ms': канал k = 1 — те же шаги, что у сети на шагах (бит в бит) | "
          f"{'✅' if err_sum <= tol else '❌'} 'sum': уровни — суммы соседних клеток, верх — сумма окна (max|Δ| {err_sum:.1e}) | "
          f"{'✅' if err_haar <= tol else '❌'} 'haar': обратное преобразование возвращает шаги (max|Δ| {err_haar:.1e})")
    print(f"   {'✅' if ok_hist else '❌'} нормы H_k (столбцы {HIST_COL0}-{HIST_COL0 + len(HIST_K) - 1}) у реального окна и его "
          f"суррогата (зеркало sflip4) совпадают бит в бит — у пары одна норма (из прошлого до окна: бар start − 2)")
    g = S[:, HIST_COL0:HIST_COL0 + len(HIST_K)]
    print("   типичный множитель 'hist' (делитель окна / H_k, медиана по окнам VAL): "
          + " | ".join(f"k={k} {float(torch.exp(g[:, j]).median()):.3f}" for j, k in enumerate(HIST_K)))
    msn = pyr_input(ev['Xn'][:n], 'ms', 'rw').view(n, C, len(PYR_MS_K), L)
    print("   справочно, 'rw' (close, места с полной суммой): RMS доходности за k баров / √k — реал / суррогат (отношение): "
          + " | ".join(f"k={k} {float(ms[:, 0, j, k:].pow(2).mean().sqrt()):.3f} / {float(msn[:, 0, j, k:].pow(2).mean().sqrt()):.3f} "
                       f"({float(ms[:, 0, j, k:].pow(2).mean().sqrt() / msn[:, 0, j, k:].pow(2).mean().sqrt()):.3f})"
                       for j, k in enumerate(PYR_MS_K)))
    for seed in ('a', 'b', 'c'):
        try:
            model, r = load_finalist(PYR_REF, seed, L)
        except FileNotFoundError as e:
            print(f"   ⏭️ {e}")
            continue
        a_ = auc_se(score(model, ev['Xp'], S=ev['Sp']), score(model, ev['Xn'], S=ev['Sn']), ev['wp'], ev['wn'])[0]
        ok = abs(a_ - r['val']['auc']) < 2e-4
        print(f"   {'✅' if ok else '❌'} старый F1 через новый код ({r['tag']}): VAL AUC {a_:.4f}, в json прогона "
              f"{r['val']['auc']:.4f}" + ("" if ok else " — проверка изменилась, сравнение с волной 9 не читать"))
        del model
    del store


def check_prices(close_data, L=64):
    """v4.5: у каждой цены бара с файлом TrendyCoins_SMC_Prices — окна те же, что у close; зеркало с одними +1
       даёт реальное окно бит в бит; знаки баров у суррогатов — те же, что у close (один мир суррогатов)."""
    print("\n🔎 ЦЕНЫ БАРА (TrendyCoins_SMC_Prices)")
    for price in ('hl2', 'hlc3'):
        try:
            data = load_data(price)
        except (FileNotFoundError, ValueError) as e:
            print(f"   ⏭️ {PRICE_NAMES[price]}: {e}")
            continue
        w, wc = data.windows(L), close_data.windows(L)
        same = bool(np.array_equal(w['st'], wc['st']))
        st = torch.from_numpy(w['st'][w['val'][:5000]]).to(DEVICE)
        exact = bool(torch.equal(gather(data.r_t, st, L), data.mirror(st, L, torch.ones(len(st), L + 1, device=DEVICE))))
        g1, g2 = torch.Generator(), torch.Generator()
        g1.manual_seed(1)
        g2.manual_seed(1)
        signs = bool(torch.equal(block_signs(5000, L, 4, g1, 'cpu'), block_signs_prev(5000, L, 4, g2, 'cpu')[:, 1:]))
        print(f"   {'✅' if same and exact and signs else '❌'} {PRICE_NAMES[price]} L={L}: окна те же, что у close — "
              f"{same} | зеркало с одними +1 = реальное окно — {exact} | знаки баров те же, что у close — {signs}")
    try:                                       # v4.6: три цены бара одной сетью
        data = load_data('multi')
    except (FileNotFoundError, ValueError) as e:
        print(f"   ⏭️ {PRICE_NAMES['multi']}: {e}")
        return None
    w, wc = data.windows(L), close_data.windows(L)
    same = bool(np.array_equal(w['st'], wc['st']))
    st = torch.from_numpy(w['st'][w['val'][:5000]]).to(DEVICE)
    W = data.gw(st, L)
    exact = bool(torch.equal(W, data.flip_multi(st, L, torch.ones(len(st), L + 1, device=DEVICE), W)))
    close_ok = bool(torch.equal(W[:, 0], gather(close_data.r_t, st, L)))
    print(f"   {'✅' if same and exact and close_ok else '❌'} {PRICE_NAMES['multi']} L={L}: окна те же, что у close — {same} | "
          f"переворот с одними +1 = реальное окно — {exact} | канал 0 = close — {close_ok}")
    return data


def run_job(job, items):
    datas, stores = {}, {}
    t0 = time.time()
    done = []
    for n, (name, over, seed_key) in enumerate(items):
        print(f"\n▶️ [{n + 1}/{len(items)}] {name} {over} seed {seed_key}")
        try:
            tag = make_cfg(name, over, seed_key)['tag']
            old = RUN_DIR + f"smc_{tag}.json"
            if not FORCE and os.path.isfile(old):
                with open(old, encoding='utf-8') as fh:
                    r = json.load(fh)
                if r.get('ver') == SMC_VER:
                    print(f"⏭️ {tag} уже посчитан ({r.get('when')}) — пропуск (FORCE = True — пересчитать)")
                    with orientation((r.get('cfg') or {}).get('orient', True)):     # v6.7: рисунок — в ориентации прогона
                        backfill_extremes(r, datas, stores)
                    done.append(r)
                    continue
            done.append(run_one(name, over, seed_key, datas, stores, job))
        except Exception as e:
            print(f"\n🍆 АЙ, ОШИБКА! {name} {over} {seed_key}: {type(e).__name__}: {e}")
            traceback.print_exc(file=sys.stdout)
        if DEVICE.type == 'cuda':
            torch.cuda.empty_cache()
    print(f"\n👑 ЗАДАНИЕ {job}: {len(done)} из {len(items)} прогонов | {(time.time() - t0) / 60:.0f} мин")
    for r in done:
        print(f"   {r['tag']:<32} VAL AUC {r['val']['auc']:.4f}±{r['val']['auc_se']:.4f} | TUNE "
              f"{r['tune']['auc']:.4f}")


# =====================================================================
# СВОДКА ПО ВСЕМ ПРОГОНАМ
# =====================================================================
def _load_runs():
    rows = []
    for p in sorted(glob.glob(RUN_DIR + 'smc_*.json')):
        try:
            with open(p, encoding='utf-8') as fh:
                r = json.load(fh)
        except Exception as e:
            print(f"⚠️ {os.path.basename(p)} не читается: {e}")
            continue
        if r.get('ver') == SMC_VER:
            rows.append(r)
    return rows


def _scores(tag):
    d = np.load(RUN_DIR + f"smc_{tag}.npz")
    return {k: d[k] for k in ('tune_sp', 'tune_sn', 'val_sp', 'val_sn', 'tune_wp', 'tune_wn',
                              'val_wp', 'val_wn')} | ({'lab': d['probe_lab']} if 'probe_lab' in d.files else {})


def _mean_sd(xs):
    xs = [x for x in xs if x is not None and np.isfinite(x)]
    if not xs:
        return np.nan, np.nan
    return float(np.mean(xs)), (float(np.std(xs, ddof=1)) if len(xs) > 1 else np.nan)


def summary():
    rows = _load_runs()
    if not rows:
        print(f"⚠️ в {RUN_DIR} нет прогонов SMC v{SMC_VER}")
        return None
    by = {}
    for r in rows:
        by.setdefault(r['label'], []).append(r)
    print(f"\n\n{'#' * 78}\n# SMC: СВОДКА | прогонов {len(rows)}, вариантов {len(by)} | {RUN_DIR}\n{'#' * 78}")

    # ---- контроли
    if any(rs[0]['name'].startswith('C0_') for rs in by.values()):
        print("\n🧪 КОНТРОЛИ (VALIDATION)")
    for lab_, rs in sorted(by.items()):
        r0 = rs[0]
        if not r0['name'].startswith('C0_'):
            continue
        m, sd = _mean_sd([r['val']['auc'] for r in rs])
        se = rs[0]['val']['auc_se']
        if r0['name'].startswith('C0_null'):           # v4.5: и «зеркало против зеркала» у средней цены бара
            ok = abs(m - 0.5) <= max(0.005, 3 * se)
            note = f"{'✅' if ok else '❌'} обязан быть 0.5 ± max(0.005, 3·SE)"
        elif r0['name'] == 'C0_iid':
            ok = m >= 0.55
            note = f"{'✅' if ok else '❌'} положительный контроль: обязан быть >= 0.55"
        elif r0['name'] == 'C0_mir':                   # v6.7: контроль зеркального теста — его правило в MODE 'dr_sum'
            note = "контроль зеркального теста (v6.7): рынок симметризован — читать в MODE 'dr_sum'"
        else:
            note = (f"пол перекоса «знак-размер»: {'≈ шум' if abs(m - 0.5) <= 3 * se else 'ВЫШЕ шума'}"
                    f" — справочно, AUC основных моделей читать рядом с ним")
        print(f"   {lab_:<28} AUC {m:.4f} ±SE {se:.4f} (прогонов {len(rs)}) | {note}")

    # ---- основная таблица по L
    Ls = sorted({r['cfg']['L'] for r in rows})
    for L in Ls:
        labs = [l_ for l_, rs in by.items() if rs[0]['cfg']['L'] == L and not rs[0]['name'].startswith('C0_')]
        if not labs:
            continue
        ref_mlp = next((l_ for l_ in labs if l_ == f"B_mlp_L{L}_K{SMC_BASE['K']}"), None)
        ref_frz = next((l_ for l_ in labs if by[l_][0]['name'] == 'B_frozen'
                        and l_ == f"B_frozen_L{L}_K{by[l_][0]['cfg']['K']}"), None)
        sc = {l_: [_scores(r['tag']) for r in by[l_]] for l_ in labs}
        print(f"\n{'=' * 78}\n📊 L={L}: реал против главной нулевой прогона. TUNE — выбор, VALIDATION — "
              f"подтверждение. Числа — среднее по сидам (n).\n   Δ — парная разница AUC на TUNE с MLP / "
              f"словарём, среднее по сидам; ±SE = шум окон (по неделям) + разброс сидов.\n{'=' * 78}")
        print(f"   {'вариант':<48} {'n':>2} {'TUNE AUC':>9} {'VAL AUC':>9} {'±sd сидов':>9} {'±SE':>7} "
              f"{'пары':>7} {'буква':>7} {'Δ MLP':>15} {'Δ словарь':>15} {'сила>=1.25':>11} {'lift в/н':>10} "
              f"{'effK':>6} {'n_eff P':>7} {'Δгладк':>7} {'ARI сид':>8} {'эпох':>5} {'с/эп':>5} {'Pine':>7}")
        order = sorted(labs, key=lambda l_: -np.mean([r['tune']['auc'] for r in by[l_]]))
        for l_ in order:
            rs = by[l_]
            t_m, _ = _mean_sd([r['tune']['auc'] for r in rs])
            v_m, v_sd = _mean_sd([r['val']['auc'] for r in rs])
            w_m, _ = _mean_sd([r['val'].get('win') for r in rs])
            let_m, _ = _mean_sd([(r.get('letter') or {}).get('val', {}).get('auc') for r in rs])
            ep_m, _ = _mean_sd([r['best_ep'] + 1 if r['best_ep'] >= 0 else None for r in rs])
            sm_m, _ = _mean_sd([(r['smooth']['val'] - r['val']['auc']) if r.get('smooth') else None for r in rs])
            ne_m, _ = _mean_sd([(r.get('sparsity') or {}).get('neff_med') for r in rs])

            def dlt(ref):
                if ref is None or ref == l_:
                    return "—"
                d_, se_, n_ = _seed_delta(by, sc, l_, ref)
                return "несравн." if n_ == 0 else f"{d_:+.4f}±{se_:.4f}"
            cov_m, _ = _mean_sd([next(c for c in r['cov']['lift'] if abs(c['thr'] - 1.25) < 1e-9)['both']
                                 for r in rs])
            c125 = next(c for c in rs[0]['cov']['lift'] if abs(c['thr'] - 1.25) < 1e-9)
            pr = rs[0]['protos'] or {}
            ari_s = np.nan
            labs_ = [s['lab'] for s in sc[l_] if 'lab' in s]
            if len(labs_) >= 2:
                ari_s = np.mean([adjusted_rand_score(labs_[i], labs_[j]) for i in range(len(labs_))
                                 for j in range(i + 1, len(labs_))])
            print(f"   {l_:<48} {len(rs):>2} {t_m:>9.4f} {v_m:>9.4f} {_f(v_sd, '.4f', width=9)} "
                  f"{rs[0]['val']['auc_se']:>7.4f} {_f(w_m, '.4f', width=7)} {_f(let_m, '.4f', width=7)} "
                  f"{dlt(ref_mlp):>15} {dlt(ref_frz):>15} {100 * cov_m:>10.1f}% "
                  f"{_f(c125['up'][2], '.2f', width=4)}/{_f(c125['down'][2], '.2f'):<4} {_f(pr.get('effK'), '.1f', width=6)} "
                  f"{_f(ne_m, '.1f', width=7)} {_f(sm_m, '+.4f', width=7)} {_f(ari_s, '.3f', width=8)} "
                  f"{_f(ep_m, '.0f', width=5)} "
                  f"{rs[0]['sec_ep']:>5.1f} {rs[0]['pine']:>7}")
        # другие нулевые
        nulls = [n_ for n_ in EVAL_NULLS if any(n_ in by[l_][0]['cross'] for l_ in labs)]
        nulls += sorted({k for l_ in labs for k in by[l_][0]['cross']} - set(nulls))
        if nulls:
            print("\n   AUC против других нулевых (VALIDATION, среднее по сидам):")
            print(f"   {'вариант':<48} " + " ".join(f"{n_.replace('bank:', '').replace('w2016', '|2k'):>11}"
                                               for n_ in nulls))
            for l_ in order:
                vals = [_mean_sd([r['cross'].get(n_, {}).get('auc') for r in by[l_]])[0] for n_ in nulls]
                print(f"   {l_:<48} " + " ".join(_f(v_, '.4f', width=11) for v_ in vals))
        # по годам
        parts = []
        for l_ in order:
            for y_ in (by[l_][0].get('years') or []):
                if y_['part'] not in parts:
                    parts.append(y_['part'])
        if parts:
            print("\n   AUC по годам (среднее по сидам; FIT-годы — в выборке обучения, TUNE и VAL — вне):")
            print(f"   {'вариант':<48} " + " ".join(f"{p_:>7}" for p_ in parts))
            for l_ in order:
                vals = [_mean_sd([next((y_['auc'] for y_ in (r.get('years') or []) if y_['part'] == p_), None)
                                  for r in by[l_]])[0] for p_ in parts]
                print(f"   {l_:<48} " + " ".join(_f(v_, '.4f', width=7) for v_ in vals))
    print("\n   Выбор варианта — по TUNE (VALIDATION только подтверждает). «буква» — AUC модели, сжатой "
          "до номера ближайшей формы (VALIDATION). «сила>=1.25» — доля реальных окон VALIDATION с "
          "оценкой lift >= 1.25 или <= 0.80; «lift в/н» — фактический lift этих отметок вверх/вниз "
          "(сид a). «Δгладк» — изменение VAL AUC, если сгладить прототипы окном 5 (голова та же); «ARI сид» — "
          "сходство разметки между сидами; «n_eff P» — сколько форм реально участвует в P окна "
          "(exp энтропии, медиана); «эпох» — "
          "номер лучшей эпохи.")
    for L in Ls:
        nt_verdict(by, L)                      # v6.0: модели без времени (признаки истории в барах)
        rx_verdict(by, L)                      # v5.7: точечные добавки поверх RG_den, F3 + диапазон
        rg_verdict(by, L)                      # v5.6: диапазон бара на F1
        tok_verdict(by, L)                     # v5.5: признаки токена на F1
        pyr_verdict(by, L)                     # v5.4: пирамида доходностей на F1
        stage1_verdict(by, L)
        indicator_verdict(by, L)
        stop_verdict(by, L, ref='C3_side')
        final_verdict(by, L)
        for base in ('C3_ctxp', 'C3_ctx', 'C3_side'):
            price_verdict(by, L, base)
        sweep_verdict(by, L, 'C3_ctx', W9_CTX, 'ПРОШЛОЕ ПЕРЕД ОКНОМ И ЁМКОСТЬ (волна 9)')
        sweep_verdict(by, L, 'C3_side_ctx', {'C3_ctx': {'side': 'v7tc'}}, 'НОРМА ВОЛЫ ЗА 7 СУТОК ВМЕСТО 30 (с прошлым)')
        sweep_verdict(by, L, 'C3_stream_side', W9_PINE_C, 'ПОТОКОВАЯ CNN (Pine) С ПРОШЛЫМ ПЕРЕД ОКНОМ')
        sweep_verdict(by, L, 'S_side', W9_PINE_S, 'ШЕЙПЛЕТЫ (Pine) С ПРОШЛЫМ ПЕРЕД ОКНОМ')
        sweep_verdict(by, L, 'C3_ctxp', W9_SPEED, 'КРУПНЫЙ БАТЧ (скорость для мульти-ассетов)')
        sweep_verdict(by, L, 'C3_side', W8_SIDE, 'БОКОВЫЕ ВХОДЫ: НОРМЫ ВОЛЫ И ПРОШЛОЕ ПЕРЕД ОКНОМ (волна 8)')
        if _lab('C3_side_ctx', L) in by:
            print("   C3_side_ctx смотрит и на ход рынка ДО окна (не только на форму окна): в кандидаты индикатора по "
                  "правилу одной SE не входит, при «помогает» его принятие — отдельное решение")
        sweep_verdict(by, L, 'C3_stream', W8_STREAM, 'ПОТОКОВАЯ CNN (точный счёт в Pine) + БОКОВЫЕ ВХОДЫ')
        sweep_verdict(by, L, 'S_shp16_k32', W8_SHP, 'ШЕЙПЛЕТЫ (дёшево в Pine) + БОКОВЫЕ ВХОДЫ')
        sweep_verdict(by, L, 'C_cdrop3', W7_SIDE, 'БОКОВЫЕ ВХОДЫ (ВОЛА К НОРМЕ, ВРЕМЯ; волна 7)')
        refit_verdict(by, L)
        sweep_verdict(by, L, 'C_cdrop3', C3_SWEEP, 'СВИП ЧЕМПИОНА C_cdrop3 (раунд 6)')
        holdout_verdict(by, L)
        shapelet_verdict(by, L)
        sweep_verdict(by, L, 'S_shp16', W7_SHP, 'ШЕЙПЛЕТЫ: ЧИСЛО, ДЛИНА, DROPOUT')
        bank_verdict(by, L)
        sweep_verdict(by, L, 'C_dil', CNN_SWEEP, 'СВИП СВЁРТОЧНОЙ СЕТИ (раунд 5)')
        sweep_verdict(by, L, 'M_steps', MLP_SWEEP, 'СВИП MLP НА ШАГАХ (раунд 5)')
        sparse_verdict(by, L)
        for nm in ('A2_noclu', 'A5_cos'):
            k_verdict(by, nm, L)
        init_verdict(by, L)
        null_verdict(by, L)
        diag_verdict(by, L)
    window_verdict(by)
    pair_verdict(by)
    return by


def _seed_delta(by, sc, la, lb, part='tune'):
    """Средняя по сидам парная разница AUC (la − lb) на одних окнах. Сиды спариваются по ключу;
       если у lb один прогон (словарь), он общий для всех сидов la. SE = sqrt(средний квадрат SE
       окон + разброс по сидам / n): окна у сидов одни, их шум усреднением не гасится."""
    ra, rb = by[la], by[lb]
    if ra[0]['spec'] != rb[0]['spec']:
        return np.nan, np.nan, 0
    # v4.5: модели на разных ценах бара сравнимы парно, только если окна те же (тогда и суррогаты — те же
    # перевёрнутые бары); у прогонов до v4.5 цена — close
    pa, pb = (r_[0].get('data', {}).get('price', 'close') for r_ in (ra, rb))
    if pa != pb and not all(r_[0].get('data', {}).get('same_windows', r_[0].get('data', {}).get('price', 'close') == 'close')
                            for r_ in (ra, rb)):
        return np.nan, np.nan, 0
    mb = {r['seed_key']: s for r, s in zip(rb, sc[lb])}
    one = next(iter(mb.values())) if len(mb) == 1 else None
    ds, ses = [], []
    for r, s in zip(ra, sc[la]):
        t = mb.get(r['seed_key'], one)
        if t is None or len(s[f'{part}_sp']) != len(t[f'{part}_sp']):
            continue
        d_, se_ = auc_diff(s[f'{part}_sp'], s[f'{part}_sn'], t[f'{part}_sp'], t[f'{part}_sn'],
                           s[f'{part}_wp'], s[f'{part}_wn'])
        ds.append(d_)
        ses.append(se_)
    if not ds:
        return np.nan, np.nan, 0
    var_seed = np.var(ds, ddof=1) / len(ds) if len(ds) > 1 else 0.0
    return float(np.mean(ds)), float(np.sqrt(np.mean(np.square(ses)) + var_seed)), len(ds)


# порядок простоты для правила одной сигмы: меньше движущихся частей — раньше
SIMPLICITY = ['A3_frozen', 'A8_lin', 'A6_ponly', 'A12_Tfix', 'A1_base', 'A11_amp', 'A7_noreg', 'A4_hiclu',
              'A2_noclu', 'A5_cos', 'A0_concept']

def stage1_verdict(by, L):
    """Правила этапа 1, раунд 2 (записаны в STATUS до прогона), окна TUNE, K = SMC_BASE['K']:
       ворота эмбеддинга — у большинства сидов пустых форм 0 и effK >= K/2;
       победитель — самый простой вариант, чья средняя по сидам парная разница AUC с лучшим >= −1 SE;
       цена прототипов: Δ(победитель − MLP) >= −2 SE; победа над словарём: Δ(− словарь) >= +2 SE;
       справочно: Δ(победитель − два числа B_simple) и профиль AUC по нулевым sflip 1…32."""
    K0 = SMC_BASE['K']
    pick = {}
    for lab_, rs in by.items():
        r = rs[0]
        if r['cfg']['L'] != L or lab_ != f"{r['name']}_L{L}_K{r['cfg']['K']}":
            continue
        if r['name'] in SIMPLICITY and r['cfg']['K'] == K0:
            pick[r['name']] = lab_
        elif r['name'] in ('B_mlp', 'B_frozen', 'B_simple'):
            pick[r['name']] = lab_
    cands = [n for n in SIMPLICITY if n in pick]
    if len(cands) < 5:                        # вердикт этапа 1 — только когда есть сам этап 1
        return
    print(f"\n{'=' * 78}\n🧾 ВЕРДИКТ ЭТАПА 1, L={L} (K={K0}; среднее по сидам; выбор по TUNE)\n{'=' * 78}")
    sc = {pick[n]: [_scores(r['tag']) for r in by[pick[n]]] for n in pick}

    def t_mean(n):
        return float(np.mean([r['tune']['auc'] for r in by[pick[n]]]))

    ok = {}
    for n in cands:
        runs = by[pick[n]]
        prs = [r['protos'] or {} for r in runs]
        passes = [p.get('dead', 1) == 0 and p.get('effK', 0) >= K0 / 2 for p in prs]
        ok[n] = 2 * sum(passes) >= len(passes)
        print(f"   {'✅' if ok[n] else '❌'} {n:<12} TUNE AUC {t_mean(n):.4f} (сидов {len(runs)}) | пустых "
              f"{[p.get('dead') for p in prs]} effK {[round(p.get('effK', 0), 1) for p in prs]}")
    elig = [n for n in cands if ok[n]]
    if not elig:
        print("   ❌ ни один вариант не прошёл ворота эмбеддинга — разбирать по таблицам форм")
        return
    best = max(elig, key=t_mean)
    band = []
    for n in elig:
        d_, se_, k_ = (0.0, 0.0, 0) if n == best else _seed_delta(by, sc, pick[n], pick[best])
        inside = d_ >= -se_
        if inside:
            band.append(n)
        print(f"   {n:<12} Δ к лучшему ({best}) {d_:+.4f} ± {se_:.4f}{'  ← в полосе 1 SE' if inside else ''}")
    win = next(n for n in SIMPLICITY if n in band)
    print(f"   🏆 победитель: {win} (самый простой в полосе 1 SE от {best})")
    for ref, rule, sign in (('B_mlp', 'цена прототипов (Δ >= −2 SE — прототипы бесплатны)', -1),
                            ('B_frozen', 'против словаря по клеткам (Δ >= +2 SE — SMC лучше словаря)', +1),
                            ('B_simple', 'справочно: сверх двух чисел (амплитуда, ER)', 0)):
        if ref not in pick:
            print(f"   · {ref}: нет прогона")
            continue
        d_, se_, k_ = _seed_delta(by, sc, pick[win], pick[ref])
        if sign == 0:
            print(f"   · {rule}: Δ {d_:+.4f} ± {se_:.4f} (сидов {k_})")
            continue
        passed = d_ >= -2 * se_ if sign < 0 else d_ >= 2 * se_
        print(f"   {'✅' if passed else '❌'} {rule}: Δ {d_:+.4f} ± {se_:.4f} (сидов {k_})")

    # профиль по масштабу: где живёт разница с MLP и с двумя числами
    prof = [n_ for n_ in ('sflip1', 'sflip4', 'sflip8', 'sflip16', 'sflip32')]
    rows_ = [(win, pick[win])] + [(n, pick[n]) for n in ('B_mlp', 'B_simple', 'B_frozen') if n in pick]
    print(f"   профиль AUC по нулевым (VALIDATION, среднее по сидам): {'':<6}" + " ".join(f"{n_:>8}" for n_ in prof))
    for n, l_ in rows_:
        vals = [_mean_sd([r['cross'].get(n_, {}).get('auc') for r in by[l_]])[0] for n_ in prof]
        print(f"      {n:<52}" + " ".join(_f(v_, '.4f', width=8) for v_ in vals))

    runs = by[pick[win]]
    v_m, v_sd = _mean_sd([r['val']['auc'] for r in runs])
    cov_m, _ = _mean_sd([next(c for c in r['cov']['lift'] if abs(c['thr'] - 1.25) < 1e-9)['both'] for r in runs])
    let_m, _ = _mean_sd([(r.get('letter') or {}).get('val', {}).get('auc') for r in runs])
    c = next(x for x in runs[0]['cov']['lift'] if abs(x['thr'] - 1.25) < 1e-9)
    line = (f"   VALIDATION победителя: AUC {v_m:.4f} (sd сидов {_f(v_sd, '.4f')}, SE окон "
            f"{runs[0]['val']['auc_se']:.4f}), жёсткая буква {_f(let_m, '.4f')}, сила >= 1.25 покрывает "
            f"{100 * cov_m:.1f}% окон (сид a: lift вверх {_f(c['up'][2], '.2f')}, вниз {_f(c['down'][2], '.2f')})")
    print(line)


def _sc_for(by, labels):
    return {l_: [_scores(r['tag']) for r in by[l_]] for l_ in labels if l_ in by}


def _mean_of(by, lab, get):
    return _mean_sd([get(r) for r in by[lab]])[0]


def _cov125(r):
    return next(c for c in r['cov']['lift'] if abs(c['thr'] - 1.25) < 1e-9)['both']


def k_verdict(by, name, L):
    """Этап 2 (правило записано до прогона): K* — наименьшее K, чья средняя по сидам парная разница
       AUC на TUNE с лучшим K не ниже −1 SE; справочно — буква, гладкие формы, разница с MLP."""
    rows = {}
    for lab_, rs in by.items():
        r = rs[0]
        if r['name'] == name and r['cfg']['L'] == L and lab_ == f"{name}_L{L}_K{r['cfg']['K']}":
            rows[r['cfg']['K']] = lab_
    if len(rows) < 2:
        return
    Ks = sorted(rows)
    mlp = f"B_mlp_L{L}_K{SMC_BASE['K']}"
    sc = _sc_for(by, list(rows.values()) + [mlp])
    t_mean = {K: _mean_of(by, rows[K], lambda r: r['tune']['auc']) for K in Ks}
    best = max(Ks, key=t_mean.get)
    print(f"\n{'=' * 78}\n🧾 ЭТАП 2 — ЧИСЛО ФОРМ K: {name}, L={L} (среднее по сидам; выбор по TUNE)\n{'=' * 78}")
    print(f"   {'K':>4} {'n':>2} {'TUNE AUC':>9} {'VAL AUC':>9} {'буква':>7} {'гладкие':>8} {'сила>=1.25':>11} "
          f"{'effK':>6} {'T':>7} {'Pine':>7} {'Δ к лучшему K':>17}")
    band = []
    for K in Ks:
        lab = rows[K]
        d_, se_, _ = (0.0, 0.0, 0) if K == best else _seed_delta(by, sc, lab, rows[best])
        inside = d_ >= -se_
        if inside:
            band.append(K)
        T_m = _mean_of(by, lab, lambda r: (r['hist'][r['best_ep']].get('T') if r['hist'] and r['best_ep'] >= 0
                                          else None))
        print(f"   {K:>4} {len(by[lab]):>2} {t_mean[K]:>9.4f} {_mean_of(by, lab, lambda r: r['val']['auc']):>9.4f} "
              f"{_f(_mean_of(by, lab, lambda r: (r.get('letter') or {}).get('val', {}).get('auc')), '.4f', width=7)} "
              f"{_f(_mean_of(by, lab, lambda r: (r.get('smooth') or {}).get('val')), '.4f', width=8)} "
              f"{100 * _mean_of(by, lab, _cov125):>10.1f}% "
              f"{_f(_mean_of(by, lab, lambda r: (r['protos'] or {}).get('effK')), '.1f', width=6)} "
              f"{_f(T_m, '.3f', width=7)} {by[lab][0]['pine']:>7} "
              f"{d_:>+9.4f}±{se_:.4f}{'  ← в полосе 1 SE' if inside else ''}")
    k_star = min(band)
    print(f"   🏆 K* = {k_star} (наименьшее K в полосе 1 SE от лучшего K = {best})")
    if mlp in by and by[mlp][0]['spec'] == by[rows[k_star]][0]['spec']:
        d_, se_, n_ = _seed_delta(by, sc, rows[k_star], mlp)
        print(f"   · цена прототипов при K*: Δ(− MLP) {d_:+.4f} ± {se_:.4f} (сидов {n_})")


def _best_T(r):
    return r['hist'][r['best_ep']].get('T') if r.get('hist') and r['best_ep'] >= 0 else None


def sparse_verdict(by, L):
    """Разреженный токен против плотного (правило записано до прогона): чемпион — самый разреженный
       вариант (top-1 < top-2 < top-4 < плотное A13 < плотное A2; при равной разреженности — меньшее K),
       чья средняя по сидам парная разница AUC на TUNE с лучшим из всех вариантов (A13 и A2, K 32 и 128)
       не ниже −1 SE. Разреженный чемпион = «плотное не выигрывает сверх шума»."""
    combos = {}
    for lab_, rs in by.items():
        r = rs[0]
        if r['cfg']['L'] != L or r['name'] not in ('A13_amp', 'A2_noclu'):
            continue
        k, K = int(r['cfg'].get('p_topk') or 0), r['cfg']['K']
        if lab_ == f"{r['name']}_L{L}_K{K}" + (f"_p_topk{k}" if k else ""):
            combos[(r['name'], K, k)] = lab_
    if len(combos) < 3 or not any(c[0] == 'A13_amp' for c in combos):
        return

    def rank(c):
        n_, K_, k_ = c
        return ((k_ if k_ else 100) + (0 if n_ == 'A13_amp' else 1000), K_)
    sc = _sc_for(by, combos.values())
    t_mean = {c: _mean_of(by, lab, lambda r: r['tune']['auc']) for c, lab in combos.items()}
    best = max(combos, key=t_mean.get)
    print(f"\n{'=' * 78}\n🧾 РАЗРЕЖЕННЫЙ ТОКЕН ПРОТИВ ПЛОТНОГО, L={L} (среднее по сидам; выбор по TUNE)\n{'=' * 78}")
    print(f"   {'вариант':<10} {'K':>4} {'P':>8} {'n':>2} {'TUNE AUC':>9} {'VAL AUC':>9} {'n_eff P':>8} {'буква':>7} "
          f"{'T':>7} {'Δ к лучшему':>17}")
    band = []
    for c in sorted(combos, key=rank):
        lab = combos[c]
        d_, se_, _ = (0.0, 0.0, 0) if c == best else _seed_delta(by, sc, lab, combos[best])
        inside = d_ >= -se_
        if inside:
            band.append(c)
        print(f"   {c[0]:<10} {c[1]:>4} {('top-' + str(c[2])) if c[2] else 'плотное':>8} {len(by[lab]):>2} "
              f"{t_mean[c]:>9.4f} {_mean_of(by, lab, lambda r: r['val']['auc']):>9.4f} "
              f"{_f(_mean_of(by, lab, lambda r: (r.get('sparsity') or {}).get('neff_med')), '.1f', width=8)} "
              f"{_f(_mean_of(by, lab, lambda r: (r.get('letter') or {}).get('val', {}).get('auc')), '.4f', width=7)} "
              f"{_f(_mean_of(by, lab, _best_T), '.3f', width=7)} {d_:>+9.4f}±{se_:.4f}"
              f"{'  ← в полосе 1 SE' if inside else ''}")
    win = min(band, key=rank)
    kind = f"разреженный (top-{win[2]})" if win[2] else "ПЛОТНЫЙ"
    print(f"   🏆 чемпион по правилу: {win[0]} K={win[1]} P {('top-' + str(win[2])) if win[2] else 'плотное'} — "
          f"{kind}; лучший по TUNE: {best[0]} K={best[1]} {('top-' + str(best[2])) if best[2] else 'плотное'}")
    for K in sorted({c[1] for c in combos}):
        dense = combos.get(('A13_amp', K, 0))
        if dense is None:
            continue
        for k in sorted({c[2] for c in combos if c[1] == K and c[2]}):
            lab = combos.get(('A13_amp', K, k))
            if lab:
                d_, se_, n_ = _seed_delta(by, sc, lab, dense)
                print(f"   · K={K}: top-{k} − плотное (A13) {d_:+.4f} ± {se_:.4f} (сидов {n_})")
        a2 = combos.get(('A2_noclu', K, 0))
        if a2:
            d_, se_, n_ = _seed_delta(by, sc, dense, a2)
            print(f"   · K={K}: амплитуда в голову (A13 плотное − A2 плотное) {d_:+.4f} ± {se_:.4f} (сидов {n_})")
    a5d, a5s = f"A5_cos_L{L}_K128", f"A5_cos_L{L}_K128_p_topk4"
    if a5d in by and a5s in by:
        sc5 = _sc_for(by, [a5d, a5s])
        d_, se_, n_ = _seed_delta(by, sc5, a5s, a5d)
        print(f"   · A5_cos K=128: top-4 − плотное {d_:+.4f} ± {se_:.4f} (сидов {n_}); n_eff плотного "
              f"{_f(_mean_of(by, a5d, lambda r: (r.get('sparsity') or {}).get('neff_med')), '.1f')}")


def _ens_auc(scs, part):
    """AUC ансамбля сидов: средний logit по сидам на одних и тех же окнах (сиды с другим набором
       окон — например, посчитанные при другом max_eval — не участвуют)."""
    n0 = len(scs[0][f'{part}_sp'])
    scs = [s_ for s_ in scs if len(s_[f'{part}_sp']) == n0]
    sp = np.mean([s_[f'{part}_sp'] for s_ in scs], axis=0)
    sn = np.mean([s_[f'{part}_sn'] for s_ in scs], axis=0)
    return auc_se(sp, sn, scs[0][f'{part}_wp'], scs[0][f'{part}_wn'])


def indicator_verdict(by, L):
    """Модель индикатора (правило записано до прогона): среди всех моделей против sflip 4 на всём FIT
       чемпион — самая дешёвая в Pine из тех, чья средняя по сидам парная разница AUC на TUNE с лучшей
       не ниже −1 SE. Рядом — AUC ансамбля сидов (средний logit), покрытие силой >= 1.25 и lift."""
    cands = _ind_cands(by, L)
    if len(cands) < 3 or not any(by[l_][0]['cfg']['arch'] in ('mlp', 'cnn') for l_ in cands):
        return
    sc = _sc_for(by, cands)
    t_mean = {l_: _mean_of(by, l_, lambda r: r['tune']['auc']) for l_ in cands}
    best = max(cands, key=t_mean.get)
    order = sorted(cands, key=lambda l_: -t_mean[l_])
    dl = {l_: ((0.0, 0.0, 0) if l_ == best else _seed_delta(by, sc, l_, best)) for l_ in cands}
    band = [l_ for l_ in cands if dl[l_][0] >= -dl[l_][1]]
    show = order[:25] + [l_ for l_ in order[25:] if l_ in band]
    print(f"\n{'=' * 78}\n🧾 МОДЕЛЬ ИНДИКАТОРА, L={L}: реал против sflip4, весь FIT (среднее по сидам; выбор по TUNE)\n"
          f"{'=' * 78}")
    print(f"   {'вариант':<48} {'n':>2} {'TUNE AUC':>9} {'VAL AUC':>9} {'ансамбль VAL':>13} {'сила>=1.25':>11} "
          f"{'lift в/н':>10} {'Pine':>8} {'Δ к лучшему':>17}")
    for l_ in show:
        d_, se_, _ = dl[l_]
        ens = _ens_auc(sc[l_], 'val')[0] if len(sc[l_]) >= 2 else np.nan
        c125 = next(c for c in by[l_][0]['cov']['lift'] if abs(c['thr'] - 1.25) < 1e-9)
        print(f"   {l_:<48} {len(by[l_]):>2} {t_mean[l_]:>9.4f} {_mean_of(by, l_, lambda r: r['val']['auc']):>9.4f} "
              f"{_f(ens, '.4f', width=13)} {100 * _mean_of(by, l_, _cov125):>10.1f}% "
              f"{_f(c125['up'][2], '.2f', width=4)}/{_f(c125['down'][2], '.2f'):<4} {by[l_][0]['pine']:>8} "
              f"{d_:>+9.4f}±{se_:.4f}{'  ← в полосе 1 SE' if l_ in band else ''}")
    if len(order) > len(show):
        print(f"   … ещё {len(order) - len(show)} вариантов ниже (вне полосы)")
    win = min(band, key=lambda l_: (by[l_][0]['pine'], -t_mean[l_]))   # при равной цене — выше TUNE
    print(f"   🏆 модель индикатора по правилу: {win} (самая дешёвая в Pine в полосе 1 SE от {best})")
    if len(sc[win]) >= 2:
        et, ev = _ens_auc(sc[win], 'tune'), _ens_auc(sc[win], 'val')
        print(f"   · ансамбль сидов победителя: TUNE {et[0]:.4f} ± {et[1]:.4f}, VAL {ev[0]:.4f} ± {ev[1]:.4f} "
              f"(один сид в среднем: VAL {_mean_of(by, win, lambda r: r['val']['auc']):.4f})")
    # v4.4: ансамбль трёх лучших разных вариантов (все их сиды, средний logit) — для сайта, не для Pine
    top3 = [l_ for l_ in order if len(sc[l_]) >= 1][:3]
    pool = [s_ for l_ in top3 for s_ in sc[l_]]
    if len(top3) == 3 and len({len(s_['val_sp']) for s_ in pool}) == 1:
        et, ev = _ens_auc(pool, 'tune'), _ens_auc(pool, 'val')
        print(f"   · ансамбль трёх лучших вариантов ({', '.join(l_.split('_L')[0] for l_ in top3)}; {len(pool)} моделей): "
              f"TUNE {et[0]:.4f} ± {et[1]:.4f}, VAL {ev[0]:.4f} ± {ev[1]:.4f}")
    # v4.4: держатся ли обещания индикатора во времени — AUC и фактический lift отметок по полугодиям
    halves = [y_['part'] for y_ in (by[win][0].get('years') or []) if len(y_['part']) == 5]
    if halves:
        def hv(p_, key):
            return _mean_of(by, win, lambda r: next((y_.get(key) for y_ in (r.get('years') or [])
                                                     if y_['part'] == p_), None))
        cells = []
        for p_ in halves:
            cell = f"{p_} AUC {_f(hv(p_, 'auc'), '.3f')}"
            if np.isfinite(hv(p_, 'cov')):
                cell += f", lift >= 1.25 / <= 0.8: {_f(hv(p_, 'lift_up'), '.2f')} / {_f(hv(p_, 'lift_dn'), '.2f')}"
            cells.append(cell)
        print("   · победитель по полугодиям (вне выборки): " + " | ".join(cells))


def init_verdict(by, L):
    """Справочно: откуда рождаются формы — старт из k-means / шума / случайного блуждания / случайных
       реальных окон (A2_noclu K=128, переезд пустых форм выключен у всех)."""
    base = f"A2_noclu_L{L}_K128"
    labs = {ini: f"{base}{'_init' + ini if ini != 'kmeans' else ''}_reinit_deadFalse"
            for ini in ('kmeans', 'noise', 'randwalk', 'sample')}
    labs = {k_: v_ for k_, v_ in labs.items() if v_ in by}
    if len(labs) < 2 or 'kmeans' not in labs:
        return
    sc = _sc_for(by, labs.values())
    print(f"\n{'=' * 78}\n🧾 РОЖДЕНИЕ ФОРМ, L={L}: A2_noclu K=128, старт форм (без переезда пустых форм)\n{'=' * 78}")
    print(f"   {'старт':<10} {'n':>2} {'TUNE AUC':>9} {'VAL AUC':>9} {'буква':>7} {'Δгладк':>7} {'effK':>6} {'n_eff P':>8} "
          f"{'эпох':>5} {'Δ к k-means':>17}")
    for ini, lab in labs.items():
        d_, se_, _ = (0.0, 0.0, 0) if ini == 'kmeans' else _seed_delta(by, sc, lab, labs['kmeans'])
        print(f"   {ini:<10} {len(by[lab]):>2} {_mean_of(by, lab, lambda r: r['tune']['auc']):>9.4f} "
              f"{_mean_of(by, lab, lambda r: r['val']['auc']):>9.4f} "
              f"{_f(_mean_of(by, lab, lambda r: (r.get('letter') or {}).get('val', {}).get('auc')), '.4f', width=7)} "
              f"{_f(_mean_of(by, lab, lambda r: (r['smooth']['val'] - r['val']['auc']) if r.get('smooth') else None), '+.4f', width=7)} "
              f"{_f(_mean_of(by, lab, lambda r: (r['protos'] or {}).get('effK')), '.1f', width=6)} "
              f"{_f(_mean_of(by, lab, lambda r: (r.get('sparsity') or {}).get('neff_med')), '.1f', width=8)} "
              f"{_f(_mean_of(by, lab, lambda r: r['best_ep'] + 1), '.0f', width=5)} {d_:>+9.4f}±{se_:.4f}")
    print("   Картинки рождения форм: папка прогона, evolution.png (строка «старт» — исходные формы).")


def null_verdict(by, L):
    """Этап 3 (правило записано до прогона): при обучении и проверке против sflip b прототипы
       «бесплатны на масштабе b», если Δ(A2 − MLP) на TUNE >= −2 SE; рядом — те же модели,
       обученные против sflip 4, на той же нулевой (VALIDATION)."""
    base_a, base_m = f"A2_noclu_L{L}_K{SMC_BASE['K']}", f"B_mlp_L{L}_K{SMC_BASE['K']}"
    lines = []
    for nl in ('sflip16', 'sflip32'):
        la, lm = f"{base_a}_null{nl}", f"{base_m}_null{nl}"
        if la not in by or lm not in by:
            continue
        sc = _sc_for(by, [la, lm])
        d_, se_, n_ = _seed_delta(by, sc, la, lm)
        va, vm = _mean_of(by, la, lambda r: r['val']['auc']), _mean_of(by, lm, lambda r: r['val']['auc'])
        va4 = _mean_of(by, base_a, lambda r: r['cross'].get(nl, {}).get('auc')) if base_a in by else np.nan
        vm4 = _mean_of(by, base_m, lambda r: r['cross'].get(nl, {}).get('auc')) if base_m in by else np.nan
        ok = d_ >= -2 * se_
        lines.append(f"   {'✅' if ok else '❌'} {nl}: VAL AUC A2 {va:.4f} / MLP {vm:.4f} (обучены против sflip4: "
                     f"{_f(va4, '.4f')} / {_f(vm4, '.4f')}) | Δ(A2 − MLP) на TUNE {d_:+.4f} ± {se_:.4f} "
                     f"(сидов {n_}) — прототипы {'бесплатны' if ok else 'НЕ бесплатны'} на этом масштабе")
    if lines:
        print(f"\n{'=' * 78}\n🧾 ЭТАП 3 — НА ЧЁМ УЧИТЬ, L={L}: A2_noclu и MLP, обученные против крупных блоков\n{'=' * 78}")
        print("\n".join(lines))


def diag_verdict(by, L):
    """Справочно (правила записаны до прогона): лестница масштабов против форм и MLP; свежая история."""
    K0 = SMC_BASE['K']
    A2, MLP, LAD, SIM = (f"A2_noclu_L{L}_K{K0}", f"B_mlp_L{L}_K{K0}", f"B_ladder_L{L}_K{K0}",
                         f"B_simple_L{L}_K{K0}")
    fr_labs = [f"{b_}_fit_from{fr}" for fr in FIT_RECENT for b_ in (A2, MLP)]
    sc = _sc_for(by, [A2, MLP, LAD, SIM] + fr_labs)
    out = []
    for la, lb, note in ((LAD, SIM, 'лестница сверх двух чисел'), (A2, LAD, 'формы сверх лестницы'),
                         (MLP, LAD, 'MLP сверх лестницы')):
        if la in sc and lb in sc:
            d_, se_, n_ = _seed_delta(by, sc, la, lb)
            out.append(f"   · {note}: Δ({la} − {lb}) {d_:+.4f} ± {se_:.4f} (сидов {n_})")
    for fr in FIT_RECENT:
        for b_ in (A2, MLP):
            lab = f"{b_}_fit_from{fr}"
            if lab in sc and b_ in sc:
                d_, se_, n_ = _seed_delta(by, sc, lab, b_)
                out.append(f"   {'✅' if d_ >= 2 * se_ else '·'} FIT с {fr}: Δ({lab} − весь FIT) {d_:+.4f} ± {se_:.4f} "
                           f"(сидов {n_}); VAL {_mean_of(by, lab, lambda r: r['val']['auc']):.4f} против "
                           f"{_mean_of(by, b_, lambda r: r['val']['auc']):.4f}")
    if out:
        print(f"\n{'=' * 78}\n🧾 ДИАГНОСТИКА, L={L}: что видят формы сверх многомасштабного отката; свежая история\n{'=' * 78}")
        print("\n".join(out))


def _fit_gap(r):
    """AUC на пробе FIT минус AUC на TUNE на лучшей эпохе: мера запоминания (+ смены рынка)."""
    if not r.get('hist') or r['best_ep'] < 0:
        return None
    h = r['hist'][r['best_ep']]
    return h['fit']['auc'] - h['tune']['auc']


def _lab(name, L):
    """Метка варианта без over: имя, L и K из RUNS (у шейплетов K — число форм)."""
    return f"{name}_L{L}_K{RUNS.get(name, {}).get('K', SMC_BASE['K'])}"


def sweep_verdict(by, L, ref, sweep, title):
    """v4.2 (правило записано до прогона): каждый вариант свипа против эталона — средняя по сидам парная
       разница AUC на TUNE (±SE: шум окон по неделям + разброс сидов). «помогает» — Δ >= +2 SE,
       «вредит» — Δ <= −2 SE, иначе «в шуме». Рядом — VAL, лучшая эпоха, разрыв FIT − TUNE на ней
       (мера запоминания окон) и цена в Pine."""
    ref_lab = _lab(ref, L)
    labs = [_lab(n, L) for n in sweep if _lab(n, L) in by]
    if ref_lab not in by or not labs:
        return
    sc = _sc_for(by, labs + [ref_lab])
    print(f"\n{'=' * 78}\n🧾 {title}, L={L}: один фактор против {ref} (среднее по сидам; выбор по TUNE)\n{'=' * 78}")
    print(f"   {'вариант':<14} {'что меняется':<44} {'n':>2} {'TUNE AUC':>9} {'VAL AUC':>9} {'эпоха':>6} "
          f"{'FIT−TUNE':>9} {'Pine':>8} {'Δ TUNE к эталону':>18}  вывод")

    def row(nm, lab, d_, se_, verdict):
        rs = by[lab]
        what = ", ".join(f"{k}={v}" for k, v in sweep.get(nm, {}).items()) or "эталон"
        print(f"   {nm:<14} {what[:44]:<44} {len(rs):>2} {_mean_of(by, lab, lambda r: r['tune']['auc']):>9.4f} "
              f"{_mean_of(by, lab, lambda r: r['val']['auc']):>9.4f} "
              f"{_f(_mean_of(by, lab, lambda r: r['best_ep'] + 1 if r['best_ep'] >= 0 else None), '.0f', width=6)} "
              f"{_f(_mean_of(by, lab, _fit_gap), '+.4f', width=9)} {rs[0]['pine']:>8} "
              + (f"{d_:>+10.4f}±{se_:.4f}  {verdict}" if verdict else f"{'—':>18}"))
    row(ref, ref_lab, 0.0, 0.0, None)
    res = []
    for lab in labs:
        d_, se_, n_ = _seed_delta(by, sc, lab, ref_lab)
        res.append((d_, se_, n_, lab))
    for d_, se_, n_, lab in sorted(res, key=lambda x: -x[0] if np.isfinite(x[0]) else 1e9):
        nm = by[lab][0]['name']
        if n_ == 0:
            verdict = "несравнимо"
        elif d_ >= 2 * se_:
            verdict = "✅ помогает"
        elif d_ <= -2 * se_:
            verdict = "❌ вредит"
        else:
            verdict = "· в шуме"
        row(nm, lab, d_, se_, verdict)
    print("   «эпоха» — номер лучшей эпохи (с 1); «FIT−TUNE» — AUC на пробе FIT минус AUC на TUNE на лучшей эпохе "
          "(чем больше, тем сильнее модель запомнила сами окна FIT).")


def pyr_verdict(by, L=64):
    """v5.4, пирамида доходностей на F1, один BTC (правила записаны до прогона). Каждый вариант PYR_SWEEP — против F1
       (PYR_REF) тех же сидов; окна и суррогаты проверки у них те же — разница AUC парная, среднее по сидам, SE = шум окон
       по неделям + разброс сидов: «помогает» — Δ TUNE >= +2 SE, «вредит» — <= −2 SE, иначе «в шуме». Победитель этапа 1:
       среди «помогает» — лучший по TUNE, в полосе 1 SE от него — самый простой (PYR_SIMPLE); VAL подтверждает, если у
       победителя Δ VAL > 0 — тогда этап 2 на пуле (PYR_POOL). Нет победителя — пирамида для F1 закрыта, вход остаётся
       шагами подряд. Справочно: профиль по нулевым (разница средних
       AUC против sflip 1 / 8 / 16 / 32 — где вариант выигрывает или теряет) и по полугодиям."""
    return wave_verdict(by, L, PYR_REF, PYR_SWEEP, PYR_SIMPLE, 'ПИРАМИДА ДОХОДНОСТЕЙ НА F1 (v5.4, один BTC)',
                        "пирамида для F1 закрыта, вход — шаги подряд", "PYR_POOL = ['{win}'], MODE 'pool', JOB 'V1' / 'V2'")


def tok_verdict(by, L=64):
    """v5.5, признаки токена на F1, один BTC (правила записаны до прогона — те же, что у пирамиды v5.4). Каждый вариант
       TOK_SWEEP — против F1 (TOK_REF) тех же сидов, парно: «помогает» — Δ TUNE >= +2 SE, «вредит» — <= −2 SE, иначе «в
       шуме». Победитель этапа 1: среди «помогает» — лучший по TUNE, в полосе 1 SE от него — самый простой (TOK_SIMPLE); VAL
       подтверждает, если у победителя Δ VAL > 0 — тогда этап 2 на пуле (TOK_POOL, задания W1 / W2). Нет победителя —
       признаки окна F1 не нужны."""
    return wave_verdict(by, L, TOK_REF, TOK_SWEEP, TOK_SIMPLE, 'ПРИЗНАКИ ТОКЕНА НА F1 (v5.5, один BTC)',
                        "признаки окна F1 не нужны, вход F1 — как есть", "TOK_POOL = ['{win}'], MODE 'pool', JOB 'W1' / 'W2'")


def wave_verdict(by, L, ref_name, sweep, simple, title, closed, stage2):
    """v5.4-5.5: вердикт волны «один фактор против F1» по правилам этапа 1 (см. pyr_verdict / tok_verdict). closed —
       итог, если победителя нет; stage2 — подсказка этапа 2 ('{win}' — имя победителя)."""
    ref = _lab(ref_name, L)
    labs = {n_: _lab(n_, L) for n_ in sweep if _lab(n_, L) in by}
    if ref not in by or not labs:
        return None
    sweep_verdict(by, L, ref_name, sweep, title)
    sc = _sc_for(by, list(labs.values()) + [ref])
    seeds_ref = sorted(r['seed_key'] for r in by[ref])
    short = [f"{n_} ({','.join(sorted(r['seed_key'] for r in by[lab]))})" for n_, lab in labs.items()
             if sorted(r['seed_key'] for r in by[lab]) != seeds_ref]
    if short:
        print(f"   ⚠️ сиды не те же, что у эталона ({','.join(seeds_ref)}): {', '.join(short)} — вердикт по общим сидам")
    nulls = ('sflip1', 'sflip8', 'sflip16', 'sflip32')
    halves = [y_['part'] for y_ in (by[ref][0].get('years') or []) if len(y_['part']) == 5]

    def mean_cross(lab, n_):
        return _mean_of(by, lab, lambda r: (r.get('cross') or {}).get(n_, {}).get('auc'))

    def mean_half(lab, h_):
        return _mean_of(by, lab, lambda r: next((y_['auc'] for y_ in (r.get('years') or []) if y_['part'] == h_), None))

    print(f"\n   Δ к {ref_name}: TUNE и VAL — парно (среднее по сидам ± SE); против других нулевых (VAL) и по полугодиям — "
          f"разница средних AUC (справочно, не парно)")
    print(f"   {'вариант':<10} {'Δ TUNE':>16} {'Δ VAL':>16}  " + " ".join(f"{n_:>8}" for n_ in nulls) + "  "
          + " ".join(f"{h_:>6}" for h_ in halves))
    res = {}
    for n_, lab in labs.items():
        dt, st, nt = _seed_delta(by, sc, lab, ref, 'tune')
        dv, sv, nv = _seed_delta(by, sc, lab, ref, 'val')
        res[n_] = (dt, st, nt, dv, sv)
        prof = [mean_cross(lab, x_) - mean_cross(ref, x_) for x_ in nulls]
        hv = [mean_half(lab, h_) - mean_half(ref, h_) for h_ in halves]
        print(f"   {n_:<10} {_f(dt, '+.4f', width=8)}±{_f(st, '.4f', width=7)} {_f(dv, '+.4f', width=8)}±{_f(sv, '.4f', width=7)}  "
              + " ".join(_f(x_, '+.4f', width=8) for x_ in prof) + "  " + " ".join(_f(x_, '+.3f', width=6) for x_ in hv))
    helps = [n_ for n_, (dt, st, nt, _, _) in res.items() if nt and dt >= 2 * st]
    win = None
    if helps:
        best = max(helps, key=lambda n_: _mean_of(by, labs[n_], lambda r: r['tune']['auc']))
        band = [n_ for n_ in helps if n_ == best or (lambda d: d[2] and d[0] >= -d[1])(
            _seed_delta(by, sc, labs[n_], labs[best], 'tune'))]
        win = next(n_ for n_ in simple if n_ in band)
        print(f"   «помогает»: {', '.join(helps)}; лучший по TUNE — {best}; в полосе 1 SE от него — {', '.join(band)}; "
              f"самый простой — {win}")
    if win is None:
        print(f"   ❌ ни один вариант не помогает (Δ TUNE >= +2 SE): {closed}")
    elif res[win][3] > 0:
        print(f"   🏆 победитель этапа 1: {win} (Δ TUNE {res[win][0]:+.4f} ± {res[win][1]:.4f}, Δ VAL {res[win][3]:+.4f} ± "
              f"{res[win][4]:.4f}) — VAL подтверждает. Этап 2: " + stage2.format(win=win))
    else:
        print(f"   ❗ {win} помогает на TUNE, но VAL не подтверждает (Δ VAL {res[win][3]:+.4f}) — этапа 2 нет, решение за Фёдором")
        win = None
    return win


def pyr_summary():
    """v5.4, MODE 'pyr_sum': только вердикт пирамиды доходностей (без остальной сводки)."""
    by = {}
    for r in _load_runs():
        by.setdefault(r['label'], []).append(r)
    print(f"\n\n{'#' * 78}\n# SMC: ПИРАМИДА ДОХОДНОСТЕЙ (v5.4) | прогонов в {RUN_DIR}: {sum(len(v) for v in by.values())}\n{'#' * 78}")
    if _lab(PYR_REF, 64) not in by:
        print(f"⚠️ нет эталона {_lab(PYR_REF, 64)} (прогоны F1 волны 9) — сравнивать не с чем")
        return None
    if pyr_verdict(by, 64) is None and not any(_lab(n_, 64) in by for n_ in PYR_SWEEP):
        print("⚠️ прогонов пирамиды ещё нет (задания PYa / PYb / PYc)")
    return by


