    by = {}
    for r in _load_runs():
        by.setdefault(r['label'], []).append(r)
    print(f"\n\n{'#' * 78}\n# SMC: PINE-МОДЕЛЬ В БЮДЖЕТ ОДНОГО СКРИПТА (v6.3) | прогонов в {RUN_DIR}: {sum(len(v) for v in by.values())}\n{'#' * 78}")
