#   0. TrendyCoins_SMC_Data (пол сверен с FINAL / R1), здесь MODE 'check' — сверка torch с numpy.
#   1. Этап 1 (v3, закрыт): 'S1' / 'S2' / 'S3' — по сиду на консоль, оба L, вердикт этапа 1.
