#      PYR_SWEEP; эталон — прогоны F1 волны 9 (сиды a / b / c, те же окна и суррогаты — не пересчитываются). MODE 'pyr_sum' —
#      вердикт. Этап 2 (если по правилу есть победитель): PYR_POOL = [победитель], MODE 'pool', JOB 'V1' / 'V2' (набор C,
#      'stop', сиды a / b; эталон — F1 'stop' на C), потом MODE 'pool_sum' — раздел «пирамида на пуле».
#  14. Признаки токена (v5.5, F1 на одном BTC, SMC/data/ — без накладки): MODE 'check' (сверки признаков; старые F1 через
#      новый код — AUC как в json), затем MODE 'train', JOB 'TKa' / 'TKb' / 'TKc' — по сиду на консоль, 8 вариантов
#      TOK_SWEEP; эталон — прогоны F1 волны 9 (сиды a / b / c, не пересчитываются). MODE 'tok_sum' — вердикт. Этап 2 (если
#      по правилу есть победитель): TOK_POOL = [победитель], MODE 'pool', JOB 'W1' / 'W2', потом MODE 'pool_sum'.
#      Отдельно, по желанию (явно помеченный добор): PYR_V3 = True, MODE 'pool', JOB 'V3a' / 'V3b' — третий сид пирамиды
#      на пуле (F1 и PY_ms_h, сид c), потом MODE 'pool_sum' — то же правило на трёх сидах.
#  15. Диапазон бара (v5.6): СНАЧАЛА TrendyCoins_SMC_Range (DATA_DIR = SMC/data/, все 31 ассет пула; smc_series и smc_prices
#      не трогаются), здесь MODE 'check' (сверки диапазона; старые F1 — AUC как в json), затем MODE 'train', JOB 'RGa' /
#      'RGb' / 'RGc' — RG_den и RG по сиду на консоль; эталоны F1 и TK_den уже посчитаны. MODE 'rg_sum' — вердикт по правилу.
#      Принят — RG_POOL = ['RG_den'], MODE 'pool', JOB 'X1' / 'X2' (этап 2 и первый шаг пересчёта), MODE 'pool_sum'.
#  16. Добавки поверх RG_den (v5.7, SMC/data/ — без накладки; новых файлов данных не нужно): MODE 'check' (сверки положения close
#      и ориентации; старые RG_den — AUC как в json), затем MODE 'night', JOB 'RXa' / 'RXb' / 'RXc' — три консоли на ночь (этап 1
#      на BTC по сиду на консоль, потом пул: кандидаты 'stop' сидов a / b, F3_g, 'refit' RG_den). Утром — MODE 'rx_sum' и
#      MODE 'pool_sum' (в свежей консоли). Победитель с этапом 2 — новая F1 (POOL['recalc'] = [он], его 'refit', эпохи), иначе
#      пересчёт под RG_den: рецепт по 'pool_sum', свежие smc_range в накладку, боевое обучение.
#  17. Боевые модели (v5.8): в SMC/data_fresh/ у BTC и ETH — smc_range из тех же свежих CSV, что их smc_series / smc_prices
#      (TrendyCoins_SMC_Range: DATA_DIR = SMC/data_fresh/, ASSETS = BTCUSDT, ETHUSDT). Затем MODE 'chain' в одной консоли:
#      G1 ('refit' F3_g a / b) → pool_sum (рецепт и перенос калибровки F3_g) → T (боевое F3_g a / b / c; RUN_DIR/prod/).
#      По желанию — сайт: CHAIN = ['pool:U'] (боевое RG_den, рецепт уже подтверждён).
#  18. Модели без времени (v6.0, один BTC, SMC/data/ — без накладки): СНАЧАЛА TrendyCoins_SMC_Bars (DATA_DIR = SMC/data/,
#      ASSETS = BTCUSDT; smc_series / smc_prices / smc_range не трогаются), здесь MODE 'check' (файл баров, глубина 200 баров,
#      честность, правило ничьей; старые RG_den / F3_g через новый код — AUC как в json), затем MODE 'train', JOB 'NTa' /
#      'NTb' / 'NTc' — три консоли параллельно (сиды a / b / c, 17 вариантов NT1 / NT3 по важности, контроль C0_null_nt — в NTa).
#      Утром — MODE 'nt_sum' (в свежей консоли): выбор F1 и F3 по правилам и сравнение со старыми RG_den / F3_g.
#  19. F3 без времени в бой (v6.1): СНАЧАЛА TrendyCoins_SMC_Bars — все 31 ассет в SMC/data/ (старые CSV BTC / ETH) и BTC / ETH в
#      SMC/data_fresh/ (свежие CSV). Затем MODE 'pool', JOB 'NS1' / 'NS2' — две консоли параллельно ('stop' на C, сиды a / b), и
#      в свежей консоли MODE 'chain' (CHAIN: NS -> pool_sum -> NG -> pool_sum -> NP; уже посчитанные 'stop' пропускаются) — или
#      вся цепочка в одной консоли. Потом TrendyCoins_SMC_Pack — архив artifacts/ для репо и экспорта в Pine (Claude Code).
#  20. Поассетная калибровка (v6.2): MODE 'chain' (CHAIN: NR -> pool_sum) — 'refit' F3 без времени на ALL, сиды a / b, затем
#      TrendyCoins_SMC_Pack заново (архив с 'refit' на ALL).
#  21. Pine-модель в бюджет одного скрипта и линия M без калибровки по ассету (v6.3; SMC/data/ — без накладки, новых файлов
#      данных не нужно): MODE 'train', JOB 'PBa' / 'PBb' / 'PBc' — три консоли (сиды a / b / c, 10 вариантов PB_SWEEP; эталон
#      NT3_PRV_ch48 и NT3_PRV уже посчитаны, контроль — в PBa); в консоли PBa можно сразу MODE 'chain', CHAIN = ['train:PBa',
#      'nocal'] (линия M на нынешней NT3_PRV_ch48: прогоны NR, NG, NP уже есть). Волна 2 (8 вариантов не тяжелее победителя
#      волны 1): MODE 'train', JOB 'PB2a' / 'PB2b' / 'PB2c'. Потом MODE 'pb_sum' (свежая консоль; обе волны вместе) ->
#      PINE2 = победитель -> MODE 'chain',
#      CHAIN = ['pool:PBS', 'pool_sum', 'pool:PBG', 'pool:PBR', 'pool_sum', 'pool:PBP', 'nocal'] (боевое — накладка data_fresh, как
#      у NP). Затем TrendyCoins_SMC_Pack с новой моделью и json RUN_DIR/nocal/ -> экспорт (Claude Code).
#  22. Сеть видит направление (v6.7; SMC/data/ — без накладки, новых файлов данных не нужно): MODE 'train', JOB 'DRa' / 'DRb' / 'DRc'
#      — три консоли (сиды a / b / c: DR_anti, C0_mir, DR_free, DR_alin; контроль C0_null_dr — в DRa); эталоны SM_sym и NT1_PRV уже
#      посчитаны. Потом MODE 'dr_sum' — вердикт по правилам DR_RULES; этап 2 (гипотезы с направлением) — только если сводка нашла
#      асимметрию, отдельным ноутбуком.
CONTROLS =['C0_null', 'C0_shuf', 'C0_iid', 'B_frozen']      # один сид: от сида не зависят
SEEDED = ['B_mlp', 'B_simple', 'A0_concept', 'A1_base', 'A2_noclu', 'A3_frozen', 'A4_hiclu', 'A5_cos',
          'A6_ponly', 'A7_noreg', 'A8_lin', 'A11_amp', 'A12_Tfix']
STAGE1 = CONTROLS + SEEDED
KS_A2 = (16, 32, 64, 128, 256)             # этап 2: K у победителя этапа 1
KS_A5 = (32, 64, 128, 256)                 # этап 2: K у второго финалиста (гладкие формы)
FIT_RECENT = ('2022-01-01', '2023-07-01')  # обучение на свежей истории (TUNE с 2024-07-01)
SPARSE_K = (32, 128)                       # K в сравнении «разреженный токен против плотного»
IND_NAMES = ('M_drop', 'M_wide', 'M_deep', 'M_steps', 'C_dil', 'C_dil64')   # кандидаты модели индикатора
TOPK = (0, 4, 2, 1)                        # 0 — плотное P; k — только k ближайших форм
HOLD_H = 5                                 # v4.2: откладывается каждая 5-я неделя FIT (~17% окон FIT в проверку)
WIN_PROBE = (32, 64, 128)                  # v4.2: длина окна у C_dil — справочно (L для индикатора — 64)


def _sparse_items(seed):
    items = [('A2_noclu', {'L': 64, 'K': K}, seed) for K in SPARSE_K]
    for K in SPARSE_K:
        for k in TOPK:
            items.append(('A13_amp', {'L': 64, 'K': K, **({'p_topk': k} if k else {})}, seed))
    return items


def _round5_items(seed):
    """v4.2, раунд 5 (модель индикатора), в порядке важности: эталоны; «запоминание или дрейф»; свип
       CNN (против запоминания, устройство, смеси); свип MLP на шагах; трансформер; длина окна
       (справочно). Уже посчитанные прогоны (C_dil, M_steps сидов a / b) пропускаются."""
    L64 = {'L': 64}
    items = [('C_dil', L64, seed), ('M_steps', L64, seed)]
    items += [('C_dil', {'L': 64, 'fit_holdout': HOLD_H}, seed),
              ('M_steps', {'L': 64, 'fit_holdout': HOLD_H}, seed),
              ('A2_noclu', {'L': 64, 'K': 128, 'fit_holdout': HOLD_H}, seed)]
    items += [(n, L64, seed) for n in CNN_SWEEP]
    items += [(n, L64, seed) for n in MLP_SWEEP]
    items += [('X_attn', L64, seed)]
    items += [('C_dil', {'L': L_}, seed) for L_ in WIN_PROBE if L_ != 64]
    return items


def _round7_items(seed):
    """v4.4, волна 7, в порядке важности: дообучение на FIT + TUNE (и контроль с тем же расписанием на
       одном FIT); боковые входы; шейплеты. Сиды d / e чемпиона — в R7a / R7b отдельно."""
    L64 = {'L': 64}
    items = [(n, L64, seed) for n in W7_REFIT]
    items += [(n, L64, seed) for n in W7_SIDE]
    items += [(n, L64, seed) for n in W7_SHP]
    return items


def _round8_items(seed):
    """v4.5, волна 8, в порядке важности: цены бара; боковые входы; дешёвые в Pine модели с боковыми входами.
       Сиды d / e чемпиона — в R8a / R8b, демонстрация и контроль цены бара — в R8c."""
    L64 = {'L': 64}
    items = [(n, L64, seed) for n in W8_PRICE]
    items += [(n, L64, seed) for n in W8_SIDE]
    items += [(n, L64, seed) for n in list(W8_STREAM) + list(W8_SHP)]
    return items


W9_CORE = ['C3_ctx', 'C3_ctxp', 'C3_ctx_mc', 'C3_ctxp_mc', 'C3_ctx_hlc3', 'C3_ctxp_hlc3', 'C3_ctx4',
           'C3_ctx_hl2', 'C3_ctxp_hl2', 'C3_stream_ctxp', 'S_ctxp', 'C3_stream_ctxp_mc']       # 5 сидов, по важности
W9_MORE = ['C3_stream_ctx', 'S_ctx', 'C3_ctxL', 'C3_ctxD', 'C3_ctx_ch64', 'C3_ctxp_h2', 'C3_ctxp_mc_ch64',
           'C3_ctxp_b8k', 'C3_ctxp_b16k']
W9_EXTRA = list(W9_CORE)                        # лишние сиды f / g / h ядра (по одному на консоль) — в конце очереди
W9_LONG = [('C3_ctxp', 96), ('C3_ctxp', 128), ('C3_ctxp_mc', 128), ('C3_stream_ctxp', 128)]   # справочно


def _round9_items(seed, core2=None, long_seeds=None, extra_seed=None):
    """v4.6, волна 9 (финальная): ядро (5 сидов: свой сид консоли + второй core2); 3 сида (a / b / c): Pine с простым
       прошлым, разбор прошлого, ёмкость, дообучение на FIT + TUNE, «запоминание или дрейф» у C3_ctxp, длина окна
       (справочно; long_seeds — чьи сиды длинных окон считает эта консоль)."""
    L64 = {'L': 64}
    items = [(n, L64, seed) for n in W9_CORE]
    if core2:
        items += [(n, L64, core2) for n in W9_CORE]
    items += [(n, L64, seed) for n in W9_MORE]
    items += [(n, L64, seed) for n in W9_REFIT]
    items += [('C3_ctxp', {'L': 64, 'fit_holdout': HOLD_H}, seed),
              ('C3_ctxp', {'L': 64, 'fit_holdout': HOLD_H, 'hold_block': 13}, seed)]
    for s_ in (long_seeds or []):
        items += [(n, {'L': L_}, s_) for n, L_ in W9_LONG]
    if extra_seed:
        items += [(n, L64, extra_seed) for n in W9_EXTRA]
    return items


def _round6_items(seed):
    """v4.3, раунд 6, в порядке важности: время — отложенные недели и кварталы у чемпиона; доводка
       чемпиона; точный счёт в Pine; сглаженный вход; вес свежей истории; длина окна (справочно);
       формы-шейплеты; два банка прототипов. C_cdrop3 (сиды a / b / c) уже посчитан — пропуск."""
    L64 = {'L': 64}
    items = [('C_cdrop3', L64, seed),
             ('C_cdrop3', {'L': 64, 'fit_holdout': HOLD_H}, seed),
             ('C_cdrop3', {'L': 64, 'fit_holdout': HOLD_H, 'hold_block': 13}, seed)]
    items += [(n, L64, seed) for n in C3_SWEEP]
    items += [('C_cdrop3', {'L': L_}, seed) for L_ in (96, 128)]
    items += [(n, L64, seed) for n in ('S_shp16', 'S_shp32', 'S_shp16k')]
    items += [('A2_noclu', {'L': 64, 'K': 128}, seed),
              ('A1_base', {'L': 64, 'K': 128, 'reinit_dead': False}, seed),
              ('A14_bank2', {'L': 64, 'K': 128}, seed),
              ('A15_route', {'L': 64, 'K': 128}, seed)]
    return items


JOBS = {
    # этап 1 (v3): три консоли параллельно, в каждой свой сид
    'S1': [(n, {'L': L}, 'a') for L in (32, 64) for n in STAGE1],
    'S2': ([(n, {'L': L}, 'b') for L in (32, 64) for n in SEEDED]
           + [('A1_base', {'L': 32, 'K': 16}, 'a'), ('A10_finalfrozen', {'L': 64}, 'a'),
              ('A9_finalinit', {'L': 64}, 'a')]),
    'S3': [(n, {'L': L}, 'c') for L in (32, 64) for n in SEEDED],
    # этапы 2-3 (v4): разреженный токен против плотного, по сиду на консоль
    'T1': _sparse_items('a'),
    'T2': _sparse_items('b'),
    # подробный свип K (после T1 / T2)
    'K1': ([('A2_noclu', {'L': 64, 'K': K}, 'a') for K in KS_A2]
           + [('A5_cos', {'L': 64, 'K': K}, 'a') for K in KS_A5]),
    'K2': ([('A2_noclu', {'L': 64, 'K': K}, 'b') for K in KS_A2]
           + [('A5_cos', {'L': 64, 'K': K}, 'b') for K in KS_A5]),
    # базовые линии и свежая история (v4)
    'D1': ([('B_frozen', {'L': 64}, 'a')]
           + [('B_simple', {'L': 64}, s_) for s_ in ('a', 'b')]
           + [('B_ladder', {'L': 64}, s_) for s_ in ('a', 'b', 'c')]
           + [('B_mlp', {'L': 64}, s_) for s_ in ('a', 'b')]
           + [('A2_noclu', {'L': 64, 'fit_from': FIT_RECENT[0]}, s_) for s_ in ('a', 'b')]
           + [('A2_noclu', {'L': 64, 'fit_from': FIT_RECENT[1]}, 'a'),
              ('B_mlp', {'L': 64, 'fit_from': FIT_RECENT[0]}, 'a')]
           + [('A5_cos', {'L': 64, 'K': 128, **({'p_topk': k} if k else {})}, s_) for k in (0, 4)
              for s_ in ('a', 'b')]),
    # модель индикатора (v4.1)
    'I1': [(n, {'L': 64}, 'a') for n in IND_NAMES],
    'I2': [(n, {'L': 64}, 'b') for n in IND_NAMES],
    # F1: K=256 и «рождение форм»: старт из k-means / шума / случайного блуждания / случайных реальных
    # окон; переезд пустых форм на реальные окна выключен у всех четырёх, иначе «шум» тут же
    # подменяется реальными окнами и опыт перестаёт быть чистым
    'F1': ([('A2_noclu', {'L': 64, 'K': 256}, s_) for s_ in ('a', 'b')]
           + [('A2_noclu', {'L': 64, 'K': 128, 'reinit_dead': False, **({'init': ini} if ini != 'kmeans' else {})}, s_)
              for ini in ('kmeans', 'noise', 'randwalk', 'sample') for s_ in ('a', 'b')]),
    # этап 3 (v4): нулевая обучения
    'N1': [(n, {'L': 64, 'null': nl}, s_) for nl in ('sflip16', 'sflip32') for n in ('A2_noclu', 'B_mlp')
           for s_ in ('a', 'b')],
    # раунд 5 (v4.2): свип модели индикатора, по сиду на консоль
    'R1': _round5_items('a'),
    'R2': _round5_items('b'),
    'R3': _round5_items('c'),
    # раунд 6 (v4.3): время, доводка чемпиона, Pine, шейплеты, два банка — по сиду на консоль
    'R6a': _round6_items('a'),
    'R6b': _round6_items('b'),
    'R6c': _round6_items('c'),
    # волна 7 (v4.4): FIT + TUNE, боковые входы, шейплеты; сиды d / e чемпиона и C_cdrop3
    'R7a': _round7_items('a') + [('C3_hl2', {'L': 64}, 'd'), ('C_cdrop3', {'L': 64}, 'd')],
    'R7b': _round7_items('b') + [('C3_hl2', {'L': 64}, 'e'), ('C_cdrop3', {'L': 64}, 'e')],
    'R7c': _round7_items('c'),
    # волна 8 (v4.5): цены бара, боковые входы, дешёвые в Pine модели; сиды d / e C3_side; демонстрация и контроль
    'R8a': _round8_items('a') + [('C3_side', {'L': 64}, 'd')],
    'R8b': _round8_items('b') + [('C3_side', {'L': 64}, 'e')],
    'R8c': _round8_items('c') + [(n, {'L': 64}, 'a') for n in W8_DEMO],
    # волна 9 (v4.6, финальная): ядро — 5 сидов, остальное — 3 сида; длинные окна (справочно): сид b — в R9a, a / c — в R9c
    'R9a': _round9_items('a', core2='d', long_seeds=('b',), extra_seed='f'),
    'R9b': _round9_items('b', core2='e', extra_seed='g'),
    'R9c': [('C0_null_mc', {'L': 64}, 'a')] + _round9_items('c', long_seeds=('c', 'a'), extra_seed='h'),
    # v5.4, пирамида доходностей на F1 (один BTC): по сиду на консоль; эталон F1 (сиды a / b / c) уже посчитан в волне 9
    'PYa': [(n, {'L': 64}, 'a') for n in PYR_SWEEP],
    'PYb': [(n, {'L': 64}, 'b') for n in PYR_SWEEP],
    'PYc': [(n, {'L': 64}, 'c') for n in PYR_SWEEP],
    # v5.5, признаки токена на F1 (один BTC): по сиду на консоль; эталон F1 (сиды a / b / c) уже посчитан в волне 9
    'TKa': [(n, {'L': 64}, 'a') for n in TOK_SWEEP],
    'TKb': [(n, {'L': 64}, 'b') for n in TOK_SWEEP],
    'TKc': [(n, {'L': 64}, 'c') for n in TOK_SWEEP],
    # v5.6, диапазон бара (один BTC): по сиду на консоль; эталоны F1 (волна 9) и TK_den (TKa / TKb / TKc) уже посчитаны
    'RGa': [(n, {'L': 64}, 'a') for n in RG_SWEEP],
    'RGb': [(n, {'L': 64}, 'b') for n in RG_SWEEP],
    'RGc': [(n, {'L': 64}, 'c') for n in RG_SWEEP],
    # v5.7, точечные добавки поверх RG_den (один BTC), по сиду на консоль, по важности: кандидаты, Pine (F3 + диапазон),
    # [контроль и «мешок баров» — один сид, в RXa], ёмкость (справочно). Эталоны RG_den и F3 (сиды a / b / c) уже посчитаны.
    # MODE 'night': после этой очереди консоль сама идёт в POOL_JOBS с тем же именем (этап 2 заранее)
    'RXa': ([(n, {'L': 64}, 'a') for n in list(RX_SWEEP) + list(RX_PINE)] + [('C0_null_rx', {'L': 64}, 'a')]
            + [(n, {'L': 64}, 'a') for n in list(RX_BAG) + list(RX_CAP)]),
    'RXb': [(n, {'L': 64}, 'b') for n in list(RX_SWEEP) + list(RX_PINE) + list(RX_CAP)],
    'RXc': [(n, {'L': 64}, 'c') for n in list(RX_SWEEP) + list(RX_PINE) + list(RX_CAP)],
    # v6.0, модели без времени (один BTC): по сиду на консоль, очередь по важности; контроль — в NTa после главных вариантов
    'NTa': ([(n, {'L': 64}, 'a') for n in NT_ORDER[:6]] + [('C0_null_nt', {'L': 64}, 'a')]
            + [(n, {'L': 64}, 'a') for n in NT_ORDER[6:]]),
    'NTb': [(n, {'L': 64}, 'b') for n in NT_ORDER],
    'NTc': [(n, {'L': 64}, 'c') for n in NT_ORDER],
    # v6.3, Pine-модель в бюджет одного скрипта (один BTC): по сиду на консоль, очередь по важности; контроль — в PBa после
    # первых четырёх. NT3_PRV_ch48 (эталон) и NT3_PRV уже посчитаны (NTa / NTb / NTc)
    'PBa': ([(n, {'L': 64}, 'a') for n in PB_ORDER[:4]] + [('C0_null_pb', {'L': 64}, 'a')]
            + [(n, {'L': 64}, 'a') for n in PB_ORDER[4:]]),
    'PBb': [(n, {'L': 64}, 'b') for n in PB_ORDER],
    'PBc': [(n, {'L': 64}, 'c') for n in PB_ORDER],
    # v6.3, волна 2 Pine-модели (один BTC): по сиду на консоль, очередь по важности; волна 1 и контроль уже посчитаны
    'PB2a': [(n, {'L': 64}, 'a') for n in PB2_SWEEP],
    'PB2b': [(n, {'L': 64}, 'b') for n in PB2_SWEEP],
    'PB2c': [(n, {'L': 64}, 'c') for n in PB2_SWEEP],
    # v6.4, гладкость линии F1 (один BTC): по сиду на консоль, очередь по важности; контроль — в SMa после первых трёх. Эталон
    # NT1_PRV (сиды a / b / c) уже посчитан (NTa / NTb / NTc)
    'SMa': ([(n, {'L': 64}, 'a') for n in SM_ORDER[:3]] + [('C0_null_sm', {'L': 64}, 'a')]
            + [(n, {'L': 64}, 'a') for n in SM_ORDER[3:]]),
    'SMb': [(n, {'L': 64}, 'b') for n in SM_ORDER],
    'SMc': [(n, {'L': 64}, 'c') for n in SM_ORDER],
    # v6.5, исправленный штраф скачков поверх SM_sym (один BTC): по сиду на консоль; контроль — в SPa после первых двух. Эталон
    # SM_sym (сиды a / b / c) уже посчитан (SMa / SMb / SMc)
    'SPa': ([(n, {'L': 64}, 'a') for n in SP_ORDER[:2]] + [('C0_null_sp', {'L': 64}, 'a')]
            + [(n, {'L': 64}, 'a') for n in SP_ORDER[2:]]),
    'SPb': [(n, {'L': 64}, 'b') for n in SP_ORDER],
    'SPc': [(n, {'L': 64}, 'c') for n in SP_ORDER],
    # v6.7, сеть видит направление (один BTC): по сиду на консоль, очередь по важности; контроль «суррогат против суррогата» — в DRa
    # после первых двух. Эталоны SM_sym и NT1_PRV (сиды a / b / c) уже посчитаны (SMa / SMb / SMc, NTa / NTb / NTc)
    'DRa': ([(n, {'L': 64, **DR_OVER}, 'a') for n in DR_ORDER[:2]] + [('C0_null_dr', {'L': 64, **DR_OVER}, 'a')]
            + [(n, {'L': 64, **DR_OVER}, 'a') for n in DR_ORDER[2:]]),
    'DRb': [(n, {'L': 64, **DR_OVER}, 'b') for n in DR_ORDER],
    'DRc': [(n, {'L': 64, **DR_OVER}, 'c') for n in DR_ORDER],
}

