# (посчитано 2026-10-07: CHAIN = ['pool:NS', 'pool_sum', 'pool:NG', 'pool_sum', 'pool:NP'])
# v6.2: источник поассетной калибровки — 'refit' Pine-модели на ALL, сиды a / b, затем сводка (раздел (5з))
