# прогоны из RUN_DIR/pool/ и RUN_DIR/prod/: 'refit' на ALL a / b (задание NR), 'refit' на C a / b (NG), боевые a / b / c (NP);
# новых прогонов не нужно. Потом MODE 'pb_sum', PINE2 = победитель и этап 2 ('nocal' в конце — уже на итоговой модели)
# (посчитано 2026-10-17: CHAIN = ['pool_sum', 'pool:PBG', 'pool:PBR', 'pool_sum', 'pool:PBP', 'nocal'])
# v6.4, гладкость линии F1: все три консоли — MODE 'chain'; консоль 1 — CHAIN как ниже (разбор уже посчитанных моделей на
# CPU-части, волна SMa, основа этапа 2 на пуле), консоль 2 — ['train:SMb', 'pool:SMS2'], консоль 3 — ['train:SMc', 'pool:SMS3']
# (пока SM_WIN = None, в SMS1-3 только NT1_PRV и NT1_PRV_d1 — правило dropout от волны SM не зависит). Потом MODE 'sm_sum'
# (вердикт волны; хватает CPU), SM_WIN = победитель, MODE 'pool', JOB 'SMS1' / 'SMS2' / 'SMS3' (посчитанное пропускается) и снова
# MODE 'sm_sum' (этап 2)
