# (посчитано 2026-10-20: SP — MODE 'train', JOB 'SPa' / 'SPb'; SM_sym_d1 и SP_l025_d1 на пуле — SMX / SPS1 / SPS2)
# v6.6, F1 для сайта: 1) три консоли MODE 'pool' — JOB 'F1G1', 'F1G2', 'F1R1' (F1R2 — на консоли, что освободится первой);
