# в свежей консоли (хватает CPU). Или в консоли DRa сразу MODE 'chain', CHAIN = ['train:DRa', 'dr_sum'] (сводка увидит только то, что
# уже есть на Drive у этой консоли)
CHAIN = ['train:DRa', 'dr_sum']
ONE = ('A1_base', {'L': 32}, 'a')   # для 'one'
FORCE = False           # False — уже посчитанные прогоны (есть json этой версии) пропускаются
MODE = os.environ.get('SMC_MODE', MODE)     # переопределение для стенда вне Colab
JOB = os.environ.get('SMC_JOB', JOB)

def chain_mode(steps):
    """v5.8, MODE 'chain': шаги по порядку в одной консоли — 'pool:<JOB>' (run_pool_job), 'pool_sum' (сводка пула),
       'train:<JOB>' (run_job); v6.3: 'pb_sum' (вердикт этапа 1 Pine-модели), 'nocal' (проверка линии M без калибровки по ассету);
       v6.4: 'sm_sum' (гладкость линии: разбор готовых моделей, вердикты волны SM); v6.7: 'dr_sum' (сеть видит направление).
       Одна консоль видит свои файлы Drive сразу: сводка видит только что посчитанные прогоны, а
       ворота боевого обучения — только что записанную сводку. До первого шага — проверка заданий и накладки свежих данных
       боевых шагов (чтобы не узнать о недостающем smc_range через час). Ошибка шага (например, рецепт не подтверждён и
       ворота боевого обучения закрыты) останавливает цепочку; уже посчитанные прогоны при повторном запуске пропускаются."""
    t0 = time.time()
    print(f"⛓️ ЦЕПОЧКА: {' → '.join(steps)}")
    for step in steps:                               # предпроверка
        kind, _, job = step.partition(':')
        if kind == 'pool':
            if job not in POOL_JOBS:
                raise KeyError(f"🍆 АЙ, ОШИБКА! шаг '{step}': нет задания '{job}' в POOL_JOBS")
            its = _pool_items(job, resolve=False)    # v6.3: итог этапа 2 (PB_FINAL_KEY) станет известен по ходу цепочки
            for p_ in dict.fromkeys(_pool_price(m_) for _, _, m_, mo_ in its if mo_ == 'prod'):
                prod_overlay(p_, bars=any(_pool_nt_cols(m_) for _, _, m_, mo_ in its
                                          if mo_ == 'prod' and _pool_price(m_) == p_))     # v6.1: + smc_bars
        elif kind == 'train' and job not in JOBS:
            raise KeyError(f"🍆 АЙ, ОШИБКА! шаг '{step}': нет задания '{job}' в JOBS")
        elif kind not in ('pool', 'pool_sum', 'train', 'pb_sum', 'nocal', 'sm_sum', 'dr_sum'):
            raise ValueError(f"🍆 АЙ, ОШИБКА! шаг '{step}' — есть 'pool:<JOB>', 'pool_sum', 'train:<JOB>', 'pb_sum', 'nocal', 'sm_sum', "
                             f"'dr_sum'")
    for i, step in enumerate(steps, 1):
        kind, _, job = step.partition(':')
        print(f"\n\n{'⛓️ ' * 3}ШАГ {i}/{len(steps)}: {step} | {(time.time() - t0) / 60:.0f} мин от начала")
        try:
            if kind == 'pool':
                run_pool_job(job)
            elif kind == 'pool_sum':
                pool_summary()
            elif kind == 'pb_sum':                   # v6.3: вердикт этапа 1 Pine-модели (прогоны BTC)
                pb_summary()
            elif kind == 'nocal':                    # v6.3: проверка линии M без калибровки по ассету
                nocal_check()
            elif kind == 'sm_sum':                   # v6.4: гладкость линии — разбор готовых моделей и вердикты волны SM
                sm_summary()
            elif kind == 'dr_sum':                   # v6.7: сеть видит направление — вердикт волны DR
                dr_summary()
            else:
                run_job(job, JOBS[job])
        except Exception as e:
            print(f"\n🍆 АЙ, ОШИБКА! шаг {step}: {type(e).__name__}: {e}\n⛔ цепочка остановлена: следующие шаги не запускались")
            traceback.print_exc(file=sys.stdout)
            return False
        gc.collect()
        if DEVICE.type == 'cuda':
            torch.cuda.empty_cache()
    print(f"\n⛓️ ЦЕПОЧКА ГОТОВА: {len(steps)} шагов | {(time.time() - t0) / 60:.0f} мин")
    return True


def figs_mode():
    """Дорисовать extremes.png (и у CNN — cnn_forms.png) всем прогонам этой версии, у которых их нет."""
    datas, stores, n = {}, {}, 0
    for r in _load_runs():
        try:
            n += bool(backfill_extremes(r, datas, stores))
            n += bool(backfill_cnn_forms(r, datas, stores))
        except Exception as e:
            print(f"🍆 АЙ, ОШИБКА! {r.get('tag')}: {type(e).__name__}: {e}")
    print(f"🖼️ дорисовано рисунков: {n}")


if MODE not in ('check', 'train', 'one', 'sum', 'figs', 'core', 'pool', 'pool_sum', 'pyr_sum', 'tok_sum', 'rg_sum',
                'night', 'rx_sum', 'chain', 'nt_sum', 'pb_sum', 'nocal', 'sm_sum', 'dr_sum', 'none'):
    print(f"🍆 АЙ, ОШИБКА! неизвестный MODE '{MODE}'")
elif MODE != 'none':
    stamp = time.strftime('%Y%m%d_%H%M%S')
    log_path = RUN_DIR + f"logs/smc_{MODE}_{JOB if MODE in ('train', 'pool', 'night') else ''}_{stamp}.log"
    with tee_to(log_path):
        print(f"🗒️ лог: {log_path}")
        if MODE == 'check':
            check_mode(load_data())
        elif MODE == 'train':
            run_job(JOB, JOBS[JOB])
        elif MODE == 'one':
            run_job('one', [ONE])
        elif MODE == 'figs':
            figs_mode()
        elif MODE == 'core':
            core_check()
        elif MODE == 'pool':
            run_pool_job(JOB)
        elif MODE == 'pool_sum':
            pool_summary()
        elif MODE == 'pyr_sum':
            pyr_summary()
        elif MODE == 'tok_sum':
            tok_summary()
        elif MODE == 'rg_sum':
            rg_summary()
        elif MODE == 'night':                       # v5.7: этап 1 на BTC, потом пул — одна консоль на всю ночь
            run_job(JOB, JOBS[JOB])
            gc.collect()
            if DEVICE.type == 'cuda':
                torch.cuda.empty_cache()
            if JOB in POOL_JOBS:
                run_pool_job(JOB)
        elif MODE == 'rx_sum':
            rx_summary()
        elif MODE == 'chain':                       # v5.8: шаги CHAIN по порядку в одной консоли
            chain_mode(CHAIN)
        elif MODE == 'nt_sum':                      # v6.0: модели без времени
            nt_summary()
        elif MODE == 'pb_sum':                      # v6.3: Pine-модель в бюджет одного скрипта
            pb_summary()
        elif MODE == 'nocal':                       # v6.3: линия M без калибровки по ассету
            nocal_check()
        elif MODE == 'sm_sum':                      # v6.4: гладкость линии — разбор готовых моделей и вердикты волны SM
            sm_summary()
        elif MODE == 'dr_sum':                      # v6.7: сеть видит направление — вердикт волны DR
            dr_summary()
        else:
            summary()
    if IN_COLAB and MODE in ('train', 'one', 'figs', 'core', 'pool', 'pool_sum', 'sum', 'pyr_sum', 'tok_sum', 'rg_sum',
                             'night', 'rx_sum', 'chain', 'nt_sum', 'pb_sum', 'nocal', 'sm_sum', 'dr_sum'):
        try:                                         # v5.1: всё записанное этой консолью — на Drive до закрытия runtime
            drive.flush_and_unmount()
            print("☁️ Drive: записи выгружены (flush_and_unmount); для новой работы в этой консоли — запусти скрипт заново")
        except Exception as e:
            print(f"⚠️ Drive: flush_and_unmount не прошёл ({type(e).__name__}: {e}) — проверь файлы на Drive до закрытия консоли")